prompt --application/shared_components/logic/application_processes/session
begin
wwv_flow_api.create_flow_process(
 p_id=>wwv_flow_api.id(209363611069357751608)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SESSION'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'CURSOR C_THEME IS',
'SELECT S.NAME, S.THEME_STYLE_ID',
'  FROM APEX_APPLICATION_THEME_STYLES S, APEX_APPLICATION_THEMES T',
' WHERE S.APPLICATION_ID = T.APPLICATION_ID',
'   AND S.THEME_NUMBER = T.THEME_NUMBER',
'   AND S.APPLICATION_ID = :app_id',
'   AND T.UI_TYPE_NAME = ''DESKTOP''',
'   AND ((upper(S.NAME) = ''VITA (NATCORP)'' AND :P_PAINEL = ''PO'') OR ',
'        (upper(S.NAME) = ''VITA (NATCORP)'' AND :P_PAINEL = ''PG'') OR',
'        (upper(S.NAME) = ''VITA (NATCORP)'' AND :P_PAINEL = ''PC''));',
'        ',
'v_theme c_theme%rowtype;',
'',
'BEGIN',
'',
'BEGIN',
'PKG_APEX.prc_inicio (:app_id,',
'                     :app_page_id,',
'                     NULL,',
'                     :p_base,',
'                     :p_usuario,',
'                     :p_painel,',
'                     :p_titulo,',
'                     :p_dispositivo,',
'                     :p_browser);',
'                      ',
'pkg_apex.prc_usuario (:p_painel,',
'                      :p_modulo,',
'                      :p_usuario,',
'                      :p_empresa_user,',
'                      :p_matricula_user,',
'                      :p_ccusto_user,',
'                      :p_perfil);',
'',
'END;',
'',
'   IF :P_PAINEL IS NOT NULL THEN',
'',
'    open c_theme;',
'    fetch c_theme into v_theme;',
'    close c_theme;',
'    ',
'    BEGIN',
'    apex_theme.set_user_style(',
'    p_application_id => :APP_ID,',
'    p_USER => :APP_USER,',
'    p_THEME_NUMBER => 42,',
'    P_ID => v_theme.THEME_STYLE_ID',
'    );',
'    END;',
'    ',
'   END IF;',
'',
'END;'))
);
end;
/
