prompt --application/shared_components/security/authentications/auth_natcorp
begin
wwv_flow_api.create_authentication(
 p_id=>wwv_flow_api.id(208498584232019240616)
,p_name=>'Auth Natcorp'
,p_scheme_type=>'PLUGIN_BR.COM.NATCORP.AUTH'
,p_attribute_01=>'P900_OK'
,p_attribute_02=>'P900_BUSCA_USER'
,p_attribute_03=>'P_EMPRESA_USER'
,p_attribute_04=>'P_MATRICULA_USER'
,p_attribute_05=>'P_USUARIO'
,p_attribute_06=>'P_SEQUENCIA'
,p_attribute_07=>'P_PAINEL'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'PROCEDURE POST_LOGIN IS',
'',
' cursor c_gestor is',
' select distinct ''S'' existe',
'   from apex_programas_acesso',
'  where usuario = :p_usuario',
'    and modulo is not null',
'    and substr(app_id,1,1) = 1 -- Gestor',
'    and app_page_number <> 1',
'    and acesso = ''S'';',
' ',
' v_gestor c_gestor%rowtype;',
' ',
' cursor c_oper is',
' select distinct ''S'' existe',
'   from apex_programas_acesso',
'  where usuario = :p_usuario',
'    and modulo is not null',
'    and substr(app_id,1,1) = 2 -- Operador',
'    and app_page_number <> 1',
'    and acesso = ''S'';',
'    ',
' v_oper c_oper%rowtype;',
' ',
'begin',
'',
'open c_gestor;',
'fetch c_gestor into v_gestor;',
'close c_gestor;',
'',
'open c_oper;',
'fetch c_oper into v_oper;',
'close c_oper;',
'',
'if v_gestor.existe = ''S'' and v_oper.existe = ''S'' then',
'--faz pergunta',
'null;',
'elsif v_gestor.existe = ''S'' and nvl(v_oper.existe,''N'') = ''N'' then',
':p_painel := ''PG'';',
'elsif nvl(v_gestor.existe,''N'') = ''N'' and v_oper.existe = ''S'' then',
':p_painel := ''PO'';',
'end if;',
'',
'end;'))
,p_cookie_name=>'APPNATCORP'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
);
end;
