prompt --application/shared_components/plugins/dynamic_action/br_com_natcorp_reports
begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(203157155000372244508)
,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'BR.COM.NATCORP.REPORTS'
,p_display_name=>'Natcorp Execute Reports'
,p_category=>'EXECUTE'
,p_supported_ui_types=>'DESKTOP'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('DYNAMIC ACTION','BR.COM.NATCORP.REPORTS'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'procedure download_blob(p_url      in varchar2',
'                       ,p_mimetype out varchar2',
'                       ,p_blob     out blob) is',
'  v_blobref     blob := empty_blob();',
'  v_request     utl_http.req;',
'  v_response    utl_http.resp;',
'  v_data        raw(32767);',
'begin',
'  dbms_lob.createTemporary(v_blobref, TRUE);',
'  utl_http.set_transfer_timeout(1200); -- em segundos',
'',
'  v_request  := utl_http.begin_request(/*utl_url.escape(*/p_url/*)*/); -- Comentado por Igor Cardoso 24/09/2019, Aparecendo caracteres em texto no Report.',
'  v_response := utl_http.get_response(v_request);',
'',
'  utl_http.get_header_by_name(v_response, ''Content-Type'', p_mimetype);',
'  if instr(p_mimetype, '';'') > 0 then',
'    p_mimetype := nvl(substr(p_mimetype, 1, instr(p_mimetype, '';'') - 1), ''application/octet-stream'');',
'  end if;',
'',
'  begin',
'    loop',
'      utl_http.read_raw(v_response, v_data, 32767);',
'      dbms_lob.writeAppend(lob_loc => v_blobref, amount => utl_raw.length(v_data), buffer => v_data);',
'    end loop;',
'  exception',
'    when utl_http.end_of_body then',
'      utl_http.end_response(v_response);',
'    when others then',
'      utl_tcp.close_all_connections;',
'  end;',
'',
'  p_blob := v_blobref;',
'  dbms_lob.freetemporary(v_blobref);',
'end download_blob;',
'',
'procedure call_report(p_relatorio in varchar2',
'                     ,p_blob     out blob',
'                     ,p_mimetype out varchar2',
'                     ,p_parametro in varchar2 default null',
'                     ,p_formato   in varchar2 default ''pdf'' -- pdf / excel (csv) / csv (texto) / excellarge',
'                     ,p_destype   in varchar2 default ''cache''',
'                     ,p_desname   in varchar2 default null',
'                     ) is',
'  l_reportURL  varchar2(4000);',
'  l_url        varchar2(255);',
'  l_path       configuracoes.ver11g_caminho_rdf%type;',
'  l_datasource configuracoes.datasource_reports%type;',
'begin',
'  --if lower(p_formato) not in (''pdf'', ''excel'', ''csv'', ''excellarge'') then',
'  --  raise_application_error(-20051, ''Formato '' || p_formato || '' invalido.'');',
'  --end if;',
'',
'  begin',
'    select apex_caminho_report || ''reports/rwservlet'',',
'           case when instr(upper(p_relatorio), ''.REP'') > 0 then ver11g_caminho_rdf end,',
'           nvl(datasource_reports, sys_context(''USERENV'', ''SESSION_SCHEMA''))',
'      into l_url,',
'           l_path,',
'           l_datasource',
'      from configuracoes;',
'  exception when others then null;',
'  end;',
'  l_reportURL := l_url || ''?'' || l_datasource',
'              || chr(38) || ''destype=''||nvl(p_destype,''cache'') --''cache''',
'              || chr(38) || ''desname=''||p_desname',
'              || chr(38) || ''paramform=no''',
'              || chr(38) || ''report='' || l_path || p_relatorio',
'              || chr(38) || ''desformat='' || case lower(p_formato)',
'                                              when ''excel'' then',
'                                                ''delimited''',
'                                                || chr(38) || ''delimiter=;''',
'                                                --|| chr(38) || ''cellwrapper="'' -- da erro por bug 397279.1 do reports',
'                                              when ''excellarge'' then',
'                                                ''delimiteddata''',
'                                                || chr(38) || ''delimiter=;''',
'                                              when ''csv'' then',
'                                                ''texto999''',
'                                                || chr(38) || ''mode=character''',
'                                              else lower(p_formato)',
'                                            end',
'              || case when length(p_parametro) > 0 then',
'                   chr(38) || utl_url.escape(p_parametro, false, ''UTF-8'')',
'                 end;',
'  apex_debug.message(''URL: %s'', l_reportURL);',
'  download_blob(l_reportURL, p_mimetype, p_blob);',
'end call_report;',
'',
'function blob2clob(plob in blob) return clob is',
'	l_clob_result  clob    := ''x'';',
'	l_dest_offsset integer := 1;',
'	l_src_offsset  integer := 1;',
'	l_lang_context integer := dbms_lob.default_lang_ctx;',
'	l_warning  	   integer;',
'begin',
'	if plob is not null and length(plob) > 0 then',
'  	dbms_lob.converttoclob(dest_lob 	  => l_clob_result',
'                        	,src_blob 	  => plob',
'                        	,amount   	  => dbms_lob.lobmaxsize',
'                        	,dest_offset  => l_dest_offsset',
'                        	,src_offset   => l_src_offsset',
'                        	,blob_csid	  => dbms_lob.default_csid',
'                        	,lang_context => l_lang_context',
'                        	,warning    	=> l_warning);',
'  	if l_warning != 0 then',
'     	apex_debug.warn(''function blob_to_clob warning: %s'', l_warning);',
'     	return null;',
'  	end if;',
'  	return(l_clob_result);',
'	else',
'  	return null;',
'	end if;',
'exception',
'	when others then',
'  	return null;',
'end blob2clob;',
'',
'function render (',
'    p_dynamic_action in apex_plugin.t_dynamic_action,',
'    p_plugin         in apex_plugin.t_plugin',
')',
'return apex_plugin.t_dynamic_action_render_result is',
'  l_result       apex_plugin.t_dynamic_action_render_result;',
'  l_nome         p_dynamic_action.attribute_02%type := p_dynamic_action.attribute_02;',
'  l_submit_items p_dynamic_action.attribute_05%type := p_dynamic_action.attribute_05;',
'  l_report       p_dynamic_action.attribute_01%type := p_dynamic_action.attribute_01;',
'begin',
'  if apex_application.g_debug then',
'    apex_plugin_util.debug_dynamic_action(p_plugin         => p_plugin,',
'                                          p_dynamic_action => p_dynamic_action);',
'  end if;',
'  apex_javascript.add_inline_code (',
'        p_key  => ''run_report'',',
'        p_code =>',
'q''[var natcorp = natcorp || {};',
'natcorp.run_report = function () {',
'  var l_submit_items = this.action.attribute01 ? this.action.attribute01.split(",") : [],',
'      spinner        = apex.util.showSpinner(),',
'      modal          = $(''<div class="ui-widget-overlay ui-front" style="z-index: 900;"></div>''),',
'      filename       = this.action.attribute02;',
'',
'  $("body").append(modal);',
'',
'  if (this.action.attribute03 && /#.+#/.test(this.action.attribute03))',
'    l_submit_items.push(this.action.attribute03.replace(/(#)(.+)(#)/,"$2"))',
'',
'  apex.server.plugin (this.action.ajaxIdentifier, {',
'    pageItems: l_submit_items',
'  }, {',
'    xhr: function() {',
'      var xhr = new XMLHttpRequest();',
'      xhr.responseType = "blob";',
'      return xhr;',
'    },',
'    //dataType: "text",',
'    complete: function() {',
'      modal && modal.remove();',
'      spinner && spinner.remove();',
'    },',
'    success: function(JSONData, pStatus, pXHR) {',
'      var mime   = JSONData.mime //pXHR.getResponseHeader("content-type"),',
'          disp   = JSONData.disp //pXHR.getResponseHeader("content-disposition"),',
'          blob   = new Blob([JSONData.bin], {type: mime});',
'',
'      if (JSONData.error) {',
'        apex.message.showErrors({',
'          type:     "error",',
'          location: "page",',
'          message:  JSONData.error,',
'          unsafe:   false',
'        });',
'      } else {',
'        if (window.navigator && window.navigator.msSaveOrOpenBlob) { // IE',
'            window.navigator.msSaveOrOpenBlob(blob, filename);',
'        } else {',
'          var url    = window.URL || window.webkitURL,',
'              urlObj = url.createObjectURL(blob);',
'',
'          if (!!~disp.indexOf("inline"))',
'            window.open(urlObj);',
'          else {',
'            var link = document.createElement("a");',
'            link.href     = urlObj;',
'            link.download = filename;',
'            link.click();',
'          }',
'',
'          setTimeout(function() { url.revokeObjectURL(urlObj); }, 100); // cleanup',
'        }',
'      }',
'    }',
'  });',
'}]'');',
'  --',
'  l_result.javascript_function := ''natcorp.run_report'';',
'  l_result.ajax_identifier     := apex_plugin.get_ajax_identifier;',
'  l_result.attribute_01        := l_submit_items;',
'  l_result.attribute_02        := l_nome;',
'  l_result.attribute_03        := l_report;',
'  --',
'  return l_result;',
'end render;',
'',
'function ajax_report(p_dynamic_action in apex_plugin.t_dynamic_action,',
'                     p_plugin         in apex_plugin.t_plugin)',
'  return apex_plugin.t_dynamic_action_ajax_result is',
'  --',
'  l_result      apex_plugin.t_dynamic_action_ajax_result;',
'  --',
'  l_blob        blob;',
'  l_mime        varchar2(255);',
'  l_len         number;',
'  --',
'  l_report      p_dynamic_action.attribute_01%type := p_dynamic_action.attribute_01;',
'  l_name        p_dynamic_action.attribute_02%type := p_dynamic_action.attribute_02;',
'  l_disposition p_dynamic_action.attribute_03%type := p_dynamic_action.attribute_03;',
'  l_param_list  p_dynamic_action.attribute_04%type := p_dynamic_action.attribute_04;',
'  l_use_plsql   p_dynamic_action.attribute_06%type := p_dynamic_action.attribute_06;',
'  l_param_plsql p_dynamic_action.attribute_07%type := p_dynamic_action.attribute_07;',
'  l_format      p_dynamic_action.attribute_08%type := p_dynamic_action.attribute_08;',
'  l_extension   p_dynamic_action.attribute_09%type := p_dynamic_action.attribute_09;',
'  l_destype     p_dynamic_action.attribute_10%type := p_dynamic_action.attribute_10;',
'  l_desname     p_dynamic_action.attribute_11%type := p_dynamic_action.attribute_11;',
'  l_params      varchar2(32767);',
'begin',
'  --',
'  execute immediate ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS=''''.,'''''';',
'  pkg_idioma.seta_idioma(''AMERICAN'');',
'  --',
'  if l_use_plsql = ''Y'' then',
'    if l_param_plsql is not null then',
'      l_params := apex_plugin_util.get_plsql_function_result(l_param_plsql);',
'    end if;',
'  else',
'    l_params := l_param_list;',
'  end if;',
'  --',
'  if regexp_instr(l_report, ''#.+#'') > 0 then',
'    l_report := apex_util.get_session_state(regexp_replace(l_report, ''(#)(.+)(#)'', ''\2''));',
'  end if;',
'  --',
'  call_report (',
'    l_report || l_extension',
'   ,l_blob',
'   ,l_mime',
'   ,l_params',
'   ,l_format',
'   ,nvl(l_destype,''cache'')',
'   ,l_desname',
'  );',
'  --',
'  l_len := nvl(dbms_lob.getlength(l_blob), 0);',
'  --',
'  apex_debug.info(''Disposition: %s'', l_disposition);',
'  apex_debug.info(''Mimetype: %s'', l_mime);',
'  apex_debug.info(''Length: %s'', l_len);',
'  apex_debug.info(''Name: %s'', l_name);',
'  --',
'  apex_json.open_object;',
'    apex_json.write(''disp'', l_disposition);',
'    apex_json.write(''mime'', l_mime);',
'    apex_json.write(''len'', l_len);',
'    apex_json.write(''bin'', blob2clob(l_blob));',
'  apex_json.close_object;',
'  --',
'  return l_result;',
'exception when others then',
'  apex_json.open_object;',
'    apex_json.write(''error'', dbms_utility.format_error_stack || dbms_utility.format_error_backtrace);',
'  apex_json.close_object;',
'  --',
'  return l_result;',
'end ajax_report;'))
,p_api_version=>2
,p_render_function=>'render'
,p_ajax_function=>'ajax_report'
,p_standard_attributes=>'ITEM:BUTTON:JQUERY_SELECTOR:TRIGGERING_ELEMENT:STOP_EXECUTION_ON_ERROR:WAIT_FOR_RESULT'
,p_substitute_attributes=>true
,p_reference_id=>6643529931099188396
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.0'
,p_plugin_comment=>'By Vinicius Damarques'
);
wwv_flow_api.create_plugin_attribute(
 p_id=>wwv_flow_api.id(203157155209512244502)
,p_plugin_id=>wwv_flow_api.id(203157155000372244508)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Report'
,p_attribute_type=>'TEXT'
,p_is_required=>true
,p_is_translatable=>false
,p_text_case=>'UPPER'
,p_help_text=>'Para usar um item, utilize a sintaxe #PX_ITEM#'
);
