prompt --application/shared_components/plugins/authentication_type/br_com_natcorp_auth
begin
wwv_flow_api.create_plugin(
 p_id=>wwv_flow_api.id(208519040016885168131)
,p_plugin_type=>'AUTHENTICATION TYPE'
,p_name=>'BR.COM.NATCORP.AUTH'
,p_display_name=>'Auth Natcorp'
,p_supported_ui_types=>'DESKTOP'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('AUTHENTICATION TYPE','BR.COM.NATCORP.AUTH'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function natcorp_auth(p_authentication in apex_plugin.t_authentication',
'                     ,p_plugin         in apex_plugin.t_plugin',
'                     ,p_password       in varchar2)',
'  return apex_plugin.t_authentication_auth_result is',
'',
'  l_result    apex_plugin.t_authentication_auth_result;',
'  --',
'  l_username  VARCHAR2(200) := trim(p_authentication.username);--usuario_oracle.nm_usuario_oracle%type := trim(p_authentication.username);',
'  l_empresa   inf_pessoais_cad.cod_empresa%type;',
'  l_matricula inf_pessoais_cad.matricula%type;',
'  l_painel    varchar2(2) := NVL(:p_painel,''PO'');',
'  --l_nome      inf_pessoais_cad.nome%type;',
'  --',
'  l_status varchar2(10);',
'  l_existe_msg varchar2(1);',
'  l_ok         varchar2(1);',
'  l_mensagem   varchar2(4000);',
'begin',
'',
'  --pkg_login_operador.prc_valida_acesso(l_username, p_password, l_existe_msg, l_mensagem, l_ok, l_Painel);',
'  pkg_apex.prc_login(l_painel, l_username, l_empresa, l_matricula, p_password,null, l_status, l_mensagem);',
'  --',
'  --apex_util.set_session_state(p_authentication.attribute_01, l_ok);',
'  --',
'  if l_status = ''OK'' then',
'    --',
'    apex_util.set_session_state(p_authentication.attribute_01, ''OK'');',
'    apex_util.set_session_state(p_authentication.attribute_02, usuario.busca_user);',
'    apex_util.set_session_state(p_authentication.attribute_03, l_empresa);',
'    apex_util.set_session_state(p_authentication.attribute_04, l_matricula);',
'    apex_util.set_session_state(p_authentication.attribute_05, l_username);',
'    apex_util.set_session_state(p_authentication.attribute_06, to_number(to_char(sysdate,''ddmmrrrrhh24miss'')));',
'    apex_util.set_session_state(p_authentication.attribute_07, l_painel);',
'    --',
'    l_result.is_authenticated := true;',
'  else',
'    apex_util.set_session_state(p_authentication.attribute_01, null);',
unistr('    apex_util.set_session_state(p_authentication.attribute_02, ''N\00E3o'');'),
'    --',
'    l_result.is_authenticated := false;',
'    l_result.display_text     := l_mensagem;',
'  end if;',
'',
'  return l_result;',
'exception when others then',
'  apex_util.set_session_state(p_authentication.attribute_01, ''N'');',
'  apex_util.set_session_state(p_authentication.attribute_02, ''Erro'');',
'  --',
'  l_result.is_authenticated := false;',
'  l_result.display_text     := ''Erro ao Efetuar Login'';',
'',
'  return l_result;',
'end;'))
,p_api_version=>2
,p_authentication_function=>'natcorp_auth'
,p_standard_attributes=>'LOGIN_PAGE'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.0'
);
