wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196789873994539364740)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_IMG_FUNC'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_blob blob;',
'  l_len  number;',
'  --',
'  l_mime varchar2(255);',
'  l_name varchar2(255);',
'  --',
'  l_cod_empresa fotos.cod_empresa%type;',
'  l_matricula   fotos.matricula%type;',
'begin',
'',
'  l_cod_empresa := regexp_substr(apex_application.g_x01, ''[0-9]+'', 1, 1);',
'  l_matricula   := regexp_substr(apex_application.g_x01, ''[0-9]+'', 1, 2);',
'',
'  select foto, dbms_lob.getlength(foto), tipo, nome_foto || ''.jpg''',
'    into l_blob, l_len, l_mime, l_name',
'    from fotos',
'   where cod_empresa = l_cod_empresa',
'     and matricula   = l_matricula;',
'',
'  if l_len > 0 then',
unistr('    -- seta header de sess\00E3o'),
'    owa_util.mime_header(l_mime, false);',
'    htp.p(''Content-length: '' || l_len);',
'    --htp.p(''Content-Disposition: '' || ''attachment'' || ''; filename="'' || l_name || ''"'');',
'    htp.p(''Content-Disposition: inline; filename="'' || l_name || ''"'');',
'    owa_util.http_header_close;',
'',
'    -- faz download',
'    sys.wpg_docload.download_file(l_blob);',
'    apex_application.stop_apex_engine;',
'  end if;',
'exception when others then',
'  htp.p(''param:'' || apex_application.g_x01 || '' / erro:'' || sqlerrm);',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
/
