wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(196622864444611292937)
,p_plug_name=>'Report 1'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(209353570115087209769)
,p_plug_display_sequence=>20
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with my_sel as (',
'select inf.ROWID cod,',
'       (select cod||''-''||nome from empresas_cad where cod = inf.cod_empresa) EMPRESA,',
'       (select cod_filial||''-''||nome_filial from filiais_cad where cod_empresa = inf.cod_empresa and cod_filial = inf.filial) COD_FILIAL,',
'       (select cod||''-''||nome from centro_de_custo where cod_empresa = inf.cod_empresa and cod = inf.COD_CCUSTO) CENTRO,',
'       (select matricula||''-''||nome from inf_pessoais where cod_empresa = inf.cod_empresa and matricula = inf.MATRICULA) MAT,',
'       (select cod_local_trab||''-''||descricao from local_trab where cod_local_trab = inf.COD_LOCALIZACAO) LOC,',
'       (select cod_escala||''-''||descricao from pe_escalas where cod_escala = e.COD_ESCALA) ESCALA,',
'       par.COD_PARAM_BH BANCO,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''D'', ''A'', ''T'') DEB_PER,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, ''01/01/1900'', ''31/12/2099'', ''D'', ''A'', ''T'') TOT_DEB,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''C'', ''A'', ''T'') CRED_PER,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, ''01/01/1900'', ''31/12/2099'', ''C'', ''A'', ''T'') TOT_CRED,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''T'', ''A'', ''T'') SALDO_PER,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, ''01/01/1900'', ''31/12/2099'', ''T'', ''A'', ''T'') TOT_SALDO,',
'       to_date(:P2_INICIO, ''dd/mm/rrrr'') INICIO,',
'       to_date(:P2_FIM, ''dd/mm/rrrr'') FIM,',
'       inf.cod_empresa,',
'       inf.matricula,',
'       replace(fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''T'', ''A'', ''T''),'':'','''') TOT_SALDO_PARAM',
'  from VW_INFORMACOES_FUNCIONAIS_CAD inf,',
'       PE_ESCALAS_EXCECOES e,',
'       PE_FUNC_PARAMETROS_BH par',
'WHERE inf.COD_EMPRESA = e.COD_EMPRESA',
' AND  inf.MATRICULA = e.MATRICULA',
' AND  par.COD_EMPRESA = inf.COD_EMPRESA',
' AND  par.MATRICULA = inf.MATRICULA',
' AND  e.EXCECAO     = ''N''',
' AND  par.DATA_ini = (select max(data_ini) ',
'                     from pe_func_parametros_bh',
'	                 where cod_empresa = inf.cod_empresa',
'                      and matricula   = inf.matricula)',
' AND  inf.COD_EMPRESA = :p2_cod_empresa',
' AND  inf.MATRICULA = nvl(:P2_MATRICULA, inf.MATRICULA)',
' AND  inf.FILIAL  = nvl(:P2_FILIAL, inf.FILIAL)',
' AND  inf.COD_CCUSTO = nvl(:P2_COD_CCUSTO, inf.COD_CCUSTO)',
' AND  ( :P2_FIM BETWEEN e.INICIO AND e.FIM',
' OR    LAST_DAY(:P2_FIM) BETWEEN e.INICIO AND e.FIM)',
' and  (fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''D'', ''A'', ''T'') != ''00:00'' or fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''C'', ''A'', ''T'')  != ''00:00'')',
' UNION',
'select inf.ROWID cod,',
'       (select cod||''-''||nome from empresas_cad where cod = inf.cod_empresa) EMPRESA,',
'       (select cod_filial||''-''||nome_filial from filiais_cad where cod_empresa = inf.cod_empresa and cod_filial = inf.filial) COD_FILIAL,',
'       (select cod||''-''||nome from centro_de_custo where cod_empresa = inf.cod_empresa and cod = inf.COD_CCUSTO) CENTRO,',
'       (select matricula||''-''||nome from inf_pessoais where cod_empresa = inf.cod_empresa and matricula = inf.MATRICULA) MAT,',
'       (select cod_local_trab||''-''||descricao from local_trab where cod_local_trab = inf.COD_LOCALIZACAO) LOC,',
'       (select cod_escala||''-''||descricao from pe_escalas where cod_escala = e.COD_ESCALA) ESCALA,',
'       nvl(sind.COD_REGRA_BH, pe.cod_param_bh) BANCO, ',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''D'', ''A'', ''T'') DEB_PER,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, ''01/01/1900'', ''31/12/2099'', ''D'', ''A'', ''T'') TOT_DEB,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''C'', ''A'', ''T'') CRED_PER,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, ''01/01/1900'', ''31/12/2099'', ''C'', ''A'', ''T'') TOT_CRED,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''T'', ''A'', ''T'') SALDO_PER,',
'       fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, ''01/01/1900'', ''31/12/2099'', ''T'', ''A'', ''T'') TOT_SALDO,',
'       to_date(:P2_INICIO, ''dd/mm/rrrr'') INICIO,',
'       to_date(:P2_FIM, ''dd/mm/rrrr'') FIM,',
'       inf.cod_empresa,',
'       inf.matricula,',
'      replace(fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''T'', ''A'', ''T''),'':'','''') TOT_SALDO_PARAM',
'  from VW_INFORMACOES_FUNCIONAIS_CAD inf,',
'       PE_ESCALAS_EXCECOES e,',
'       SINDICATOS sind,',
'       PE_JORNADAS pe',
'WHERE inf.COD_EMPRESA = e.COD_EMPRESA',
' AND  inf.MATRICULA = e.MATRICULA',
' AND  e.EXCECAO     = ''N''',
' and  sind.cod_empresa = e.cod_empresa',
' and  sind.cod = inf.NUM_SIND_DISS',
' and  pe.cod_empresa = e.COD_EMPRESA',
' and  pe.cod_jornada = e.cod_jornada',
' and exists (select 1',
'               from pe_resultado_apuracao res',
'              where res.cod_empresa = inf.cod_empresa',
'                and res.matricula = inf.MATRICULA',
'                and res.tipo_evento = ''BANCO'')',
' AND  inf.COD_EMPRESA = :p2_cod_empresa',
' AND  inf.MATRICULA = nvl(:P2_MATRICULA, inf.MATRICULA)',
' AND  inf.FILIAL  = nvl(:P2_FILIAL, inf.FILIAL)',
' AND  inf.COD_CCUSTO = nvl(:P2_COD_CCUSTO, inf.COD_CCUSTO)',
' AND  ( :P2_FIM BETWEEN e.INICIO AND e.FIM',
' OR    LAST_DAY(:P2_FIM) BETWEEN e.INICIO AND e.FIM)',
' and  (fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''D'', ''A'', ''T'') != ''00:00'' or fnct_pe_saldos_apurado (inf.COD_EMPRESA, inf.MATRICULA, :P2_INICIO, :P2_FIM, ''C'', ''A'', ''T'')  != ''00:00'')',
' ORDER BY 2, 3,4, 5)',
' select * from my_sel',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P2_COD_EMPRESA,P2_COD_CCUSTO,P2_MATRICULA,P2_FILIAL,P2_TIPO'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_document_header=>'APEX'
,p_prn_units=>'MILLIMETERS'
