 p_id=>wwv_flow_api.id(196697818232925069544)
,p_plug_name=>'Report1'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(209353570115087209769)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select LP.ROWID,',
'       LP.COD_EMPRESA,',
'       LP.MATRICULA,',
'       LP.DT_LANCTO,',
'       LP.COD_EVENTO_FOLHA EVENTO_FOLHA,',
'       LP.COD_EVENTO_PONTO EVENTO_PONTO,',
'       LP.TIPO_CATEGORIA,',
'       LP.HORA_INICIO,',
'       LP.HORA_FIM,',
'       LP.HORA_TOTAL, ',
'       LP.DT_ATUALIZACAO,',
'       LP.USUARIO,',
'       LP.COD_DOENCA,',
'       LP.CRM,',
unistr('       DECODE(LP.FECHAMENTO, ''S'', ''Sim'', ''N'', ''N\00E3o'') FECHAMENTO,'),
'       LP.USUARIO_FECHAMENTO,',
'       LP.DT_FECHAMENTO',
'from LANCAMENTOS_PONTO LP',
'  where LP.COD_EMPRESA = :P4_COD_EMPRESA',
'   and ( :P4_MATRICULA is null or LP.matricula = :P4_MATRICULA )',
'    and  (:P4_CCUSTO IS NULL OR :P4_CCUSTO IN (SELECT IFC.COD_CCUSTO ',
'                                               FROM VW_INFORMACOES_FUNCIONAIS_CAD IFC',
'                                              WHERE IFC.COD_EMPRESA = LP.COD_EMPRESA',
'                                               AND  IFC.MATRICULA = LP.MATRICULA',
'                                               AND  f_acesso_apex_simples(IFC.cod_empresa, ',
'                                                    IFC.MATRICULA,NULL, NULL, :P_USUARIO, :P_PAINEL) = ''S'' ))',
'   and (:P4_CID is null or COD_DOENCA = :P4_CID)',
'   and (:P4_CRM is null or CRM = :P4_CRM)',
'   and NVL(:P4_MARCA_PONTO, ''N'') = (select marca_ponto',
'                               from VW_INFORMACOES_FUNCIONAIS_CAD IFC',
'                                              WHERE IFC.COD_EMPRESA = LP.COD_EMPRESA',
'                                               AND  IFC.MATRICULA = LP.MATRICULA',
'                                               and marca_ponto = ''S'')',
'',
'AND (  EXISTS (SELECT 1 ',
'       FROM VW_INFORMACOES_FUNCIONAIS_CAD IFC',
'             WHERE IFC.COD_EMPRESA = LP.COD_EMPRESA',
'              AND  IFC.MATRICULA = LP.MATRICULA',
'              AND :P4_SITUACAO = ''A''',
'              AND SITUACAO < ''90'') ',
'     OR        ',
'        EXISTS  (SELECT 1 ',
'       FROM VW_INFORMACOES_FUNCIONAIS_CAD IFC',
'             WHERE IFC.COD_EMPRESA = LP.COD_EMPRESA',
'              AND  IFC.MATRICULA = LP.MATRICULA',
'              AND :P4_SITUACAO = ''D''',
'              AND SITUACAO >= ''90'') ',
'    OR         ',
'          EXISTS    (SELECT 1 ',
'       FROM VW_INFORMACOES_FUNCIONAIS_CAD IFC',
'             WHERE IFC.COD_EMPRESA = LP.COD_EMPRESA',
'              AND  IFC.MATRICULA = LP.MATRICULA',
'              AND :P4_SITUACAO = ''T'') )',
'   and exists (select 1 ',
'               from pe_escalas_excecoes ',
'              where cod_empresa = nvl(:P4_COD_EMPRESA, LP.cod_empresa) ',
'              and matricula = LP.matricula',
'              and sysdate between inicio and fim)  ',
'ORDER BY LP.COD_EMPRESA, LP.MATRICULA',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P4_COD_EMPRESA,P4_CCUSTO,P_USUARIO,P_PAINEL,P4_CID,P4_CRM'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_document_header=>'APEX'
,p_prn_units=>'MILLIMETERS'
