wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(196697902952283708518)
,p_event_id=>wwv_flow_api.id(196697902835833708517)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	V_HORA     NUMBER(5)    := 0;',
'	V_MIN      NUMBER(5)    := 0;',
'	V_USUARIO  VARCHAR2(30) := :APP_USER;',
'	V_CONT     NUMBER(10)   := 0;',
'    V_ERRO     VARCHAR2(4000);',
'BEGIN',
'    DELETE OCORRENCIA_CALCULO',
'        WHERE  COD_EMPRESA = :P6_COD_EMPRESA ',
'        --AND    DT_INIC_VAL BETWEEN :P6_DT_INI AND :P6_DT_FIN',
'        and dt_inic_val >= :P6_DT_INI AND DT_FIN_VAL <= :P6_DT_FIM',
'        AND   HORAS_FERIAS = ''515'';',
'',
'    FOR L1 IN(',
'            SELECT A.ROWID, A.COD_EMPRESA, A.MATRICULA, C.DC_MATRICULA, A.TIPO_CATEGORIA, A.HORA_TOTAL, B.COD COD_OCORR, B.DC_COD,',
'            A.DT_LANCTO, D.DT_REF_FOLHA ',
'            FROM LANCAMENTOS_PONTO A, OCORR_PAGTO B, INFORMACOES_FUNCIONAIS C, PARAMETROS_RECURSOS_HUMANOS D',
'            WHERE A.COD_EMPRESA    =  :P6_COD_EMPRESA ',
'            AND   A.DT_LANCTO BETWEEN :P6_DT_INI AND :P6_DT_FIM',
'            AND   B.COD_EMPRESA    = A.COD_EMPRESA',
'            AND   B.TIPO_CATEGORIA = A.TIPO_CATEGORIA',
'            AND   C.COD_EMPRESA    = A.COD_EMPRESA',
'            AND   C.MATRICULA      = A.MATRICULA',
'            AND   D.COD_EMPRESA    = A.COD_EMPRESA',
'            AND A.FECHAMENTO       = ''N'')',
'    LOOP',
'       V_HORA := TO_NUMBER(SUBSTR(L1.HORA_TOTAL, 1, INSTR(L1.HORA_TOTAL, '':'')-1));',
'       V_MIN  := TO_NUMBER(SUBSTR(L1.HORA_TOTAL, INSTR(L1.HORA_TOTAL, '':'')+1)) / 60 *100;',
'       --V_HORA := TRUNC(L1.HORA_TOTAL/100);',
'        --V_MIN  := SUBSTR(TO_CHAR(L1.HORA_TOTAL/100, ''99999.09''), INSTR(TO_CHAR(L1.HORA_TOTAL/100, ''99999.09''), ''.'')+1);',
'',
'        INSERT INTO OCORRENCIA_CALCULO(',
'        COD_EMPRESA       , MATRICULA   , DC_MATRICULA   , DATA_REF      , COD_OCORR     , DC_OCORR     , UNIDADE1   , UNIDADE2      , ',
'        VALOR             , FAIXA       , HORAS_FERIAS   , MIN_FERIAS    , DT_INIC_VAL   , DT_FIN_VAL   , USUARIO    , DT_ULT_ATLZ   , ',
'        VALOR_CRUZEIRO    , CD_NIVEL    , DATA_RETENCAO  )',
'        VALUES(',
'        :P6_COD_EMPRESA, L1.MATRICULA, L1.DC_MATRICULA,L1.DT_REF_FOLHA, L1.COD_OCORR  , L1.DC_COD    , V_HORA     , V_MIN         ,',
'        NULL              , NULL        , 515            , NULL          , L1.DT_LANCTO  , L1.DT_LANCTO , V_USUARIO  , SYSDATE       ,',
'        NULL              , NULL        , NULL);',
'',
'        UPDATE LANCAMENTOS_PONTO',
'            SET FECHAMENTO = ''S''',
'                , USUARIO_FECHAMENTO = :P_USUARIO',
'                , DT_FECHAMENTO = SYSDATE',
'            WHERE ROWID = L1.ROWID;',
'        V_CONT  := V_CONT + 1;',
'    END LOOP;',
'',
'  EXCEPTION WHEN OTHERS THEN',
'        V_ERRO := SQLERRM;',
'        ROLLBACK;',
'        APEX_ERROR.ADD_ERROR(p_message => V_ERRO, p_display_location => apex_error.c_inline_in_notification);',
'END;'))
,p_attribute_02=>'P6_COD_EMPRESA,P6_DT_INI,P6_DT_FIM'
,p_wait_for_result=>'Y'
);
