'pkg_pe_abono.fnct_pe_retorna_div_class (t.cod_empresa, t.matricula, t.data, t.hora_batida_abono_10, 10) divergente_10',
'from pe_abono_batidas_seq_ponto t',
'where t.cod_empresa = :p8_emp',
'and t.matricula = :p8_mat and seq = :p8_seq',
'and t.data between :p8_dt_ini and :p8_dt_fim',
'and ((to_char(t.hora_batida_abono_1,''hh24:mi'') is not null)',
