') x,',
'parametros_recursos_humanos p',
'where x.cod_empresa = p.cod_empresa',
'and ((:p_painel = ''PO'') or (x.data between nvl(p.dt_ini_ponto_gestor,x.data) and nvl(p.dt_fim_ponto_gestor,x.data)))',
'order by 1,2,4,3',
