wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(196705788945869814642)
,p_event_id=>wwv_flow_api.id(196705788858328814641)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'  vJornada pe_jornadas.cod_jornada%type;',
'',
'cursor c1 is',
'select cod_empresa, matricula, data_ponto, vira_dia, hora_batida, hora_batida_abono, posicao, cod_justificativa, comentarios',
'  from pe_tratamento_batimentos',
' where cod_empresa = :p9_cod_empresa',
'   and matricula = :p9_matricula',
'   and nvl(vira_dia,data_ponto) = :p9_data_ponto',
'   and posicao = :p9_posicao;',
'   ',
'v_c1 c1%rowtype;',
'',
'cursor c2 (v_emp number, v_mat number, v_data date, v_pos number, v_pto_feriado varchar2, pJornada number) is',
'      SELECT horario, posicao',
'        FROM PE_JORNADAS_COMPOSICAO',
'       WHERE cod_jornada = pJornada',
'         AND POSICAO = v_pos',
'         AND ((((((TO_CHAR(v_data, ''d'') = 1) AND (domingo = ''S'')  AND (NVL(v_pto_feriado,''N'') = ''N'')) )',
'          OR   (((TO_CHAR(v_data, ''d'') = 2) AND (segunda = ''S'')  AND (NVL(v_pto_feriado,''N'') = ''N'')) )',
'          OR   (((TO_CHAR(v_data, ''d'') = 3) AND (terca   = ''S'')  AND (NVL(v_pto_feriado,''N'') = ''N'')) )',
'          OR   (((TO_CHAR(v_data, ''d'') = 4) AND (quarta  = ''S'')  AND (NVL(v_pto_feriado,''N'') = ''N'')) )',
'          OR   (((TO_CHAR(v_data, ''d'') = 5) AND (quinta  = ''S'')  AND (NVL(v_pto_feriado,''N'') = ''N'')) )',
'          OR   (((TO_CHAR(v_data, ''d'') = 6) AND (sexta   = ''S'')  AND (NVL(v_pto_feriado,''N'') = ''N'')) )',
'          OR   (((TO_CHAR(v_data, ''d'') = 7) AND (sabado  = ''S'')  AND (NVL(v_pto_feriado,''N'') = ''N'')) ))',
'          OR ((NVL(v_pto_feriado,''N'') = ''S'' AND (FERIADO = ''S'') ))))',
'       ORDER BY POSICAO DESC;',
' ',
'v_c2 c2%rowtype;',
'',
' V_CONSID_PTO_FERIADO varchar2(1) := ''N'';',
'',
'v_emp informacoes_funcionais.cod_empresa%type;',
'v_mat informacoes_funcionais.matricula%type;',
'',
'begin',
'',
'    v_emp := :p9_cod_empresa;',
'    v_mat := :p9_matricula;',
'    ',
'    vJornada := Fnct_Pe_Retorna_Jornada( v_emp, v_mat, :p9_data_ponto );',
'',
'    open  c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'',
'    V_CONSID_PTO_FERIADO := F_Pe_Considera_Jornada_Feriado(v_emp,v_mat,:p9_data_ponto);',
' ',
'    open  c2(v_emp, v_mat, :p9_data_ponto, :p9_posicao, V_CONSID_PTO_FERIADO,vJornada);',
'    fetch c2 into v_c2;',
'    close c2;',
'    ',
'    if v_c2.horario is not null then',
'    :p9_horario           := v_c2.horario;',
'    else',
'    :p9_horario           := null;',
'    end if;',
' ',
'    if v_c1.cod_empresa is not null then ',
'            ',
'        :p9_hora_batida       := to_char(v_c1.hora_batida,''hh24:mi'');',
'        :p9_hora_batida_abono := to_char(v_c1.hora_batida_abono,''hh24:mi'');',
'        :p9_justificativa := v_c1.cod_justificativa;',
'        :p9_comentarios   := v_c1.comentarios;',
'    ',
'    else',
'    ',
'        :p9_hora_batida       := null;',
'        :p9_hora_batida_abono := null;',
'        :p9_justificativa     := null;',
'        :p9_comentarios       := null;',
'    ',
'    end if;',
'',
'end;',
''))
,p_attribute_02=>'P9_COD_EMPRESA,P9_MATRICULA,P9_DATA_PONTO,P9_POSICAO'
,p_attribute_03=>'P9_HORARIO,P9_HORA_BATIDA,P9_HORA_BATIDA_ABONO,P9_JUSTIFICATIVA,P9_COMENTARIOS'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
