 p_id=>wwv_flow_api.id(144599710747462529879)
,p_name=>'post-change-cod_evento_novo'
,p_event_sequence=>20
,p_triggering_element_type=>'ITEM'
,p_triggering_element=>'P10_COD_EVENTO_NOVO'
,p_bind_type=>'bind'
,p_bind_event_type=>'change'
