wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(144599711238715529879)
,p_event_id=>wwv_flow_api.id(144599710747462529879)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
unistr('select decode(tipo_rubrica, 1, ''Cr\00E9dito'', 2, ''D\00E9bito'', 3, ''Base'') tipo_Desc, to_char(cod_ocorr) tipo, FOLHA folha'),
'  from pe_eventos_folha f, ocorr_pagto op',
' where ',
'  op.cod_empresa = f.cod_empresa ',
' and op.cod = f.cod_ocorr',
'    and f.cod_empresa = :p10_emp',
'   and f.cod_evento_folha = :P10_COD_EVENTO_NOVO --p10_cod_evento_novo',
'   and :p10_tipo_evento_novo = ''PONTO''',
'union ',
unistr('select decode(b.tipo,''C'',''Cr\00E9dito'',''D'',''D\00E9bito'') tipo_Desc, b.tipo tipo, ''S'' Folha'),
'  from pe_eventos_banco b',
' where b.cod_empresa = :p10_emp',
'   and b.cod_evento_banco = :P10_COD_EVENTO_NOVO --p10_cod_evento_novo',
'   and :p10_tipo_evento_novo = ''BANCO'';',
'   ',
'v_c1 c1%rowtype;',
'',
'begin',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'    :p10_tipo_novo := '''';',
'	:p10_tipo_disp_novo := '''';',
'    :p10_tipo_disp_novo := v_c1.tipo_desc;',
'    if v_c1.tipo is not null then',
'        :p10_tipo_novo := v_c1.tipo;',
'        if v_c1.folha = ''S'' then',
'        :p10_tipo_disp_novo := v_c1.tipo_desc;',
'        end if;',
'    end if;',
'    ',
'end;'))
,p_attribute_02=>'P10_EMP,P10_COD_EVENTO_NOVO,P10_TIPO_EVENTO_NOVO'
,p_attribute_03=>'P10_TIPO_DISP_NOVO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
