,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_permite pe_eventos_folha.permite_justificar%type;',
'    v_erro varchar2(4000);',
'begin',
'',
'',
'',
'    insert into testex values (7001, ''ANDRE - P10_EMP = ''||:P10_EMP);',
'    insert into testex values (7001, ''ANDRE - P10_COD_EVENTO = ''||:P10_COD_EVENTO);',
'    insert into testex values (7001, ''ANDRE - p10_tipo_evento = ''||:p10_tipo_evento);',
'COMMIT;',
'',
'    :P10_ALTERA_EVENTO:= null;',
'    if UPPER( :p10_tipo_evento ) = ''PONTO'' then    ',
'        select permite_justificar',
'            into l_permite',
'        from pe_eventos_folha ',
'        where COD_EMPRESA =:P10_EMP',
'        and COD_EVENTO_FOLHA = :P10_COD_EVENTO;',
'    elsif UPPER( :p10_tipo_evento ) = ''BANCO'' then ',
'        select permite_justificar',
'            into l_permite',
'        from PE_EVENTOS_BANCO ',
'        where COD_EMPRESA =:P10_EMP',
'        and COD_EVENTO_BANCO = :P10_COD_EVENTO;    ',
'    end if;',
'    if l_permite = ''N'' then',
'        :P10_ALTERA_EVENTO := 1;',
'    else',
'        :P10_ALTERA_EVENTO := NULL;',
'    end if;',
'exception',
'    when others then',
'    v_erro := SQLERRM;',
'        :P10_ALTERA_EVENTO := 1;',
'end;'))
,p_attribute_02=>'P10_EMP,P10_COD_EVENTO'
,p_attribute_03=>'P10_ALTERA_EVENTO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
