,p_process_sequence=>20
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Popula_campos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    cursor c_dados is',
'    select cod_item, cod_empresa, matricula, data, qtd_horas, posicao, tipo_evento, cod_evento, bh_apurado',
'    from pe_resultado_apuracao',
'           where cod_item = :P10_ROWID;',
'           ',
'    /*cursor c1 is',
'    select f.cod_evento_folha||'' - ''||f.descricao descricao,                                 ',
unistr('            (select decode(op.tipo_rubrica, 1, ''Cr\00E9dito'', 2, ''D\00E9bito'') '),
'                                         from ocorr_pagto op ',
'                                         where op.cod = f.cod_ocorr',
'                                         and cod_empresa = f.cod_empresa) TIPO, FOLHA FOLHA',
'        from pe_eventos_folha f',
'        where f.cod_empresa = :p10_emp',
'        and f.cod_evento_folha = :p10_cod_evento',
'        and upper( :p10_tipo_evento ) = ''PONTO''',
'    union ',
'        select b.cod_evento_banco||'' - ''||b.descricao descricao, B.TIPO TIPO, ''S'' FOLHA',
'        from pe_eventos_banco b',
'        where b.cod_empresa = :p10_emp',
'        and b.cod_evento_banco = :p10_cod_evento',
'        and upper( :p10_tipo_evento ) = ''BANCO'';',
'',
'    v_c1       c1%rowtype;*/',
'    r_dados    c_dados%rowtype;',
'   -- v_c varchar2(20);',
'begin',
'    ',
'    open c_dados;',
'    fetch c_dados into r_dados;',
'    close c_dados;',
'    :P10_POSICAO     := r_dados.posicao;',
'    :P10_QTD_HORAS   := r_dados.qtd_horas;',
'    :P10_CALC_HORAS  :=  r_dados.qtd_horas;',
'    :P10_DATA        := r_dados.data;',
'    :P10_TIPO_EVENTO := r_dados.tipo_evento;',
'    ',
'    select decode(:P10_BH_APURADO,''A'',''Aberto'',''F'',''Fechado'',''M'',''Manual'',:P10_BH_APURADO)',
'    into :P10_BH_APURADO_DSP',
'    from dual;',
'    --:P10_EVENTO := v_c1.descricao;',
'/*',
'    if :P10_TIPO_EVENTO  = ''PONTO'' then',
'        select f.cod_evento_folha||'' - ''||f.descricao descricao,                                 ',
unistr('                (select decode(op.tipo_rubrica, 1, ''Cr\00E9dito'', 2, ''D\00E9bito'') '),
'                                             from ocorr_pagto op ',
'                                             where op.cod = f.cod_ocorr',
'                                             and cod_empresa = f.cod_empresa) TIPO',
'            into :P10_EVENTO, :P10_TIPO',
'            from pe_eventos_folha f',
'            where f.cod_empresa = :p10_emp',
'            and f.cod_evento_folha = :p10_cod_evento;',
'    else',
