wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(124862082171272267500)
,p_process_sequence=>30
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Recupera Justificativa'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_msg varchar2(4000);',
'begin',
'',
'DELETE FROM TESTEX WHERE TEXTO LIKE ''ANDRE%'';',
'',
'INSERT INTO TESTEX VALUES (-10011, ''ANDRE - P10_EMP = ''||:P10_EMP);',
'INSERT INTO TESTEX VALUES (-10012, ''ANDRE - P10_COD_ITEM = ''||:P10_COD_ITEM);',
'INSERT INTO TESTEX VALUES (-10013, ''ANDRE - P10_MAT = ''||:P10_MAT);',
'INSERT INTO TESTEX VALUES (-10014, ''ANDRE - P10_DATA = ''||:P10_DATA);',
'INSERT INTO TESTEX VALUES (-10015, ''ANDRE - P10_QTD_HORAS = ''||:P10_QTD_HORAS);',
'INSERT INTO TESTEX VALUES (-10016, ''ANDRE - P10_TIPO_EVENTO = ''||:P10_TIPO_EVENTO);',
'INSERT INTO TESTEX VALUES (-10017, ''ANDRE - P10_COD_EVENTO = ''||:P10_COD_EVENTO);',
'INSERT INTO TESTEX VALUES (-10018, ''ANDRE - P10_POSICAO = ''||:P10_POSICAO);',
'',
'   PKG_JUSTIFICA_PONTO_HIST.recupera_justificativa( p_cod_empresa           => :P10_EMP',
'                                                   , p_cod_item             => :P10_COD_ITEM                              ',
'                                                   , p_matricula            => :P10_MAT ',
'                                                   , p_data                 => :P10_DATA ',
'                                                   , p_qtd_horas            => :P10_QTD_HORAS ',
'                                                   , p_tipo_evento          => :P10_TIPO_EVENTO',
'                                                   , p_cod_evento           => :P10_COD_EVENTO',
'                                                   , p_posicao              => :P10_POSICAO ',
'                                                   , p_justificativa        => :P10_JUSTIFICATIVA',
'                                                   , p_cod_ccusto_contabil  => :P10_CCUSTO_CONTABIL ',
'                                                   , p_observacoes          => :P10_OBSERVACOES',
'                                                   , p_mensagem             => v_msg  );',
'INSERT INTO TESTEX VALUES (-10019, ''ANDRE - v_msg = ''||v_msg);',
'COMMIT;',
'    if :P10_TIPO_EVENTO  = ''PONTO'' then',
'        select f.cod_evento_folha||'' - ''||f.descricao descricao,                                 ',
unistr('                (select decode(op.tipo_rubrica, 1, ''Cr\00E9dito'', 2, ''D\00E9bito'') '),
'                                             from ocorr_pagto op ',
'                                             where op.cod = f.cod_ocorr',
'                                             and cod_empresa = f.cod_empresa) TIPO',
'            into :P10_EVENTO, :P10_TIPO',
'            from pe_eventos_folha f',
'            where f.cod_empresa = :p10_emp',
'            and f.cod_evento_folha = :p10_cod_evento;',
'    else',
'        select b.cod_evento_banco||'' - ''||b.descricao descricao, B.TIPO TIPO',
'            into :P10_EVENTO, :P10_TIPO',
'        from pe_eventos_banco b',
'        where b.cod_empresa = :p10_emp',
'        and b.cod_evento_banco = :p10_cod_evento;',
'   end if;',
'                                                   ',
'    if v_msg is not null then',
'        :P10_MSG_CLOSE := v_msg;',
'    end if;',
'exception',
'    when others then',
'        :P10_JUSTIFICATIVA  := null;',
'        :P10_CCUSTO_CONTABIL:= null;',
'        :P10_OBSERVACOES    := null;',
'end;    '))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
