wwv_flow_api.create_report_region(
 p_id=>wwv_flow_api.id(124856704957760998989)
,p_name=>unistr('Travamento da Apura\00E7\00E3o')
,p_template=>wwv_flow_api.id(209353570115087209769)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'BODY'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select cod_item',
'    , data',
'    , qtd_horas',
'    , tipo_evento',
'    ,  case tipo_evento',
'           when ''PONTO'' then b.cod_evento||''-''||(select descricao from pe_eventos_folha where cod_evento_folha = b.cod_evento and cod_empresa = b.cod_empresa)',
'           when ''BANCO'' then b.cod_evento||''-''||(select descricao from pe_eventos_banco where cod_evento_banco = b.cod_evento and cod_empresa = b.cod_empresa)',
unistr('           else ''Evento n\00E3o identificado'''),
'       end "EVENTO"      ',
'   , posicao',
'    , decode(b.bh_apurado,''A'',''Aberto'',''F'',''Fechado'',''M'',''Manual'',b.bh_apurado) "BH_APURADO"',
unistr('    , decode(b.plantao, ''S'', ''Sim'', ''N'', ''N\00E3o'') "PLANT\00C3O"'),
