wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(69550393506394224164)
,p_name=>'P13_COD_EVENTO'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_api.id(222020668208539730464)
,p_prompt=>'Evento'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select a.cod_evento_folha||'' - ''||a.descricao, a.cod_evento_folha',
'    from pe_eventos_folha a,',
'        ocorr_pagto b,',
'         PE_EVENTOS_PERFIL x',
'    where a.cod_empresa = b.cod_empresa',
'    and a.cod_ocorr = b.cod',
'    and (b.tipo_rubrica in (1, 3) AND :P13_TIPO = ''C'')',
'    AND A.PERMITE_TRATAMENTO = ''S''',
'    and ''PONTO'' = :P13_TIPO_EVENTO',
'    and a.cod_empresa = :P13_COD_EMPRESA',
'    and x.cod_empresa(+) = :P13_COD_EMPRESA',
'    and x.cd_perfil(+) = :P_PERFIL',
'    AND X.COD_EVENTO(+) = a.cod_evento_FOLHA ',
'union',
'select a.cod_evento_folha||'' - ''||a.descricao, a.cod_evento_folha',
'    from pe_eventos_folha a,',
'        ocorr_pagto b,',
'        PE_EVENTOS_PERFIL x',
'    where a.cod_empresa = b.cod_empresa',
'    and a.cod_ocorr = b.cod',
'    and (b.tipo_rubrica in (2) AND :P13_TIPO = ''D'')',
'    AND A.PERMITE_TRATAMENTO = ''S''',
'    and ''PONTO'' = :P13_TIPO_EVENTO',
'    and a.cod_empresa = :P13_COD_EMPRESA',
'    and  x.cod_empresa(+) = :P13_COD_EMPRESA',
'               and x.cd_perfil(+)  = :P_PERFIL',
'               AND X.COD_EVENTO(+)  = a.cod_evento_FOLHA ',
'union',
'select c.cod_evento_banco||'' - ''||c.descricao, c.cod_evento_banco',
'    from pe_eventos_BANCO c,',
'            ocorr_pagto b,',
'            PE_EVENTOS_PERFIL x',
'    where c.cod_empresa = c.cod_empresa',
'    and b.cod = c.cod_ocorr',
'    --and c.tipo_rubrica in (1, 3)',
'    AND c.tipo = :P13_TIPO',
'    and c.cod_empresa = 600',
'    and ''BANCO'' = :P13_TIPO_EVENTO',
'    and  x.cod_empresa(+) = :P13_COD_EMPRESA',
'    and x.cd_perfil(+) = :P_PERFIL',
'    AND X.COD_EVENTO(+) = C.cod_evento_banco',
'union',
'select c.cod_evento_banco||'' - ''||c.descricao, c.cod_evento_banco',
'    from pe_eventos_BANCO c,',
'            ocorr_pagto b,',
'             PE_EVENTOS_PERFIL x',
'    where c.cod_empresa = c.cod_empresa',
'    and b.cod = c.cod_ocorr',
'    --and c.tipo_rubrica in (1, 3)',
'    AND c.tipo = :P13_TIPO',
'    and c.cod_empresa = :P13_COD_EMPRESA',
'    and ''BANCO'' = :P13_TIPO_EVENTO',
'    and  x.cod_empresa(+) = :P13_COD_EMPRESA',
'    and x.cd_perfil(+) = :P_PERFIL',
'    AND X.COD_EVENTO(+) = C.cod_evento_banco',
'order by 2  ',
''))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P13_COD_EMPRESA,P13_TIPO_EVENTO,P13_TIPO,P13_DTINI,P13_DTFIM'
