,p_prompt=>'Evento'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select a.cod_evento_folha||'' - ''||a.descricao, a.cod_evento_folha',
'    from pe_eventos_folha a,',
'        ocorr_pagto b,',
'         PE_EVENTOS_PERFIL x',
'    where a.cod_empresa = b.cod_empresa',
'    and a.cod_ocorr = b.cod',
'    and (b.tipo_rubrica in (1, 3) AND :P13_TIPO_NOVO = ''C'')',
'    AND A.PERMITE_TRATAMENTO = ''S''',
'    and ''PONTO'' = :P13_TIPO_EVENTO_NOVO',
'    and a.cod_empresa = :P13_COD_EMPRESA',
'    and x.cod_empresa(+) = :P13_COD_EMPRESA',
'    and x.cd_perfil(+) = :P_PERFIL',
'    AND X.COD_EVENTO(+) = a.cod_evento_FOLHA ',
'    AND A.COEFICIENTE = :P13_COEFICIENTE',
'union',
'select a.cod_evento_folha||'' - ''||a.descricao, a.cod_evento_folha',
'    from pe_eventos_folha a,',
'        ocorr_pagto b,',
'        PE_EVENTOS_PERFIL x',
'    where a.cod_empresa = b.cod_empresa',
'    and a.cod_ocorr = b.cod',
'    and (b.tipo_rubrica in (2) AND :P13_TIPO_NOVO = ''D'')',
'    AND A.PERMITE_TRATAMENTO = ''S''',
'    and ''PONTO'' = :P13_TIPO_EVENTO_NOVO',
'    and a.cod_empresa = :P13_COD_EMPRESA',
'    and  x.cod_empresa(+) = :P13_COD_EMPRESA',
'               and x.cd_perfil(+)  = :P_PERFIL',
'               AND X.COD_EVENTO(+)  = a.cod_evento_FOLHA',
'        AND A.COEFICIENTE = :P13_COEFICIENTE',
'',
'union',
'select c.cod_evento_banco||'' - ''||c.descricao, c.cod_evento_banco',
'    from pe_eventos_BANCO c,',
'            ocorr_pagto b,',
'            PE_EVENTOS_PERFIL x',
'    where c.cod_empresa = c.cod_empresa',
'    and b.cod = c.cod_ocorr',
'    --and c.tipo_rubrica in (1, 3)',
'    AND c.tipo = :P13_TIPO_NOVO',
'    and c.cod_empresa = :P13_COD_EMPRESA',
'    and ''BANCO'' = :P13_TIPO_EVENTO_NOVO',
'    and  x.cod_empresa(+) = :P13_COD_EMPRESA',
'    and x.cd_perfil(+) = :P_PERFIL',
'    AND X.COD_EVENTO(+) = C.cod_evento_banco',
'        AND C.COEFICIENTE = :P13_COEFICIENTE',
'',
'union',
'select c.cod_evento_banco||'' - ''||c.descricao, c.cod_evento_banco',
'    from pe_eventos_BANCO c,',
'            ocorr_pagto b,',
'             PE_EVENTOS_PERFIL x',
'    where c.cod_empresa = c.cod_empresa',
'    and b.cod = c.cod_ocorr',
'    --and c.tipo_rubrica in (1, 3)',
'    AND c.tipo = :P13_TIPO_NOVO',
'    and c.cod_empresa = :P13_COD_EMPRESA',
'    and ''BANCO'' = :P13_TIPO_EVENTO_NOVO',
'    and  x.cod_empresa(+) = :P13_COD_EMPRESA',
'    and x.cd_perfil(+) = :P_PERFIL',
'    AND X.COD_EVENTO(+) = C.cod_evento_banco',
'        AND C.COEFICIENTE = :P13_COEFICIENTE',
'',
'order by 2  ',
''))
