,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_status varchar2(1);',
'BEGIN',
'    FOR I IN (SELECT * FROM PE_BANCO_FOLHA_TEMP',
'             WHERE USUARIO = :P_USUARIO)',
'    LOOP       ',
'        IF I.SELECIONADO = ''S'' THEN',
'            v_status := ''N'';',
'        ELSE',
'            v_status := ''S'';        ',
'        END IF;',
'        update PE_BANCO_FOLHA_TEMP  set  SELECIONADO = v_status',
'        WHERE USUARIO = :P_USUARIO',
'        AND COD_EMPRESA = I.COD_EMPRESA',
'        AND MATRICULA = I.MATRICULA;',
'',
'    END LOOP;',
'',
'END;'))
,p_attribute_02=>'P13_COD_EMPRESA,P13_MATRICULA'
,p_wait_for_result=>'Y'
);
