wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(69556582821994143524)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Selecionar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'null;',
'/*declare',
'    v_erro varchar2(4000);',
'    v_retornoC    varchar2(50);',
'    v_retornoD    varchar2(50);',
'    v_retorno   varchar2(50);',
'',
'    v_saldoC varchar2(20);',
'    v_saldoD varchar2(20);',
'    v_saldot varchar2(20);',
'    ',
'    v_banco    pe_eventos_banco.cod_evento_banco%type;',
'    v_folha    pe_eventos_folha.cod_evento_folha%type;',
'    ',
'begin',
'',
'    delete from PE_BANCO_FOLHA_TEMP',
'    where usuario = :P_USUARIO;',
'    COMMIT;',
'    ',
'    ',
'    FOR I IN (select DISTINCT i.COD_EMPRESA, i.MATRICULA ,',
'              pkg_AdmPessFreqLancamentoBH.calculaHoras( ',
'                         p_cod_empresa => :P13_COD_EMPRESA',
'                       , p_cod_evento  => :P13_COD_EVENTO',
'                       , p_matricula   => i.MATRICULA',
'                       , p_data_ini   => :P13_DTINI',
'                       , p_data_fim  => :P13_DTFIM ) SALDO  ',
'                  from informacoes_funcionais i , pe_resultado_apuracao a',
'             where a.cod_empresa = i.cod_empresa',
'             and a.matricula = i.matricula',
'               and i.cod_empresa = :P13_COD_EMPRESA',
'             and FILIAL = NVL( :P13_FILIAL, FILIAL )',
'              and COD_CCUSTO = NVL( :P13_CCUSTO, COD_CCUSTO )',
'             and SITUACAO < ''90''',
'              and MARCA_PONTO = ''S'' ',
'              AND I.MATRICULA = NVL(:P13_MATRICULA, I.MATRICULA)',
'              --',
'             and data between :P13_DTINI and :P13_DTFIM',
'             and cod_evento = :P13_COD_EVENTO',
'              ',
'             and pkg_AdmPessFreqLancamentoBH.calculaHoras( ',
'                         p_cod_empresa => :P13_COD_EMPRESA',
'                       , p_cod_evento  => :P13_COD_EVENTO',
'                       , p_matricula   => i.MATRICULA',
'                       , p_data_ini   => :P13_DTINI',
'                       , p_data_fim  => :P13_DTFIM ) != ''00:00''',
' ',
'             GROUP BY i.cod_empresa, i.matricula)',
'    LOOP',
'        BEGIN',
'        ',
'            IF :P13_TIPO_EVENTO = ''BANCO'' THEN',
'                v_banco := :P13_COD_EVENTO;',
'            ELSE',
'                v_folha :=  :P13_COD_EVENTO;',
'            END IF;',
'            ',
'           ',
'           v_retorno :=               pkg_AdmPessFreqLancamentoBH.calculaHoras( ',
'                         p_cod_empresa => :P13_COD_EMPRESA',
'                       , p_cod_evento  => :P13_COD_EVENTO',
'                       , p_matricula   => i.MATRICULA',
'                       , p_data_ini   => :P13_DTINI',
'                       , p_data_fim  => :P13_DTFIM );',
'',
'            delete from testex where texto like ''ANDRE%'';',
'            insert into testex values (-1, ''ANDRE - v_retorno = ''||v_retorno);',
'            insert into testex values (-1, ''ANDRE - I.SALDO = ''||v_retorno);',
'            commit;',
'            ',
'            ',
'            ',
'            ',
'            ',
'            INSERT INTO PE_BANCO_FOLHA_TEMP ',
'                (  cod_empresa,',
'                      matricula ,',
'                      --dt_inicio,',
'                      --dt_final,',
'                      filial,',
'                      cod_ccusto,',
'                      cod_evento_banco,',
'                      cod_evemto_folha,',
'                      cod_justificativa,',
'                      data_pagto,',
'                      --total_saldo,',
'                      per_saldo,',
'                      per_credito,',
'                      per_debito,',
'                      seq_id,',
'                      usuario)',
'            VALUES (:P13_COD_EMPRESA, ',
'                        I.MATRICULA,                         ',
'                        --i.DATA,',
'                        --:P13_DTFIM,',
'                        :P13_FILIAL,',
'                        :P13_CCUSTO, ',
'                        v_banco,',
'                        v_folha,',
'                        NULL,',
'                        SYSDATE,',
'                        --v_retorno,',
'                        NULL,',
'                        NULL,',
'                        NULL,',
'                        :P13_SEQ,',
'                        :P_USUARIO',
'                        );',
'',
'        exception',
'                when others then',
'                    v_erro  := SQLERRM;',
'        end;',
'    end loop;',
'    commit;',
'',
'end;',
'*/'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(68238993102526438269)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Processar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_saldoT  varchar2(10);',
'    v_erro    varchar(4000);',
'     ',
'BEGIN',
'    FOR I IN (SELECT * FROM PE_BANCO_FOLHA_TEMP',
'             WHERE SELECIONADO = ''S''',
'             AND USUARIO = :P_USUARIO)',
'    LOOP         ',
'',
'       v_saldoT := pkg_AdmPessFreqLancamentoBH.calculaHoras( ',
'                         p_cod_empresa => :P13_COD_EMPRESA',
'                       , p_cod_evento  => :P13_COD_EVENTO',
'                       , p_matricula   => I.MATRICULA --APEX_APPLICATION.G_F01(r) ',
'                       , p_data_ini   => :P13_DTINI',
'                       , p_data_fim  => :P13_DTFIM );',
'        BEGIN',
'        ',
'          pkg_AdmPessFreqLancamentoBH.prc_InsereLinha(p_cod_empresa  => :P13_COD_EMPRESA,',
'                                p_matricula            => I.MATRICULA, ',
'                                p_qtd_horas            => v_saldoT,',
'                                p_tipo_evento          => :P13_TIPO_EVENTO,',
'                                p_tipo                 => :P13_TIPO,',
'                                p_cod_evento           => :P13_COD_EVENTO,',
'                                p_tipo_evento_novo     => :P13_TIPO_EVENTO_NOVO,',
'                                p_tipo_novo            => :P13_TIPO,',
'                                p_cod_evento_novo      => :P13_COD_EVENTO_NOVO,',
'                                p_justificativa        => :P13_COD_JUSTIFICATIVA,',
'                                p_data_ini             => :P13_DTINI,',
'                                p_data_fim             => :P13_DTFIM,',
'                                p_data_pagto           => :P13_DTFIM,',
'                                p_usuario              => :P_USUARIO,',
'                                p_msg                  => v_erro) ;',
'              ',
'            if v_erro is not null then',
'                APEX_ERROR.ADD_ERROR (',
'                    p_message          => ''Erro ao processar.''||v_erro,',
'                    p_display_location => apex_error.c_inline_in_notification',
'                );',
'            end if;',
'        END;    ',
'    END LOOP;',
'',
'    :P13_TIPO_EVENTO_NOVO := NULL;',
'    :P13_TIPO_NOVO := NULL;',
'    :P13_COD_EVENTO_NOVO := NULL;',
'    :P13_COD_JUSTIFICATIVA := NULL;',
'    --',
'    ',
'    DELETE FROM PE_BANCO_FOLHA_TEMP ',
'    WHERE USUARIO = :P_USUARIO;',
'    COMMIT;',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(69556583123962143527)
,p_process_success_message=>unistr('Lan\00E7amentos criados com sucesso')
);
