wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(196793958321517134678)
,p_validation_name=>'Data Limite'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'	--',
'	v_data_ref_ponto DATE;',
'	--',
'BEGIN',
'	--',
'  BEGIN',
'	  --',
'	  SELECT NVL(data_ref_ponto,TRUNC(SYSDATE))',
'	    INTO v_data_ref_ponto',
'	    FROM parametros_recursos_humanos',
'	   WHERE cod_empresa = :P14_emp;',
'  --',
'  EXCEPTION',
'  	--',
'	  WHEN OTHERS THEN',
'	    --',
'	    v_data_ref_ponto := TRUNC(SYSDATE);',
'  --',
'  END;',
'  --',
'  IF :P14_data < v_data_ref_ponto THEN',
'	  --',
'     return(''Data fora do limite permitido: '' || v_data_ref_ponto);',
'  --',
'  END IF;',
'--',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_message=>'Erro'
,p_associated_item=>wwv_flow_api.id(196793954639026134673)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(196793958561752134678)
,p_validation_name=>'Data Existente'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'cursor c1 is',
'	select count(*) tot',
'	from   pe_tratamento_batimentos',
'	where cod_empresa = :p14_emp',
'	and   matricula   = :p14_mat',
'	and   nvl(vira_dia,data_ponto)         = :p14_data',
'	and  (posicao     = 1 and ''S'' = ''N'' or ''S'' = ''S'');',
'	v_c1 c1%rowtype;',
'	v_imp number;',
'begin',
'',
'	open  c1;',
'	fetch c1 into v_c1;',
'	close c1;',
'',
'	if v_c1.tot > 0 and ''S'' = ''S'' then',
unistr('		return(''Data j\00E1 cadastrada!'');'),
'    END IF;',
'',
'end;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_message=>unistr('Valida\00E7\00E3o')
,p_when_button_pressed=>wwv_flow_api.id(219561989355061691311)
,p_associated_item=>wwv_flow_api.id(196793954639026134673)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(153943236321045312265)
,p_validation_name=>'Verifica se tem plantao'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_conta number := 0;',
'begin',
'    if :P14_OPCAO_PLANTAO in (''P'', ''Q'') then',
'        select nvl(count(*), 0)',
'        into v_conta',
'         from pe_escalas_excecoes pee',
'        where 1=1--',
'        and cod_empresa = :P14_EMP',
'        and matricula = :P14_MAT',
'        and :P14_DATA between inicio and fim',
'        and escala_plantao = ''S'';',
'',
'        if v_conta = 0  then',
unistr('            return ''N\00E3o pode ser criada esta data pois colaboraor n\00E3o tem plant\00E3o'';'),
'        end if;',
'    end if;    ',
'end;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_associated_item=>wwv_flow_api.id(196793954639026134673)
