,p_process_name=>'popula_campos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select cod_empresa, matricula, data_ponto, vira_dia, hora_batida, hora_batida_abono, posicao, cod_justificativa, comentarios',
'  from pe_tratamento_batimentos',
' where cod_empresa = :p14_emp',
'   and matricula = :p14_mat',
'   and nvl(vira_dia,data_ponto) = :p14_data',
'   and posicao = :p14_posicao;',
'   ',
'v_c1 c1%rowtype;',
'',
'cursor c2 is',
'SELECT HORARIO, POSICAO',
'  FROM PE_JORNADAS_COMPOSICAO',
' WHERE COD_JORNADA = Fnct_Pe_Retorna_Jornada( :p14_emp,:p14_mat, :P14_DATA )',
'   AND POSICAO = :p14_posicao',
' order by 2;',
' ',
'v_c2 c2%rowtype;',
'',
'begin',
'',
'EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= ''''.,'''' '';',
'',
'BEGIN',
'PKG_IDIOMA.SETA_IDIOMA(''AMERICAN'');',
'END;',
'',
'    open  c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'',
'    open  c2;',
'    fetch c2 into v_c2;',
'    close c2;',
'',
'    :p14_jornada           := v_c2.horario;',
'',
'    if v_c1.cod_empresa is not null then ',
'    ',
'        :p14_data_ponto        := v_c1.data_ponto;',
'        :p14_vira_dia          := v_c1.vira_dia;',
'        :p14_hora_batida       := to_char(v_c1.hora_batida,''hh24:mi'');',
'        :p14_hora_batida_abono := to_char(v_c1.hora_batida_abono,''hh24:mi'');',
'        :p14_posicao           := v_c1.posicao;',
'        :p14_cod_justificativa := v_c1.cod_justificativa;',
'        :p14_comentarios       := v_c1.comentarios;',
'    ',
'    end if;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
