'    select case :P14_OPCAO_PLANTAO',
'        when ''F'' then',
'        ''Final''',
'        when ''O'' then',
'        ''Original''',
'        when ''T'' then',
'        ''Todos''',
'        when ''R'' then',
unistr('        ''Requisi\00E7\00E3o'''),
'        when ''P'' then',
unistr('        ''Plant\00E3o Original'''),
'        when ''Q'' then',
unistr('        ''Plant\00E3o Abonado'''),
'        else',
'        ''Todos''',
'        end  tipo',
'    INTO  :P14_OPCAO_PLANTAO_DSP',
'    FROM DUAL;',
'exception',
'    when others then',
'        :P14_OPCAO_PLANTAO := ''F'';',
'end;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
