,p_process_name=>'Popula Campos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'if :P19_FILTRO_DT_INI is null then',
':P19_FILTRO_DT_INI := sysdate;',
'end if;',
'',
'if :P19_FILTRO_DT_FIM is null then',
':P19_FILTRO_DT_FIM := sysdate;',
'end if;',
'',
'',
'if :P19_REPROCESSAR = ''S'' then',
'    select cod_empresa||'' - ''||nome',
'        into :P19_COD_EMPRESA',
'    from empresas ',
'    where COD_EMPRESA = :P19_FILTRO_EMP;',
'',
'    select matricula||'' - ''||nome',
'        into :P19_MATRICULA',
'        from inf_pessoais',
'        where matricula = :P19_FILTRO_MAT',
'        and cod_empresa = :P19_FILTRO_EMP;',
'',
'end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
