'SELECT x.cod_empresa',
'      ,x.matricula',
'      ,(SELECT e.cod||''-''||e.nome FROM empresas_cad e WHERE e.cod = x.cod_empresa) empresa',
'      ,(SELECT p.matricula||''-''||p.nome FROM inf_pessoais_cad p WHERE p.cod_empresa = x.cod_empresa AND p.matricula = x.matricula) colaborador ',
'  FROM TABLE(PKG_PE_ABONO.fnc_ListLimiteAbono(pEscala     => :p33_escala',
'                                             ,pJornada    => :p33_jornada',
'                                             ,pJornadaDsp => :p33_jornada_display',
'                                             ,pEmpresas   => :p33_empresas_ind',
'                                             ,pFiliais    => :p33_filiais_ind',
'                                             ,pCCustos    => :p33_ccusto_ind',
'                                             ,pCcustoCont => :p33_ccusto_cont_ind',
'                                             ,pCargos     => :p33_cargos_ind',
'                                             ,pSituacoes  => :p33_situacoes_ind',
'                                             ,pVinculos   => :p33_vinculos_ind',
'                                             ,pSindicatos => :p33_sindicatos_ind',
'                                             ,pMatriculas => :p33_matriculas_ind',
'                                             ,pDataIniDsp => :P33_DATA_INI_DISPLAY',
'                                             ,pDataFimDsp => :P33_DATA_FIM_DISPLAY',
'                                             ,pDtAbonoIni => :P33_DATA_ABONO_INI',
'                                             ,pDtAbonoFim => :P33_DATA_ABONO_FIM',
'                                             ,pSeq        => :p33_seq',
'                                             ,pQtdAbono   => :P33_LIMITE_ABONO',
'                                             ,pUser       => :p_usuario',
'                                             ,pPainel     => :P_PAINEL)) x',
' WHERE x.limitesn = ''S''',
'ORDER BY 1,2'))
