,p_display_sequence=>60
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:js-showMaximizeButton:t-Region--scrollBody:t-Form--slimPadding:t-Form--stretchInputs:t-Form--labelsAbove'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'BODY'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  select cod_evento||'' - ''||INITCAP(descricao) descricao, to_hours(nvl(fnct_tot_horas(nvl(sum(horas),0), nvl(sum(minutos),0)),0)) horas, ''Banco'' TIPO',
'  from (  SELECT  sum(SUBSTR(RA.QTD_HORAS, 1, INSTR(RA.QTD_HORAS, '':'')-1)) horas, ',
'                 sum(SUBSTR(RA.QTD_HORAS, INSTR(RA.QTD_HORAS,'':'')+1) ) minutos,',
'                 ef.cod_evento_banco cod_evento, ef.descricao, ef.cod_ocorr',
'          FROM PE_RESULTADO_APURACAO ra, ',
'               PE_EVENTOS_BANCO ef,',
'               temp_abono t',
'          WHERE ra.cod_empresa = ef.cod_empresa ',
'          AND ra.cod_evento = ef.cod_evento_banco',
'          and ra.cod_empresa = t.cod_empresa',
'          and ra.matricula = t.matricula',
'          AND ra.data  between TO_DATE(:P33_DATA_INI_DISPLAY,''DD/MM/RRRR'') and TO_DATE(:P33_DATA_FIM_DISPLAY,''DD/MM/RRRR'')',
'          AND ra.BH_APURADO = ''A''',
'          AND ra.tipo_evento = ''BANCO''',
'          and ((:p_base <> ''PREVCOM'' and ef.cod_ocorr < 500) or (:p_base = ''PREVCOM'' and ef.cod_ocorr < 5000))',
'        group by ef.cod_evento_banco, ef.descricao, ef.cod_ocorr)',
'        group by cod_evento, descricao, cod_ocorr',
'  union all',
'  select cod_evento||'' - ''||INITCAP(descricao) descricao, to_hours(nvl(fnct_tot_horas(nvl(sum(horas),0), nvl(sum(minutos),0)),0)) horas, ''Ponto'' TIPO',
'  from (  SELECT  sum(SUBSTR(RA.QTD_HORAS, 1, INSTR(RA.QTD_HORAS, '':'')-1)) horas, ',
'                 sum(SUBSTR(RA.QTD_HORAS, INSTR(RA.QTD_HORAS,'':'')+1) ) minutos,',
'                 ef.cod_evento_folha cod_evento, ef.descricao, ef.cod_ocorr',
'          FROM PE_RESULTADO_APURACAO ra, ',
'               PE_EVENTOS_FOLHA ef,',
'               temp_abono t',
'          WHERE ra.cod_empresa = ef.cod_empresa ',
'          AND ra.cod_evento = ef.cod_evento_folha',
'          and ra.cod_empresa = t.cod_empresa',
'          and ra.matricula = t.matricula',
'          AND ra.data  between TO_DATE(:P33_DATA_INI_DISPLAY,''DD/MM/RRRR'') and TO_DATE(:P33_DATA_FIM_DISPLAY,''DD/MM/RRRR'')',
'          AND ra.BH_APURADO = ''A''',
'          AND ra.tipo_evento = ''PONTO''',
'          and ((:p_base <> ''PREVCOM'' and ef.cod_ocorr < 500) or (:p_base = ''PREVCOM'' and ef.cod_ocorr < 5000))',
'        group by ef.cod_evento_folha, ef.descricao, ef.cod_ocorr)',
'   group by cod_evento, descricao, cod_ocorr',
'   order by 3,1'))
,p_ajax_enabled=>'Y'
,p_query_row_template=>wwv_flow_api.id(209353579446682209787)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
