wwv_flow_api.create_report_region(
 p_id=>wwv_flow_api.id(220444754704545004979)
,p_name=>'Colaboradores a serem abonados'
,p_template=>wwv_flow_api.id(209353570635128209771)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody:t-Form--noPadding:t-Form--stretchInputs:t-Form--labelsAbove'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'BODY'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT case when nvl((select dbms_lob.getlength(foto)',
'                              from fotos',
'                             where cod_empresa = i.cod_empresa',
'                               and matricula   = i.matricula), 0) > 0 then',
'               ''<img src="'' ||',
'               ''f?p='' || :APP_ID || '':'' || 1 || '':'' || :APP_SESSION ||',
'               '':APPLICATION_PROCESS=GET_IMG_FUNC:'' || :DEBUG ||',
'               ''&x01='' || i.cod_empresa || ''|'' || i.matricula ||',
'               ''" title="'' || ''colaborador'' || ''" class="fotoColabSmall" style="margin: auto;background-color: white;"/>''',
'             else',
'               ''<img src="#WORKSPACE_IMAGES#PROFILE.jpg" class="fotoColabSmall" style="margin: auto;background-color: white;"/>''',
'             end Foto,',
'       i.cod_empresa COD_EMPRESA, ',
'       i.FILIAL FILIAL, ',
'       i.cod_ccusto COD_CCUSTO, ',
'       i.cod_empresa||'' / ''||i.filial||'' / ''||i.cod_ccusto emp_filial_ccusto,',
'       I.MATRICULA, ',
'       I.MATRICULA||'' - ''||Initcap(fnct_nome_func(i.cod_empresa, i.matricula)) Colaborador, ',
'       Initcap(fnct_nome_situacao(i.situacao)) NOME_SIT_FUNC,',
'       Initcap(fnct_nome_vinculo(i.vinculo)) vinculo,',
unistr('       decode(e.excecao,''S'',''(Exce\00E7\00E3o) - '')||E.cod_escala||'' - ''||Initcap(s.descricao) nome_escala,'),
'       i.cod_localizacao ||'' - ''||Initcap(fnct_nome_local_trab(i.cod_localizacao)) nome_local,',
'       e.cod_jornada||'' - ''||Initcap(j.nome_jornada) nome_jornada,',
'       to_char(e.inicio,''dd/mm/rrrr'')||'' - ''||to_char(e.fim,''dd/mm/rrrr'') periodo_escala,',
'       ''Abonar'' Abonar',
'  FROM INFORMACOES_FUNCIONAIS I,',
'       PE_ESCALAS_EXCECOES E,',
'       pe_escalas s,',
'       pe_jornadas j,',
'       temp_abono_seq t',
' WHERE i.cod_empresa = e.cod_empresa',
'   and i.cod_empresa = t.cod_empresa',
'   and i.matricula = e.matricula',
'   and i.matricula = t.matricula',
'   and e.cod_jornada = j.cod_jornada',
'   and e.cod_escala  = s.cod_escala',
'   and ((I.SITUACAO < ''90'') or (I.SITUACAO > ''90'' and i.dt_situacao between TO_DATE(:P33_DATA_INI_DISPLAY,''DD/MM/RRRR'') and TO_DATE(:P33_DATA_FIM_DISPLAY,''DD/MM/RRRR'')))',
'   and i.marca_ponto = ''S''',
'   and (:p33_data_abono_ini between e.inicio and e.fim',
'    or  :p33_data_abono_fim between e.inicio and e.fim)',
'   and t.seq = :p33_seq',
'order by i.cod_empresa, i.filial, i.cod_ccusto, i.matricula'))
,p_display_condition_type=>'NEVER'
,p_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="runningindicator">',
'Processando, por favor aguarde...',
'<div id="runningindicator-img"></div>',
'</div>'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P33_DATA_INI_DISPLAY,P33_DATA_FIM_DISPLAY,P33_DATA_ABONO_INI,P33_DATA_ABONO_FIM,P33_SEQ'
,p_query_row_template=>wwv_flow_api.id(209353579446682209787)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'-'
,p_query_no_data_found=>'Para ver resultados, filtre sua pesquisa.'
,p_query_num_rows_type=>'ROW_RANGES_IN_SELECT_LIST'
,p_pagination_display_position=>'BOTTOM_RIGHT'
