wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(196794126525618190294)
,p_name=>'P33_JORNADA_DISPLAY'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_api.id(220444763026062004990)
,p_prompt=>'Jornada'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT distinct e.cod_jornada||'' - ''||Initcap(j.nome_jornada) nome_jornada',
'  FROM INFORMACOES_FUNCIONAIS I,',
'       CENTRO_DE_CUSTO C,',
'       PE_ESCALAS_EXCECOES E,',
'       pe_escalas s,',
'       pe_jornadas j',
' WHERE i.cod_empresa = c.cod_empresa',
'   and i.cod_empresa = e.cod_empresa',
'   and i.cod_ccusto = c.cod',
'   and i.matricula = e.matricula',
'   and e.cod_jornada = j.cod_jornada',
'   and e.cod_escala  = s.cod_escala',
'   and e.cod_escala  = nvl(:p33_escala,e.cod_escala)',
'   and e.cod_jornada = :p33_jornada',
'   and I.SITUACAO < ''90''',
'   and i.marca_ponto = ''S''',
'   AND (I.COD_CCUSTO IN (SELECT X.COD',
'                           FROM CENTRO_DE_CUSTO X',
'                          WHERE X.MATRICULA_GESTOR IN (SELECT U.CD_MATRICULA ',
'                                                         FROM USUARIO_ORACLE U  ',
'                                                        WHERE U.NM_USUARIO_ORACLE = :P_USUARIO)))'))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT distinct e.cod_jornada||'' - ''||Initcap(j.nome_jornada) nome_jornada, e.cod_jornada',
'  FROM INFORMACOES_FUNCIONAIS I,',
'       CENTRO_DE_CUSTO C,',
'       PE_ESCALAS_EXCECOES E,',
'       pe_escalas s,',
'       pe_jornadas j,',
'       temp_abono_seq t',
' WHERE i.cod_empresa = c.cod_empresa',
'   and i.cod_empresa = e.cod_empresa',
'   and i.cod_ccusto = c.cod',
'   and i.matricula = e.matricula',
'   and e.cod_jornada = j.cod_jornada',
'   and e.cod_escala  = s.cod_escala',
'   and i.cod_empresa = t.cod_empresa',
'   and i.matricula = t.matricula',
'   and t.seq = :p33_seq',
'   --and e.cod_escala  = :p33_escala',
'   --and e.cod_jornada = :p33_jornada',
'   and I.SITUACAO < ''90''',
'   and i.marca_ponto = ''S'''))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Selecione -'
,p_lov_cascade_parent_items=>'P33_ESCALA,P33_JORNADA'
,p_ajax_optimize_refresh=>'N'
,p_cHeight=>1
,p_field_template=>wwv_flow_api.id(209353591083850209808)
,p_item_template_options=>'#DEFAULT#'
