,p_name=>'P33_COD_JUSTIFICATIVA_1'
,p_item_sequence=>510
,p_item_plug_id=>wwv_flow_api.id(220444763026062004990)
,p_prompt=>'Justificativa'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
' select cod_justificativa||'' - ''||descricao descricao, cod_justificativa',
'  from pe_tipo_justificativa',
' where cod_empresa = nvl(:P33_EMPRESAS_IND, cod_empresa)',
'  and (select count(*) from  PE_EVENTOS_PERFIL_JUST pepj',
' where cd_perfil = :P_PERFIL',
' and cod_empresa = nvl( :P33_EMPRESAS_IND ,cod_empresa)) = 0',
' union',
' select (select COD_JUSTIFICATIVA||'' - ''||DESCRICAO ',
'        FROM PE_TIPO_JUSTIFICATIVA ptj',
'        WHERE COD_empresa = :P33_EMPRESAS_IND',
'        and ptj.cod_justificativa =  pepj.cod_justificativa) , COD_JUSTIFICATIVA',
'  from PE_EVENTOS_PERFIL_JUST pepj',
' where cd_perfil = :P_PERFIL',
' and cod_empresa = nvl( :P33_EMPRESAS_IND ,cod_empresa)',
' order by 2',
' '))
,p_lov_display_null=>'YES'
,p_cHeight=>1
,p_colspan=>3
,p_grid_label_column_span=>2
,p_field_template=>wwv_flow_api.id(209353590986122209808)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'NONE'
,p_attribute_02=>'N'
);
