wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(196794174591580190336)
,p_name=>'P33_EMPRESAS_IND'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_api.id(220444739464556004957)
,p_prompt=>'Empresas'
,p_placeholder=>'- Selecione -'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct e.cod||'' - ''||Initcap(e.nome) descricao, e.cod cod ',
'from empresas e',
'where ((:p_painel = ''PO'') or (nvl(dt_encerramento,trunc(sysdate)) >= trunc(sysdate)))',
'  and e.cod in (select i.cod_empresa ',
'                  from informacoes_funcionais i ',
'                 where i.marca_ponto = ''S'' ',
'                   and ((I.SITUACAO < ''90'') or ',
'                        (I.SITUACAO > ''90'' and ',
'                         i.dt_situacao between TO_DATE(:P33_DATA_INI_DISPLAY,''DD/MM/RRRR'') and TO_DATE(:P33_DATA_FIM_DISPLAY,''DD/MM/RRRR''))))',
' order by 2'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Selecione -'
,p_lov_cascade_parent_items=>'P33_DATA_INI_DISPLAY,P33_DATA_FIM_DISPLAY'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>30
,p_field_template=>wwv_flow_api.id(209353591245558209809)
,p_item_template_options=>'#DEFAULT#'
