,p_placeholder=>'- Selecione -'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
' select distinct x.cod_filial||'' - ''||initcap(x.nome_filial) descricao, x.cod_filial cod',
'   from filiais x',
'  where ((:P_PAINEL = ''PO'') or (encer_ativ = ''N'' AND SIT NOT IN (''E'',''I'')))',
'    and ((instr('',''||:p33_empresas_ind||'','','',''||x.cod_empresa||'','') > 0) or (:p33_empresas_ind is null))',
'    and (x.cod_empresa, x.cod_filial) in (select i.cod_empresa, i.filial ',
'                                          from informacoes_funcionais i ',
'                                         where i.marca_ponto = ''S'' and ((I.SITUACAO < ''90'') or (I.SITUACAO > ''90'' and i.dt_situacao between TO_DATE(:P33_DATA_INI_DISPLAY,''DD/MM/RRRR'') and TO_DATE(:P33_DATA_FIM_DISPLAY,''DD/MM/RRRR''))))',
' order by 2'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Todos -'
