wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(196794218618092190373)
,p_event_id=>wwv_flow_api.id(196794218052061190373)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c2 is',
'SELECT HORARIO, POSICAO',
'  FROM PE_JORNADAS_COMPOSICAO',
' WHERE COD_JORNADA = nvl(:P33_JORNADA_DISPLAY,:P33_JORNADA)',
' order by 2;',
' ',
'v_c2 c2%rowtype;',
'',
'begin',
'',
'EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= ''''.,'''' '';',
'',
'BEGIN',
'  PKG_IDIOMA.SETA_IDIOMA(''AMERICAN'');',
'END;',
'',
':p33_marcacao := ''A'';',
'',
':p33_posicao_1           := 1;',
':p33_posicao_2           := 2;',
':p33_posicao_3           := 3;',
':p33_posicao_4           := 4;',
':p33_posicao_5           := 5;',
':p33_posicao_6           := 6;',
':p33_posicao_7           := 7;',
':p33_posicao_8           := 8;',
':p33_posicao_9           := 9;',
':p33_posicao_10          := 10;',
'',
':p33_jornada_1       := null;',
':p33_jornada_2       := null;',
':p33_jornada_3       := null;',
':p33_jornada_4       := null;',
':p33_jornada_5       := null;',
':p33_jornada_6       := null;',
':p33_jornada_7       := null;      ',
':p33_jornada_8       := null;',
':p33_jornada_9       := null;',
':p33_jornada_10      := null;',
'',
'for l2 in c2',
'loop',
'',
'    if l2.posicao = 1 then',
'',
'        :p33_jornada_1       := l2.horario;',
'    ',
'    elsif l2.posicao = 2 then',
'',
'        :p33_jornada_2       := l2.horario;',
'    ',
'    elsif l2.posicao = 3 then',
'',
'        :p33_jornada_3       := l2.horario;',
'    ',
'    elsif l2.posicao = 4 then',
'',
'        :p33_jornada_4       := l2.horario;',
'    ',
'    elsif l2.posicao = 5 then',
'',
'        :p33_jornada_5       := l2.horario;',
'    ',
'    elsif l2.posicao = 6 then',
'    ',
'        :p33_jornada_6       := l2.horario;',
'    ',
'    elsif l2.posicao = 7 then',
'',
'        :p33_jornada_7       := l2.horario;',
'        ',
'    elsif l2.posicao = 8 then',
'    ',
'        :p33_jornada_8       := l2.horario;',
'        ',
'    elsif l2.posicao = 9 then',
'',
'        :p33_jornada_9       := l2.horario;',
'        ',
'    elsif l2.posicao = 10 then',
'    ',
'        :p33_jornada_10       := l2.horario;',
'    ',
'    end if;',
'',
'end loop;',
'',
'end;'))
,p_attribute_02=>'P33_JORNADA_DISPLAY,P33_JORNADA'
,p_attribute_03=>'P33_MARCACAO,P33_POSICAO_1,P33_POSICAO_2,P33_POSICAO_3,P33_POSICAO_4,P33_POSICAO_5,P33_POSICAO_6,P33_POSICAO_7,P33_POSICAO_8,P33_POSICAO_9,P33_POSICAO_10,P33_JORNADA_1,P33_JORNADA_2,P33_JORNADA_3,P33_JORNADA_4,P33_JORNADA_5,P33_JORNADA_6,P33_JORNADA_'
||'7,P33_JORNADA_8,P33_JORNADA_9,P33_JORNADA_10'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
