 p_id=>wwv_flow_api.id(197412296507438286506)
,p_event_id=>wwv_flow_api.id(197412296089422286505)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- Verifica Per\00EDodo Abono - Painel'),
'DECLARE',
'  vReturn    VARCHAR2(550) DEFAULT NULL;',
'  --',
'  vMsg    VARCHAR2(550) DEFAULT NULL;',
'BEGIN',
'  :P33_MSG_CLOSE  := NULL;',
'  :P33_CLOSE_PAGE := NULL;',
'  --',
'  IF :P33_EMPRESAS_IND IS NOT NULL AND :P33_DATA_ABONO_INI IS NOT NULL THEN',
'    vMsg := PKG_PE_ABONO.fnc_ValPeriodoAbonoPainel(pEmpresa   => :P33_EMPRESAS_IND',
'                                                  ,pUser      => :APP_USER',
'                                                  ,pPainel    => :P_PAINEL',
'                                                  ,pdata      => TRUNC(SYSDATE)',
'                                                  ,pPerIniPto => :P33_DATA_ABONO_INI);',
'    --',
'    IF vMsg IS NOT NULL THEN',
unistr('      vReturn := ''<strong>Edi\00E7\00E3o N\00C3O Permitida!!</strong><br>'';'),
'      vReturn := vReturn||REPLACE(REPLACE(REPLACE(REPLACE(vMsg, ''|'', ''<br>''), ''['',''<strong>''), '']'',''</strong>''), ''- '');',
'      --',
'      :P33_MSG_CLOSE  := vReturn;',
'      :P33_CLOSE_PAGE := ''S'';',
'    END IF;',
'  END IF;',
'  --',
'  /*IF vMsg IS NULL THEN',
'    IF :P33_JORNADA_DISPLAY IS NULL THEN',
unistr('       vReturn := ''<strong>JORNADA deve ser informada!!</strong><br><i>Utilize o bot\00E3o FILTRAR e realize a pesquisa.</i>'';'),
'      --',
'      :P33_MSG_CLOSE  := vReturn;',
'      :P33_CLOSE_PAGE := ''S'';         ',
'    END IF;  ',
'  END IF;*/',
'END;'))
,p_attribute_02=>'P33_EMPRESAS_IND,P33_DATA_ABONO_INI,P33_MSG_CLOSE,P33_CLOSE_PAGE'
,p_attribute_03=>'P33_MSG_CLOSE,P33_CLOSE_PAGE'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
