,p_process_sequence=>10
,p_process_point=>'AFTER_FOOTER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE_TEMP_ABONO'
,p_process_sql_clob=>'DELETE FROM TEMP_ABONO; COMMIT;'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196794189181424190350)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_TEMP_ABONO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'  delete from temp_abono_seq where seq = :p33_seq;',
'if',
':p33_escala is not null or',
':p33_jornada is not null or',
':p33_empresas_ind is not null or',
':p33_filiais_ind is not null or',
':p33_ccusto_ind is not null or',
':p33_ccusto_cont_ind is not null or',
':p33_cargos_ind is not null or',
':p33_situacoes_ind is not null or',
':p33_vinculos_ind is not null or',
':p33_sindicatos_ind is not null or',
':p33_matriculas_ind is not null or',
':P33_JORNADA_PLANTAO is not null or',
':P33_TIPO_JORNADA is not null then',
'',
'insert into temp_abono_seq  (',
'SELECT distinct',
'       i.cod_empresa, ',
'       I.MATRICULA,',
'       e.cod_escala,',
'       e.cod_jornada,',
'       :p33_seq',
'  FROM INFORMACOES_FUNCIONAIS_CAD I,',
'       CENTRO_DE_CUSTO C,',
'       PE_ESCALAS_EXCECOES E,',
'       pe_escalas s,',
'       pe_jornadas j',
' WHERE i.cod_empresa = c.cod_empresa',
'   and i.cod_empresa = e.cod_empresa',
'   and i.cod_ccusto = c.cod',
'   and i.matricula = e.matricula',
'   and e.cod_jornada = j.cod_jornada',
'   and e.cod_escala  = s.cod_escala',
'   and e.cod_escala = nvl(:p33_escala, e.cod_escala)',
'   and e.cod_jornada = nvl(nvl(:p33_jornada,:p33_jornada_display),e.cod_jornada)',
'   and j.jornada_plantao = nvl(:P33_JORNADA_PLANTAO,j.jornada_plantao)',
'   and j.tipo_jornada = nvl(:P33_TIPO_JORNADA,j.tipo_jornada)',
'   and ((i.cod_empresa  in (:p33_empresas_ind))  or (:p33_empresas_ind is null))',
'   and ((i.filial       in (:p33_filiais_ind))   or (:p33_filiais_ind is null))',
'   and ((instr('',''||:p33_ccusto_ind||'','','',''||i.cod_ccusto||'','') > 0)  or (:p33_ccusto_ind is null))',
'   and ((instr('',''||:p33_ccusto_cont_ind||'','','',''||fnct_retorna_ccusto_cont(i.cod_empresa, i.cod_ccusto)||'','') > 0) or (:p33_ccusto_cont_ind is null))',
'   and ((instr('',''||:p33_cargos_ind||'','','',''||i.cargo||'','') > 0) or (:p33_cargos_ind is null))',
'   and ((instr('',''||:p33_situacoes_ind||'','','',''||i.situacao||'','') > 0) or (:p33_situacoes_ind is null))',
'   and ((instr('',''||:p33_vinculos_ind||'','','',''||i.vinculo||'','') > 0)  or (:p33_vinculos_ind is null))',
'   and ((instr('',''||:p33_sindicatos_ind||'','','',''||i.num_sind_diss||'','') > 0)  or (:p33_sindicatos_ind is null))',
'   and ((instr('',''||:p33_matriculas_ind||'','','',''||i.matricula||'','') > 0)  or (:p33_matriculas_ind is null))',
'   and ((I.SITUACAO < ''90'') or (I.SITUACAO > ''90'' and i.dt_situacao between TO_DATE(:P33_DATA_INI_DISPLAY,''DD/MM/RRRR'') and TO_DATE(:P33_DATA_FIM_DISPLAY,''DD/MM/RRRR'')))',
'   and i.marca_ponto = ''S''',
'   and (:p33_data_abono_ini between e.inicio and e.fim',
'    or  :p33_data_abono_fim between e.inicio and e.fim)',
'  AND f_acesso_pg_apex(i.cod_empresa, i.matricula, i.filial, i.cd_nivel, :p_usuario, :P_PAINEL, ''PONTO'') = ''S''',
'  );',
'  ',
'end if;',
'',
'exception',
'when no_data_found then',
'null;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(195908207450812891899)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Limite Abono DEL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  vCont   NUMBER DEFAULT 0;',
'BEGIN',
'  :P33_LIMITE_ABONO := 0;',
'  --',
'  IF :P33_HORA_BATIDA_ABONO_1  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_2  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_3  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_4  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_5  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_6  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_7  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_8  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_9  IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  IF :P33_HORA_BATIDA_ABONO_10 IS NOT NULL THEN vCont := NVL(vCont, 0) + 1; END IF;',
'  --',
'  IF vCont > 0 AND :P33_CTRL_ABONO = ''S'' THEN',
'    :P33_LIMITE_ABONO := vCont;',
'    --',
'    DELETE FROM temp_abono_seq x',
'      WHERE x.seq = :p33_seq',
'        AND PKG_PE_ABONO.fnc_ValLimiteAbono(pEmpresa   => x.cod_empresa',
'                                           ,pMatricula => x.matricula',
'                                           ,pDataIni   => NULL',
'                                           ,pDataFim   => NULL',
'                                           ,pUser      => :p_usuario',
'                                           ,pQtdAbono  => vCont',
'                                           ,pDataAbono => TRUNC(SYSDATE)',
'                                           ,pPainel    => :P_PAINEL) IS NOT NULL; ',
'  END IF;',
'  --',
'  :P33_CTRL_ABONO   := NULL;',
'  --',
'  EXCEPTION',
'    WHEN OTHERS THEN',
'      RAISE_APPLICATION_ERROR(-20900, SQLERRM);',
'END;',
''))
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196794189559266190350)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'prc_adicionar_data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_data_ini date := :P33_DATA_ABONO_INI;--to_date(''20/02/2018'',''dd/mm/rrrr'');',
'v_data_fim date := :P33_DATA_ABONO_FIM;--to_date(''01-mar-2018'',''dd/mm/rrrr'');',
'',
'v_qtd_dias number;',
'',
'v_data date;',
'',
'cursor c_func is',
'SELECT distinct',
'       i.cod_empresa,',
'       I.MATRICULA',
'  FROM TEMP_ABONO I',
'  order by i.cod_empresa, i.matricula;',
'',
'',
'v_cod_importacao number;',
'v_imp number;',
'',
'cursor c_trat(v_emp number, v_mat number, v_data date) is ',
'select nvl(vira_dia, data_ponto) data',
'  from pe_tratamento_batimentos',
' where cod_empresa = v_emp',
'   and matricula = v_mat',
'   and nvl(vira_dia, data_ponto) = v_data;',
'   ',
'v_trat c_trat%rowtype;',
'',
'BEGIN',
'',
'v_qtd_dias := v_data_fim - v_data_ini;',
'',
' for l1 in 0..v_qtd_dias',
' loop',
'',
' v_data := v_data_ini + l1;',
'',
'    for l_func in c_func',
'    loop',
'',
'         open c_trat(l_func.cod_empresa, l_func.matricula, v_data);',
'        fetch c_trat into v_trat;',
'        close c_trat;',
'',
'        if v_trat.data is null then',
'',
'         begin',
'         select distinct cod_importacao',
'           into v_cod_importacao',
'           from pe_tratamento_batimentos',
'          where cod_empresa = l_func.cod_empresa',
'            and matricula = l_func.matricula',
'            and nvl(vira_dia,data_ponto) = v_data',
'            and posicao = 1; ',
'         exception',
'         when others then',
'         v_cod_importacao := null;',
'',
'         end;',
'',
'            Prc_Pe_Imp_Filhos2(l_func.cod_empresa,l_func.cod_empresa,',
'                           l_func.matricula,''N'',',
'                           v_DATA,',
'                             NULL,',
'                             1,NULL,NULL,''A'', NVL(v_cod_importacao,0), v_imp,0, :p_usuario, ',
'                              NULL, null );',
'                              ',
'        end if;',
'        ',
'    end loop;',
'',
'  end loop;',
'',
'END;  '))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(196794125245365190293)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196794189985190190351)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'prc_de_para_escala'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    ',
'    cursor c1 is ',
'    select cod_escala, inicio, fim',
'      from pe_escalas p',
'     where cod_escala = :p33_escala_de;',
'    ',
'    v_c1 c1%rowtype;',
'    ',
'    cursor c2 is ',
'    select cod_escala, inicio, fim',
'      from pe_escalas p',
'     where cod_escala = :p33_escala_para;',
'    ',
'    v_c2 c2%rowtype;    ',
'    ',
'    v_data_ini date;',
'    v_data_fim date;',
'    ',
'    cursor c3 is',
'    select cod_escala, cod_jornada',
'    from pe_escalas_jornadas',
'   where cod_escala = :p33_escala_para;',
'  ',
'  v_c3 c3%rowtype;',
'    ',
'begin',
'    ',
'    open  c1;',
'    fetch c1 into v_c1;',
'    close c1;    ',
'    ',
'    open  c3;',
'    fetch c3 into v_c3;',
'    close c3;            ',
'    ',
'    if nvl(:p33_excecao,''N'') = ''S'' then',
'    /*    if :p33_data_ini >= v_c1.inicio and',
'             :p33_data_fim <= v_c1.fim    then*/',
'         v_data_ini := :p33_data_ini;',
'         v_data_fim := :p33_data_fim;',
'    /*    else ',
'           ',
'        end if;*/',
'    else',
'        ',
'        open  c2;',
'        fetch c2 into v_c2;',
'        close c2;',
'        ',
'        v_data_ini := :p33_data_ini;',
'        v_data_fim := v_c2.fim;',
'        ',
'        update pe_escalas_excecoes',
'           set fim = v_data_ini - 1',
'         where cod_escala = :p33_escala_de',
'           and excecao = ''N'';',
'        ',
'        ',
'        ',
'    end if;',
'',
'     /*update pe_escalas_excecoes',
'        set cod_escala = :p33_escala_para, ',
'                inicio          = v_data_ini, ',
'                fim              = v_data_fim, ',
'                excecao      = :p33_excecao',
'      where cod_escala = :p33_escala_de',
'        and (cod_empresa, matricula) in (select x.cod_empresa, x.matricula from temp_abono x);*/',
'',
'for l1 in (SELECT distinct',
'       i.cod_empresa, ',
'       i.FILIAL, ',
'       i.cod_ccusto, ',
'       I.MATRICULA',
'  FROM INFORMACOES_FUNCIONAIS_CAD I,',
'       CENTRO_DE_CUSTO C,',
'       PE_ESCALAS_EXCECOES E,',
'       pe_escalas s,',
'       pe_jornadas j',
' WHERE i.cod_empresa = c.cod_empresa',
'   and i.cod_empresa = e.cod_empresa',
'   and i.cod_ccusto = c.cod',
'   and i.matricula = e.matricula',
'   and e.cod_jornada = j.cod_jornada',
'   and e.cod_escala  = s.cod_escala',
'   and e.cod_escala = :p33_escala_de',
'   and e.cod_jornada = nvl(:p33_jornada, e.cod_jornada)',
'   and ((i.cod_empresa  in (:p33_empresas_ind))  or (:p33_empresas_ind is null))',
'   and ((i.filial       in (:p33_filiais_ind))   or (:p33_filiais_ind is null))',
'   and ((instr('',''||:p33_ccusto_ind||'','','',''||i.cod_ccusto||'','') > 0)    or (:p33_ccusto_ind is null))',
'   and ((instr('',''||:p33_ccusto_cont_ind||'','','',''||fnct_retorna_ccusto_cont(i.cod_empresa, i.cod_ccusto)||'','') > 0) or (:p33_ccusto_cont_ind is null))',
'   and ((instr('',''||:p33_cargos_ind||'','','',''||i.cargo||'','') > 0) or (:p33_cargos_ind is null))',
'   and ((instr('',''||:p33_situacoes_ind||'','','',''||i.situacao||'','') > 0) or (:p33_situacoes_ind is null))',
'   and ((instr('',''||:p33_vinculos_ind||'','','',''||i.vinculo||'','') > 0)  or (:p33_vinculos_ind is null))',
'   and ((instr('',''||:p33_matriculas_ind||'','','',''||i.matricula||'','') > 0)  or (:p33_matriculas_ind is null))',
'   and I.SITUACAO < ''90''',
'   and i.marca_ponto = ''S''',
'   and v_data_ini >= i.dt_admissao',
'   and F_Acesso_PG_Apex(i.cod_empresa, i.matricula, i.filial, i.cd_nivel, :p_usuario) = ''S''',
'  order by i.cod_empresa, i.filial, i.cod_ccusto, i.matricula',
'                          )',
'loop',
'    begin',
'    insert into ',
'    pe_escalas_excecoes',
'    (cod_escala,',
'     matricula,',
'     inicio,',
'     fim,',
'     cod_empresa,',
'     usuario,',
'     dt_atualizacao,',
'     excecao,',
'     cod_jornada)',
'    values',
'    (:p33_escala_para,',
'     l1.matricula,',
'     v_data_ini,',
'     v_data_fim,',
'     l1.cod_empresa,',
'     :p_usuario,',
'     sysdate,',
'     :p33_excecao,',
'     V_C3.cod_jornada);',
'    ',
'    exception',
'        when DUP_VAL_ON_INDEX then',
'        null;',
'  end;',
'end loop;',
'',
'   commit;',
'',
'end;'))
,p_process_error_message=>'Erro ao alterar escala.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(196794180857672190341)
,p_process_when=>'p33_btn_exec_escala'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>'Escala alterada com Sucesso!'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196794190351806190351)
,p_process_sequence=>80
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'prc_atualiza_batida_todos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_data_ini date := :P33_DATA_ABONO_INI;--to_date(''20/02/2018'',''dd/mm/rrrr'');',
'v_data_fim date := :P33_DATA_ABONO_FIM;--to_date(''01-mar-2018'',''dd/mm/rrrr'');',
'',
'v_qtd_dias number;',
'',
'',
'cursor c_func is',
'SELECT distinct',
'       i.cod_empresa,',
'       I.MATRICULA,',
'       i.seq',
'  FROM TEMP_ABONO_seq I',
'  where i.seq = :p33_seq',
'  order by i.cod_empresa, i.matricula;',
'',
' cursor c_trat(v_emp number, v_mat number, v_data date) is',
' select COD_EMPRESA           ,',
'  MATRICULA            ,',
'  DATA           ,',
'  HORA_BATIDA_1          ,',
'  HORA_BATIDA_ABONO_1    ,',
'  COD_JUSTIFICATIVA_1     ,',
'  COMENTARIOS_1           ,',
'  HORA_BATIDA_2           ,',
'  HORA_BATIDA_ABONO_2     ,',
'  COD_JUSTIFICATIVA_2     ,',
'  COMENTARIOS_2           ,',
'  HORA_BATIDA_3           ,',
'  HORA_BATIDA_ABONO_3     ,',
'  COD_JUSTIFICATIVA_3     ,',
'  COMENTARIOS_3           ,',
'  HORA_BATIDA_4           ,',
'  HORA_BATIDA_ABONO_4     ,',
'  COD_JUSTIFICATIVA_4     ,',
'  COMENTARIOS_4           ,',
'  HORA_BATIDA_5           ,',
'  HORA_BATIDA_ABONO_5     ,',
'  COD_JUSTIFICATIVA_5     ,',
'  COMENTARIOS_5           ,',
'  HORA_BATIDA_6           ,',
'  HORA_BATIDA_ABONO_6     ,',
'  COD_JUSTIFICATIVA_6     ,',
'  COMENTARIOS_6           ,',
'  HORA_BATIDA_7           ,',
'  HORA_BATIDA_ABONO_7     ,',
'  COD_JUSTIFICATIVA_7     ,',
'  COMENTARIOS_7           ,',
'  HORA_BATIDA_8           ,',
'  HORA_BATIDA_ABONO_8     ,',
'  COD_JUSTIFICATIVA_8     ,',
'  COMENTARIOS_8           ,',
'  HORA_BATIDA_9           ,',
'  HORA_BATIDA_ABONO_9     ,',
'  COD_JUSTIFICATIVA_9     ,',
'  COMENTARIOS_9           ,',
'  HORA_BATIDA_10          ,',
'  HORA_BATIDA_ABONO_10    ,',
'  COD_JUSTIFICATIVA_10    ,',
'  COMENTARIOS_10      ',
'   from PE_ABONO_BATIDAS_SEQ',
'  where cod_empresa = v_emp',
'    and matricula = v_mat',
'    and data = v_data',
'    and seq = :p33_seq;',
' ',
' v_trat c_trat%rowtype;',
'',
' v_data            varchar2(10);',
' ',
' v_batida_1        date;',
' v_batida_abono_1  date;',
' v_batida_2        date;',
' v_batida_abono_2  date;',
' v_batida_3        date;',
' v_batida_abono_3  date;',
' v_batida_4        date;',
' v_batida_abono_4  date;',
' v_batida_5        date;',
' v_batida_abono_5  date;',
' v_batida_6        date;',
' v_batida_abono_6  date;',
' v_batida_7        date;',
' v_batida_abono_7  date;',
' v_batida_8        date;',
' v_batida_abono_8  date;',
' v_batida_9        date;',
' v_batida_abono_9  date;',
' v_batida_10       date;',
' v_batida_abono_10 date;       ',
'',
'',
'begin',
'v_qtd_dias := (v_data_fim - v_data_ini);',
'',
'        ',
'    EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= ''''.,'''' '';',
'',
'    BEGIN',
'    PKG_IDIOMA.SETA_IDIOMA(''AMERICAN'');',
'    END;',
'        ',
'',
'    for l1 in 0..v_qtd_dias',
'    loop',
'        v_data := v_data_ini + l1;--:p33_data; --to_Date(:p33_data,''dd/mm/rrrr'');',
'            ',
'        for l_func in c_func',
'        loop',
'         if nvl(:P33_FOLGA_FERIADO,''N'') = ''S'' and',
unistr('            ((nvl(instr(translate(upper(Fnct_Pe_Retorna_Situacao(l_func.cod_empresa,l_func.matricula,v_data)),''\00C9'',''E''),''FERIAS''),0) > 0 and '),
'             Fnct_Pe_Retorna_Situacao(l_func.cod_empresa,l_func.matricula,v_data) is not null) OR',
'            (Fnct_Pe_Verif_Folga(l_func.cod_empresa,l_func.matricula,v_data) = ''S'')) THEN',
'            goto proximo;',
'         end if;',
'',
unistr('         if (nvl(instr(translate(upper(Fnct_Pe_Retorna_Situacao(l_func.cod_empresa,l_func.matricula,v_data)),''\00C9'',''E''),''SIT.: FERIAS''),0) = 0 and '),
'             Fnct_Pe_Retorna_Situacao(l_func.cod_empresa,l_func.matricula,v_data) is not null) THEN',
'         GOTO PROXIMO;         ',
'         END IF;',
'        pkg_pe_abono.prc_pe_abono_batidas(l_func.cod_empresa,',
'                                       l_func.matricula,',
'                                       v_data,',
'                                       v_data,',
'                                       :p33_seq',
'                                       );',
'',
'             open c_trat(l_func.cod_empresa, l_func.matricula, v_data);',
'            fetch c_trat into v_trat;',
'            close c_trat;',
'',
'        ----------------------------------------------------------------------------------------------',
'            ',
'            if v_trat.hora_batida_1 is not null then',
'            v_batida_1 := v_trat.hora_batida_1;',
'            end if;',
'            ',
'            if :p33_hora_batida_abono_1 is not null then',
'            v_batida_abono_1 := to_date(v_data||'' ''||:p33_hora_batida_abono_1,''dd/mm/rrrr hh24:mi'');',
'            end if;',
'            ',
'          --  INSERT INTO TESTEX VALUES (123, V_DATA||'' - ''||v_batida_abono_1); COMMIT;    ',
'            ',
'            if v_trat.hora_batida_2 is not null then',
'            v_batida_2 := v_trat.hora_batida_2;',
'            end if;',
'            ',
'            if :p33_hora_batida_abono_2 is not null then',
'            v_batida_abono_2 := to_date(v_data||'' ''||:p33_hora_batida_abono_2,''dd/mm/rrrr hh24:mi'');',
'            end if;',
'            ',
'            if v_trat.hora_batida_3 is not null then',
'            v_batida_3 := v_trat.hora_batida_3;',
'            end if;',
'            ',
'            if :p33_hora_batida_abono_3 is not null then',
'            v_batida_abono_3 := to_date(v_data||'' ''||:p33_hora_batida_abono_3,''dd/mm/rrrr hh24:mi'');',
'            end if;',
'            ',
'            if v_trat.hora_batida_4 is not null then',
'            v_batida_4 := v_trat.hora_batida_4;',
'            end if;',
'            ',
'            if :p33_hora_batida_abono_4 is not null then',
'            v_batida_abono_4 := to_date(v_data||'' ''||:p33_hora_batida_abono_4,''dd/mm/rrrr hh24:mi'');',
'            end if;',
'            ',
'            if v_trat.hora_batida_5 is not null then',
'            v_batida_5 := v_trat.hora_batida_5;',
'            end if;',
'            ',
'            if :p33_hora_batida_abono_5 is not null then',
'            v_batida_abono_5 := to_date(v_data||'' ''||:p33_hora_batida_abono_5,''dd/mm/rrrr hh24:mi'');',
'            end if;',
'            ',
'            if v_trat.hora_batida_6 is not null then',
'            v_batida_6 := v_trat.hora_batida_6;',
'            end if;',
