'v_data date;',
'',
'v_qtd_dias number;',
'',
'cursor c_func is',
'SELECT distinct',
'       i.cod_empresa,',
'       I.MATRICULA',
'  FROM TEMP_ABONO_SEQ I',
'  WHERE SEQ = :P33_SEQ',
'  order by i.cod_empresa, i.matricula;',
'',
'cursor c1(v_emp number, v_mat number, v_dt date) is',
'select hora_batida, hora_batida_abono, posicao',
'  from pe_tratamento_batimentos',
' where cod_empresa = v_emp',
'   and matricula = v_mat',
'   and nvl(vira_dia, data_ponto) = v_dt',
' order by 3;',
' ',
'v_c1 c1%rowtype;',
'',
'begin',
'v_qtd_dias := v_data_fim - v_data_ini;',
'',
'for l1 in 0..v_qtd_dias',
'loop',
'    v_data := v_data_ini + l1;',
'',
'    for l_func in c_func',
