'                 pkg_pe_abono.prc_deleta_batida_abono(l_func.cod_empresa, l_func.matricula, v_data, l1.posicao, :p_usuario, :p33_seq);',
'           elsif to_char(l1.hora_batida_abono,''hh24:mi'') is not null and :p33_DEL_abono_4 = ''S'' and l1.posicao = 4 then',
'                 pkg_pe_abono.prc_deleta_batida_abono(l_func.cod_empresa, l_func.matricula, v_data, l1.posicao, :p_usuario, :p33_seq);',
'           elsif to_char(l1.hora_batida_abono,''hh24:mi'') is not null and :p33_DEL_abono_5 = ''S'' and l1.posicao = 5 then',
'                 pkg_pe_abono.prc_deleta_batida_abono(l_func.cod_empresa, l_func.matricula, v_data, l1.posicao, :p_usuario, :p33_seq);',
'           elsif to_char(l1.hora_batida_abono,''hh24:mi'') is not null and :p33_DEL_abono_6 = ''S'' and l1.posicao = 6 then',
'                 pkg_pe_abono.prc_deleta_batida_abono(l_func.cod_empresa, l_func.matricula, v_data, l1.posicao, :p_usuario, :p33_seq);',
'           elsif to_char(l1.hora_batida_abono,''hh24:mi'') is not null and :p33_DEL_abono_7 = ''S'' and l1.posicao = 7 then',
'                 pkg_pe_abono.prc_deleta_batida_abono(l_func.cod_empresa, l_func.matricula, v_data, l1.posicao, :p_usuario, :p33_seq);',
