 p_id=>wwv_flow_api.id(154554796174984343775)
,p_event_id=>wwv_flow_api.id(154554795661715343774)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'  v_hora varchar2(100) := :p43_hora;',
'',
'  v_h number;',
'  v_m number;',
'  v_s number;',
'',
'begin',
'',
'  v_h := substr(TRIM(v_hora),0,2);',
'  v_m := substr(TRIM(v_hora),4,2);',
'',
'  if substr(TRIM(v_hora),7,2) + 1 >= 60 then',
'    v_s := 0;',
'    v_m := substr(TRIM(v_hora),4,2)+1;',
'    ',
'      if v_m >= 60 then',
'         v_h := v_h + 1;',
'         ',
'         if v_h >= 24 then',
'           v_h := 0;',
'         end if;',
'         ',
'      end if;',
'  else',
'    v_s := substr(TRIM(v_hora),7,2) + 1;',
'  end if;',
'',
'  :p43_hora := lpad(v_h,2,0)||'':''||lpad(v_m,2,0)||'':''||lpad(v_s,2,0);',
'  :p43_hora_dsp := lpad(v_h,2,0)||'':''||lpad(v_m,2,0)||'':''||lpad(v_s,2,0);',
'',
'end;'))
,p_attribute_02=>'P43_HORA'
,p_attribute_03=>'P43_HORA,P43_HORA_DSP'
,p_attribute_04=>'Y'
,p_wait_for_result=>'Y'
);
