wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(154554788791387343755)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_IP'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'  type t_registro is record (',
'    ip varchar2(255)',
'  );',
'  type t_registros is table of t_registro index by pls_integer;',
'',
'  l_registros t_registros;',
'',
'v_json clob := :p43_json_ip;',
'',
'BEGIN',
'/*',
'{',
'  "ip": "177.215.64.73"',
'}',
'*/',
'',
'IF :p43_ip IS NULL THEN',
'apex_json.parse(v_json);',
'',
'l_registros(1).ip     := apex_json.get_varchar2(p_path =>''ip'' , p0 => 1);',
'',
':p43_ip := l_registros(1).ip;',
'END IF;',
'',
'exception',
'when others then',
':p43_ip := ''Erro ao retornar IP'';',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'MARCAR_PONTO'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(154554789148909343755)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Marcar Ponto'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg varchar2(1);',
'v_msg varchar2(4000);',
'',
'V_DATA DATE;-- := :p43_data;',
'V_BATIDA VARCHAR2(10);-- := :p43_batida;',
'',
'v_latitude varchar2(40) := :p43_lat;--''-23.6741078'';',
'v_longitude varchar2(40) := :p43_lng; --''-46.7021295'';',
'',
'begin',
'',
'  begin',
'    prc_api_registro_data_hora(:p_empresa_user, :p_matricula_user, v_latitude, v_longitude, v_data, v_batida);',
'  end;',
'',
'if instr(1/2,'','') > 0 then',
'EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= ''''.,'''' '';',
'end if;',
'',
'BEGIN',
'PKG_IDIOMA.SETA_IDIOMA(''AMERICAN'');',
'END;  ',
'',
'  ',
'  begin',
'  -- if tipo_marcacao = 2 /*sequencial*/ then',
'   delete from pe_tratamento_batimentos t',
'    where t.cod_empresa = :p_empresa_user',
'      and t.matricula = :p_matricula_user',
'      and trunc(t.data_ponto) = v_data--trunc(sysdate)',
'      and t.posicao = 1',
'      and t.hora_batida is null',
'      and t.hora_batida_abono is null',
'      and t.origem = ''I''',
'      and not exists (select 1',
'                        from pe_tratamento_batimentos tx',
'                       where tx.cod_empresa = t.cod_empresa',
'                         and tx.matricula = t.matricula',
'                         and trunc(tx.data_ponto) = trunc(t.data_ponto)',
'                         and tx.posicao > 1);',
'   -- end if;          ',
'   exception',
'   when others then',
'   null;',
'   end;',
'   ',
'',
'Prc_Pe_Marca_Ponto',
'    (null,',
'      :P_EMPRESA_USER,',
'     :P_MATRICULA_USER,',
'     V_data,',
'     V_batida,',
'     :p43_posicao,',
'     ''S'',',
unistr('     2, --2(sequencial) --1(aproxima\00E7\00E3o), --p_tipo_marcacao in number,'),
'     v_latitude,',
'     v_longitude,',
'     v_flg,',
'     v_msg,',
'     ''N'',',
'     ''N'',',
unistr('     ''MARCA\00C7\00C3O ONLINE - PAINEL DO COLABORADOR'');'),
'     ',
':p43_flag := v_flg;',
'',
'--apex_application.g_print_success_message := ''<span style="color:white">Mensagem: ''|| v_msg ||''! </span>'';',
'',
':p43_mensagem := v_msg;',
'if v_flg = ''N'' then',
':p43_ok := ''N'';',
'else',
':p43_ok := ''S'';',
'end if;',
'',
'end;',
'',
'  '))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'MARCAR_PONTO'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>'&P43_MENSAGEM.'
);
