 p_id=>wwv_flow_api.id(220445169415952899052)
,p_plug_name=>unistr('Requisi\00E7\00E3o de Abono')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(209353570115087209769)
,p_plug_display_sequence=>40
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct',
'       R.COD_REQ     requisicao,',
'       R.dt_req data_abertura,',
'       R.cod_empresa||'' - ''||initcap(fnct_nome_empresa(R.cod_empresa)) Empresa, ',
'       r.matricula||'' - ''||initcap(fnct_nome_func(r.cod_empresa, r.matricula)) Matricula_Solicitada,',
'       R.cod_emp_req||'' - ''||Initcap(fnct_nome_empresa(R.cod_emp_req)) Empresa_Solicitante,',
'       R.mat_req||'' - ''||initcap(fnct_nome_func(R.cod_emp_req, R.cod_emp_req)) Solicitante,',
'       decode(cod_sit_req,1,''<span class="fa fa-play-circle colorNone" aria-hidden="true"></span> ''||''Aberta'',',
unistr('                            2,''<span aria-hidden="true" class="fa fa-check-circle colorSuccess"></span> ''||''Conclu\00EDda'','),
'                            3,''<span aria-hidden="true" class="fa fa-times-circle colorDanger"></span> ''||''Cancelada'',',
'                            4,''<span aria-hidden="true" class="fa fa-times-circle colorDanger"></span> ''||''Reprovada'',',
'                            5,''<span aria-hidden="true" class="fa fa-check-circle colorInfo"></span> ''||''Aprovada'',',
unistr('                            6,''<span aria-hidden="true" class="fa fa-pause-circle colorAlert"></span> ''||''Suspens\00E3o'') Situacao,'),
'       r.cod_empresa,',
'       r.cod_emp_req,',
'  --     AA.cod_emp_aprov,',
'       R.mat_req,',
'       r.matricula,',
'       r.data_ponto,',
'       to_char(r.hora_batida,''hh24:mi'') hora_original,',
'       to_char(r.hora_batida_abono,''hh24:mi'') hora_abono,',
'       r.posicao,',
'       i.filial||'' - ''||initcap(fnct_nome_filial(i.cod_empresa, i.filial)) Filial,',
'       i.cod_ccusto||'' - ''||initcap(fnct_nome_ccusto(i.cod_empresa, i.cod_ccusto)) centro_de_custo,',
'       i.unidade_adm||'' - ''||initcap(fnct_nome_unidade_adm(i.cod_empresa, null, i.unidade_adm)) unidade_adm,',
'       i.cod_atividade||'' - ''||initcap(fnct_nome_atividade(i.cod_atividade)) atividade,',
'       i.cargo||'' - ''||initcap(fnct_nome_cargo(i.cargo)) cargo,',
'       cod_justificativa||'' - ''||(select descricao ',
'                                          from pe_tipo_justificativa pet ',
'                                  where pet.cod_justificativa = r.cod_justificativa',
'                                     and pet.cod_empresa = r.cod_empresa) justificativa,',
'        case',
'            when cod_sit_req = 3 then',
'                :P_USUARIO',
'        else',
'            null',
'        end',
'        USUARIO_CANCELAMENTO,        ',
'        case',
'            when cod_sit_req = 3 then',
'                r.dt_atualizacao',
'        else',
'            null',
'        end        DATA_CANCELAMENTO                                     ',
'from --consulta_requisicoes c,',
'       PE_REQ_TRATAMENTO_BATIMENTOS r,',
'  --     APROVA_ABONO AA,',
'       informacoes_funcionais_cad i',
' where /*upper(c.tipo_req) = ''REQ_ABONO''',
'   and  AA.cod_empresa     = r.cod_empresa',
'   and */ :P137_PESQUISA = ''S''',
' --  and AA.COD_SOLICITACAO     = r.cod_req',
'   and r.cod_empresa = i.cod_empresa',
'   and r.matricula = i.matricula',
'   and (((R.cod_empresa = :P_EMPRESA_USER',
'   and           R.matricula = :P_MATRICULA_USER) or ',
'        /*(AA.cod_emp_aprov = :P_EMPRESA_USER',
'   and       AA.mat_aprov = :P_MATRICULA_USER) and */  :p_painel = ''PG'') or',
'        (:p_painel = ''PO''',
'         and ((R.cod_empresa, R.mat_req) in (select x.cod_empresa, x.matricula ',
'                                                                          from informacoes_funcionais_cad x ',
'                                                                          where x.cod_empresa = R.cod_empresa ',
'                                                                          and x.matricula = R.matricula ',
'                                                                     and F_Acesso_PG_Apex(x.cod_empresa, x.matricula, x.filial, x.cd_nivel, :p_usuario) = ''S'')',
'          /*or  (AA.COD_EMP_APROV = :P_EMPRESA_USER AND AA.MAT_APROV = :P_MATRICULA_USER)*/)',
'        ) or',
'        (i.cod_empresa = :P_EMPRESA_USER and i.matricula = :P_MATRICULA_USER and :p_painel = ''PC'') or',
'        (r.cod_empresa = :p137_emp and r.matricula = :p137_mat and :p137_mat is not null))',
'   and ((r.cod_sit_req = :p137_sit_req) or (:p137_sit_req is null))',
'   and (((trunc(sysdate) - trunc(r.dt_req)) <= :p137_periodo) or (:p137_periodo = 0))',
'   or (R.MATRICULA = :P_MATRICULA_USER AND :p_painel = ''PC'')',
