,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'select utiliza_secao ',
'  into :p137_utiliza_secao',
'  from parametros_recursos_humanos ',
' where ((instr('',''||:p137_empresa||'','','',''||cod_empresa||'','') > 0) or (:p137_empresa is null))',
'   and rownum = 1;',
' ',
'exception',
'when others then',
'null;',
'',
'end;'))
,p_attribute_02=>'P137_EMPRESA'
,p_attribute_03=>'P137_UTILIZA_SECAO'
,p_attribute_04=>'N'
