wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196794293660123222138)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'popula_colab'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select i.cod_empresa||'' - ''||initcap(fnct_nome_empresa(i.cod_empresa)) empresa,',
'       i.matricula||'' - ''||initcap(fnct_nome_func(i.cod_empresa, i.matricula)) matricula,',
'       i.situacao||'' - ''||initcap(fnct_nome_situacao(i.situacao))||'' - ''||i.dt_situacao situacao,',
'       i.dt_admissao',
'  from informacoes_funcionais i',
' where i.cod_empresa = :p137_emp',
'   and i.matricula = :p137_mat;',
'                   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
':p137_cod_empresa1 := v_c1.empresa;',
':p137_matricula := v_c1.matricula;',
':p137_situacao := v_c1.situacao;',
':p137_dt_admissao := v_c1.dt_admissao;',
'',
'IF :p137_pesquisa  IS NULL THEN',
'    :p137_pesquisa := ''N'';',
'END IF;',
'',
'',
'--:p137_OK := ''S'';',
'',
'exception',
'when others then',
':p137_cod_empresa := :p137_emp;',
':p137_matricula := :p137_mat;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
