,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'select utiliza_secao ',
'  into :p138_utiliza_secao',
'  from parametros_recursos_humanos ',
' where ((instr('',''||:p138_empresa||'','','',''||cod_empresa||'','') > 0) or (:p138_empresa is null))',
'   and rownum = 1;',
' ',
'exception',
'when others then',
'null;',
'',
'end;'))
,p_attribute_02=>'P138_EMPRESA'
,p_attribute_03=>'P138_UTILIZA_SECAO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
