,p_plug_display_sequence=>30
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'   ''apex-cal-green'' CLASS_CALENDR, ',
'   ''Matricula ''||r.matricula||''<br />''',
'   ||'' Nome ''||initcap(ip.nome)||''<br />''',
'   ||'' Inicio ''||r.inicio||''<br />''',
'   ||'' Fim ''||r.fim||''<br />''',
'   ||''Empresa ''||r.cod_empresa||''<br />'' texto,',
'   r.dt_atualizacao, r.inicio, r.fim, r.cod_req',
'FROM REQ_PE_ESCALAS_EXCECOES R, REQ_PE_ESCALAS_TRANSFER_HIST T, INF_PESSOAIS IP',
'where t.cod_req_origem = r.cod_req',
'and ip.matricula = r.matricula',
'and ip.cod_empresa = r.cod_empresa',
'and r.cod_sit_req = (select cod_sit_req from sit_req where desc_sit_req = ''TRANSFERIDA'')',
'order by r.cod_req desc'))
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_attribute_01=>'INICIO'
,p_attribute_02=>'FIM'
,p_attribute_03=>'TEXTO'
,p_attribute_09=>'list:navigation'
,p_attribute_13=>'N'
,p_attribute_14=>'CLASS_CALENDR'
,p_attribute_17=>'Y'
