,p_prompt=>'Gestor/Gestor SubCcusto'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CC.COD_EMP_GESTOR||''/''||CC.MATRICULA_GESTOR||'' - ''||IP.NOME||'' (Gestor Ccusto)'' D, REPLACE(TO_CHAR(CC.COD_EMP_GESTOR,''000'')||TO_CHAR(CC.MATRICULA_GESTOR,''000000''),'' '','''') C',
'FROM   CENTRO_DE_CUSTO CC',
'      ,INF_PESSOAIS_CAD IP',
'WHERE  IP.MATRICULA        = CC.MATRICULA_GESTOR',
'AND    IP.COD_EMPRESA      = CC.COD_EMPRESA',
'AND    CC.MATRICULA_GESTOR IS NOT NULL',
'AND    CC.COD              = NVL(:P177_COD_CCUSTO,CC.COD)',
'AND    CC.COD_EMPRESA      = :P177_COD_EMPRESA',
'UNION',
'SELECT SC.COD_EMP_SUBS||''/''||SC.MAT_SUBS||'' - ''||IP.NOME||'' (Gestor SubCcusto)'' D, REPLACE(TO_CHAR(SC.COD_EMP_SUBS,''000'')||TO_CHAR(SC.MAT_SUBS,''000000''),'' '','''') C',
'FROM   SUB_CCUSTO SC',
'      ,INF_PESSOAIS_CAD IP',
'WHERE  IP.MATRICULA   = SC.MAT_SUBS',
'AND    IP.COD_EMPRESA = SC.COD_EMP_SUBS',
'AND    SC.MAT_SUBS    IS NOT NULL',
'AND    SC.COD_CCUSTO  = NVL(:P177_COD_CCUSTO,SC.COD_CCUSTO)',
'AND    SC.COD_EMPRESA = :P177_COD_EMPRESA',
'ORDER BY 1'))
