,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select i.cod_empresa||'' - ''||initcap(fnct_nome_empresa(i.cod_empresa)) empresa,',
'       i.matricula||'' - ''||initcap(fnct_nome_func(i.cod_empresa, i.matricula)) matricula,',
'       i.situacao||'' - ''||initcap(fnct_nome_situacao(i.situacao))||'' - ''||i.dt_situacao situacao,',
'       i.dt_admissao',
'  from informacoes_funcionais i',
' where i.cod_empresa = :p177_emp',
'   and i.matricula = :p177_mat;',
'                   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'  if :p_Painel = ''PC'' then',
'    :p177_emp := :p_empresa_user;',
'    :p177_mat := :p_matricula_user;',
'  end if;',
'  ',
'  open c1;',
'  fetch c1 into v_c1;',
'  close c1;',
'',
'  if :p177_mat is not null then',
'',
'    :p177_cod_empresa1 := v_c1.empresa;',
'    :p177_matricula_desc := v_c1.matricula;',
'    :p177_situacao_desc := v_c1.situacao;',
'    :p177_dt_admissao := v_c1.dt_admissao;',
'',
'  end if;',
'',
'exception',
'when others then',
':p177_cod_empresa := :p177_emp;',
':p177_matricula := :p177_mat;',
'end;'))
