wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(229915404693942566077)
,p_plug_name=>unistr('Informa\00E7\00F5es')
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Form--stretchInputs:t-Form--labelsAbove'
,p_plug_template=>wwv_flow_api.id(209353570115087209769)
,p_plug_display_sequence=>30
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'x.cod_req cod_requisicao,',
'x.dt_req data_requisicao,',
'       decode(x.cod_sit_req,1,''<span class="fa fa-play-circle colorNone" aria-hidden="true"></span> ''||''Aberta'',',
unistr('                            2,''<span aria-hidden="true" class="fa fa-check-circle colorSuccess"></span> ''||''Conclu\00EDda'','),
'                            3,''<span aria-hidden="true" class="fa fa-times-circle colorDanger"></span> ''||''Cancelada'',',
'                            4,''<span aria-hidden="true" class="fa fa-times-circle colorDanger"></span> ''||''Reprovada'',',
'                            5,''<span aria-hidden="true" class="fa fa-check-circle colorInfo"></span> ''||''Aprovada'',',
unistr('                            6,''<span aria-hidden="true" class="fa fa-pause-circle colorAlert"></span> ''||''Suspens\00E3o'','),
'                            7,''<span aria-hidden="true" class="fa fa-refresh colorSuccess"></span> ''||''Disponibilizada'',',
'                            8,''<span aria-hidden="true" class="fa fa-exchange colorSuccess"></span> ''||''Transferida''',
'             ) Situacao_Requisicao,',
'x.dt_sit_req data_situacao_requisicao,',
'x.cod_emp_solicitante||'' - ''||initcap(fnct_nome_empresa(x.cod_emp_solicitante)) empresa_solicitante,',
'x.mat_solicitante||'' - ''||initcap(fnct_nome_func(x.cod_emp_solicitante, x.mat_solicitante)) Solicitante,',
'I.COD_EMPRESA||'' - ''||initcap(fnct_nome_empresa(I.cod_empresa)) Empresa,',
'I.FILIAL||'' - ''||initcap(fnct_nome_filial(I.cod_empresa, I.filial)) Filial,',
'I.COD_CCUSTO||'' - ''||initcap(fnct_nome_ccusto(I.cod_empresa, I.cod_ccusto)) CCusto,',
'c.cod_ccusto_cont||'' - ''||initcap(fnct_nome_ccusto_contab(I.cod_empresa,c.cod_ccusto_cont)) CCusto_Cont,',
'I.MATRICULA||'' - ''||initcap(fnct_nome_func(I.cod_empresa, I.matricula)) Colaborador,',
'I.situacao||'' - ''||initcap(fnct_nome_situacao(I.situacao)) Situacao,',
'case when x.cod_local_trab is null then',
'     I.COD_LOCALIZACAO||'' - ''||initcap(fnct_nome_local_trab(I.COD_LOCALIZACAO)) ',
'     when x.cod_local_trab is not null then',
'     x.cod_local_trab||'' - ''||initcap(fnct_nome_local_trab(x.cod_local_trab)) ',
'     end Local_Trab,',
'I.unidade_adm||'' - ''||initcap(u.descricao) Unidade_Adm,',
'c.cod_un_negocio||'' - ''||initcap(n.nome_un_negocio) Unidade_Negocio,',
'I.cod_atividade||'' - ''||initcap(a.descricao) Atividade,',
'I.COD_GRUPO_TRABALHO,',
'decode(I.COD_TIPO_MAO_OBRA,''D'',''Direta'',''I'',''Indireta'',I.cod_tipo_mao_obra) Mao_de_Obra,',
'x.cod_ESCALA||'' - ''||Initcap(E.DESCRICAO) Escala,',
'x.cod_jornada||'' - ''||initcap(r.nome_jornada) Jornada,',
'I.CARGO||'' - ''||initcap(fnct_nome_cargo(I.CARGO)) Cargo,',
'x.INICIO DT_INICIO_ESCALA,',
'x.FIM DT_FIM_ESCALA,',
unistr('DECODE(x.EXCECAO,''S'',''Sim'',''N'',''N\00E3o'') EXCECAO,'),
'upper(fnct_nome_sindicato(i.cod_empresa, i.num_sind_diss, ''S'')) sindicato,',
'I.COD_EMPRESA,',
'I.MATRICULA,',
'X.COD_JORNADA,',
'X.COD_ESCALA,',
'X.EXCECAO COD_EXCECAO,',
'(SELECT V.COD||'' - ''||V.NOME FROM VINCULO_EMPREG V WHERE V.COD = I.VINCULO) VINCULO,',
'X.USUARIO,',
'X.DT_ATUALIZACAO,',
'(SELECT C.COD_EMP_GESTOR||''/''||C.MATRICULA_GESTOR||'' - ''||IP.NOME FROM INF_PESSOAIS_CAD IP WHERE IP.MATRICULA = C.MATRICULA_GESTOR AND IP.COD_EMPRESA = C.COD_EMP_GESTOR) GESTOR,',
'(SELECT SC.COD_EMP_SUBS||''/''||SC.MAT_SUBS||'' - ''||IP.NOME FROM SUB_CCUSTO SC, INF_PESSOAIS_CAD IP WHERE IP.MATRICULA = SC.MAT_SUBS AND IP.COD_EMPRESA = SC.COD_EMP_SUBS',
' AND SC.COD_SUB_CCUSTO = I.COD_SUB_CCUSTO AND SC.COD_CCUSTO = I.COD_CCUSTO AND SC.COD_EMPRESA = I.COD_EMPRESA) GESTOR_SUBCCUSTO,',
'(SELECT C.COD_EMP_SUPLENTE||''/''||C.MATRICULA_SUPLENTE||'' - ''||IP.NOME FROM INF_PESSOAIS_CAD IP WHERE IP.MATRICULA = C.MATRICULA_SUPLENTE AND IP.COD_EMPRESA = C.COD_EMP_SUPLENTE) SUPLENTE,',
'-- r.tipo_jornada',
unistr('DECODE(R.TIPO_JORNADA,0,''0-Fixa'',1,''1-Flex\00EDvel'',2,''2-Vari\00E1vel Mensal'',3,''3-Vari\00E1vel Semanal'') TIPO_JORNADA,'),
unistr('DECODE(JORNADA_PLANTAO,''S'',''Sim'',''N'',''N\00E3o'',null) JORNADA_PLANTAO, DECODE(JOR_SOBREAVISO,''S'',''Sim'',''N'',''N\00E3o'',null) JOR_SOBREAVISO'),
' FROM informacoes_funcionais_cad I, ',
'      PE_ESCALAS E, ',
'      CENTRO_DE_CUSTO C, ',
'      UNIDADE_ADMINISTRATIVA U, ',
'      UNIDADE_DE_NEGOCIO N, ',
'      ATIVIDADE A, ',
'      req_pe_escalas_excecoes x, ',
'      pe_jornadas r ,',
'      reg_trabalho rt',
'WHERE I.cod_empresa = c.cod_empresa ',
' -- and i.matricula = 51',
' -- and i.cod_empresa = 700',
'  and I.cod_empresa = u.cod_empresa (+)',
'  and c.cod_empresa = n.cod_empresa (+)',
'  and I.cod_empresa = x.cod_empresa (+)',
'  and I.matricula = x.matricula (+)',
'  AND I.FILIAL = U.COD_FILIAL (+)',
'  and I.cod_ccusto = c.cod (+)',
'  and I.unidade_adm = u.cod_unidade_adm (+)',
'  and I.cod_atividade = a.cod (+)',
'  and c.cod_ccusto_cont = n.cod_ccusto_contab (+)',
'  ',
'  and x.cod_jornada = r.cod_jornada (+)',
'  and x.cod_escala = e.cod_escala(+)',
'  -- and I.situacao < ''90''',
'   and ((x.cod_sit_req = :p178_sit_req) or (:p178_sit_req is null))',
'   and (((trunc(sysdate) - trunc(x.dt_req)) <= :p178_periodo) or (:p178_periodo = 0))',
'  and ((:p178_TJ is not null and r.tipo_jornada = :p178_TJ) or :p178_TJ is null)',
'  and (:p178_cod_empresa IS NULL OR :p178_cod_empresa = I.cod_empresa)',
'  and (:p178_matricula     is null or I.MATRICULA in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_matricula, '','')) t))',
'  and (:p178_filial     is null or I.FILIAL in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_filial, '','')) t))',
'  and (:p178_cod_ccusto     is null or I.COD_CCUSTO in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_cod_ccusto, '','')) t))',
'  and (:p178_cod_ccusto_cont     is null or c.cod_ccusto_cont in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_cod_ccusto_cont, '','')) t))',
'  and (:p178_cod_localizacao     is null or I.COD_LOCALIZACAO in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_cod_localizacao, '','')) t))',
'  ',
'  and (:p178_unidade_adm     is null or I.unidade_adm in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_unidade_adm, '','')) t))',
'  and (:p178_un_negocio     is null or c.cod_un_negocio in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_un_negocio, '','')) t))',
'  and (:p178_atividade     is null or I.cod_atividade in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_atividade, '','')) t))',
'  and (:p178_cargo     is null or I.CARGO in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_cargo, '','')) t))',
'  and (:p178_jornada     is null or x.cod_jornada in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_jornada, '','')) t))',
'  and (:p178_escala     is null or x.cod_ESCALA in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p178_escala, '','')) t))',
'    and ((:p178_data_ini IS NULL) OR (( x.inicio between :p178_data_ini and :p178_data_fim ) or ( x.fim between :p178_data_ini and :p178_data_fim ) or (:p178_data_ini between x.inicio and x.fim) or (:p178_data_fim between x.inicio and x.fim)))',
'  --and ((:p178_data_ini between x.inicio and x.fim) or (:p178_data_fim between x.inicio and x.fim))',
'  and ((x.excecao = ''S'' and :p178_excecao = ''S'') or (x.excecao = ''N'' and :p178_excecao = ''N'') or (:p178_excecao = ''A''))',
'  AND f_acesso_pg_apex(i.cod_empresa, i.matricula, i.filial, i.cd_nivel, :p_usuario, :P_PAINEL, ''PONTO'') = ''S'' ',
unistr('  -- Novo processo de requisi\00E7\00E3o de escala - 09-01-2024 - Andr\00E9'),
'  and i.reg_trab =  rt.cod',
'    and rt.cod_empresa = i.cod_empresa',
unistr('  -- Novo processo de requisi\00E7\00E3o de escala - 09-01-2024 - Andr\00E9'),
'order by x.cod_req desc'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P178_COD_EMPRESA,P178_FILIAL,P178_COD_CCUSTO,P178_COD_CCUSTO_CONT,P178_COD_LOCAL,P178_UNIDADE_ADM,P178_UN_NEGOCIO,P178_ATIVIDADE,P178_CARGO,P178_MATRICULA,P178_JORNADA,P178_ESCALA,P178_DATA_INI,P178_DATA_FIM,P178_GT,P178_TJ'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
