,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT distinct I.MATRICULA||'' - ''||initcap(fnct_nome_func(i.cod_empresa, i.matricula)) as d, I.MATRICULA as r',
