'  AND I.MATRICULA = E.MATRICULA',
'  AND I.COD_EMPRESA = :P178_COD_EMPRESA',
'    and ((instr('':''||:p178_filial||'':'','':''||i.filial||'':'') > 0) or (:p178_filial is null))',
'    and ((instr('':''||:p178_cod_ccusto||'':'','':''||i.cod_ccusto||'':'') > 0)    or (:p178_cod_ccusto is null))',
'    and ((instr('':''||:p178_cod_ccusto_cont||'':'','':''||c.cod_ccusto_cont||'':'') > 0)    or (:p178_cod_ccusto_cont is null))',
'    and ((instr('':''||:p178_cod_localizacao||'':'','':''||I.cod_localizacao||'':'') > 0)    or (:p178_cod_localizacao is null))',
'    and ((instr('':''||:p178_unidade_adm||'':'','':''||I.unidade_adm||'':'') > 0)    or (:p178_unidade_adm is null))',
'    and ((instr('':''||:p178_un_negocio||'':'','':''||c.cod_un_negocio||'':'') > 0)    or (:p178_un_negocio is null))',
'    and ((instr('':''||:p178_atividade||'':'','':''||I.cod_atividade||'':'') > 0)    or (:p178_atividade is null))',
