wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(185912791480399019905)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'popula_colab'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select i.cod_empresa||'' - ''||initcap(fnct_nome_empresa(i.cod_empresa)) empresa,',
'       i.matricula||'' - ''||initcap(fnct_nome_func(i.cod_empresa, i.matricula)) matricula,',
'       i.situacao||'' - ''||initcap(fnct_nome_situacao(i.situacao))||'' - ''||i.dt_situacao situacao,',
'       i.dt_admissao',
'  from informacoes_funcionais i',
' where i.cod_empresa = :p178_emp',
'   and i.matricula = :p178_mat;',
'                   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'  if :p_Painel = ''PC'' then',
'    :p178_emp := :p_empresa_user;',
'    :p178_mat := :p_matricula_user;',
'  end if;',
'  ',
'  open c1;',
'  fetch c1 into v_c1;',
'  close c1;',
'',
'  if :p178_mat is not null then',
'',
'    :p178_cod_empresa1 := v_c1.empresa;',
'    :p178_matricula_desc := v_c1.matricula;',
'    :p178_situacao_desc := v_c1.situacao;',
'    :p178_dt_admissao := v_c1.dt_admissao;',
'',
'  end if;',
'',
'exception',
'when others then',
':p178_cod_empresa := :p178_emp;',
':p178_matricula := :p178_mat;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
