'  vMsg     VARCHAR2(2500) DEFAULT NULL;',
'BEGIN',
'  :P179_ERR_MSG := NULL;',
'  --',
'  PKG_PE_ABONO.prc_ValidaJornada(pEmpresa   => :P179_COD_EMPRESA',
'                                ,pmatricula => :P179_MATRICULA',
