||unistr(': ''||TRANSLATE(j.descricao,''\00C1\00C7\00C9\00CD\00D3\00DA\00C0\00C8\00CC\00D2\00D9\00C2\00CA\00CE\00D4\00DB\00C3\00D5\00CB\00DC\00E1\00E7\00E9\00ED\00F3\00FA\00E0\00E8\00EC\00F2\00F9\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00EB\00FC'',''ACEIOUAEIOUAEIOUAOEUaceiouaeiouaeiouaoeu'')'),
'            when comentarios is not null and t.cod_justificativa is not null then posicao||'' - ''||to_char(t.hora_batida,''hh24:mi'')||'' - ''||pkg_pe_abono.retorna_folga_feriado(t.cod_empresa, t.matricula, nvl(t.vira_dia,t.data_ponto))||'' - Comentario: '''
||unistr('||TRANSLATE(comentarios,''\00C1\00C7\00C9\00CD\00D3\00DA\00C0\00C8\00CC\00D2\00D9\00C2\00CA\00CE\00D4\00DB\00C3\00D5\00CB\00DC\00E1\00E7\00E9\00ED\00F3\00FA\00E0\00E8\00EC\00F2\00F9\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00EB\00FC'',''ACEIOUAEIOUAEIOUAOEUaceiouaeiouaeiouaoeu'')||'' Justificativa: ''||TRANSLATE(j.descricao,''\00C1\00C7\00C9\00CD\00D3\00DA\00C0\00C8\00CC\00D2\00D9\00C2\00CA\00CE\00D4\00DB\00C3\00D5\00CB\00DC\00E1\00E7\00E9\00ED\00F3\00FA\00E0\00E8\00EC\00F2\00F9\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00EB\00FC'',''ACEIOUAEIOUAEIOUAOEUaceiouaeiouaeiouaoeu'')'),
