'x.FIM DT_FIM_ESCALA,',
unistr('DECODE(x.EXCECAO,''S'',''Sim'',''N'',''N\00E3o'') EXCECAO,'),
'upper(fnct_nome_sindicato(i.cod_empresa, i.num_sind_diss, ''S'')) sindicato,',
'I.COD_EMPRESA,',
'I.MATRICULA,',
'X.COD_JORNADA,',
'X.COD_ESCALA,',
'X.EXCECAO COD_EXCECAO,',
'(SELECT V.COD||'' - ''||V.NOME FROM VINCULO_EMPREG V WHERE V.COD = I.VINCULO) VINCULO,',
'X.USUARIO,',
'X.DT_ATUALIZACAO,',
'(SELECT C.COD_EMP_GESTOR||''/''||C.MATRICULA_GESTOR||'' - ''||IP.NOME FROM INF_PESSOAIS_CAD IP WHERE IP.MATRICULA = C.MATRICULA_GESTOR AND IP.COD_EMPRESA = C.COD_EMP_GESTOR) GESTOR,',
'(SELECT SC.COD_EMP_SUBS||''/''||SC.MAT_SUBS||'' - ''||IP.NOME FROM SUB_CCUSTO SC, INF_PESSOAIS_CAD IP WHERE IP.MATRICULA = SC.MAT_SUBS AND IP.COD_EMPRESA = SC.COD_EMP_SUBS',
' AND SC.COD_SUB_CCUSTO = I.COD_SUB_CCUSTO AND SC.COD_CCUSTO = I.COD_CCUSTO AND SC.COD_EMPRESA = I.COD_EMPRESA) GESTOR_SUBCCUSTO,',
'(SELECT C.COD_EMP_SUPLENTE||''/''||C.MATRICULA_SUPLENTE||'' - ''||IP.NOME FROM INF_PESSOAIS_CAD IP WHERE IP.MATRICULA = C.MATRICULA_SUPLENTE AND IP.COD_EMPRESA = C.COD_EMP_SUPLENTE) SUPLENTE,',
'-- r.tipo_jornada',
unistr('DECODE(R.TIPO_JORNADA,0,''0-Fixa'',1,''1-Flex\00EDvel'',2,''2-Vari\00E1vel Mensal'',3,''3-Vari\00E1vel Semanal'') TIPO_JORNADA,'),
unistr('DECODE(JORNADA_PLANTAO,''S'',''Sim'',''N'',''N\00E3o'',null) JORNADA_PLANTAO, DECODE(JOR_SOBREAVISO,''S'',''Sim'',''N'',''N\00E3o'',null) JOR_SOBREAVISO'),
'    FROM REQ_PE_APURACAO_EXCECOES x,',
'        INFORMACOES_FUNCIONAIS I, ',
'        PE_REQ_APURACAO E,',
'        CENTRO_DE_CUSTO C, ',
'        UNIDADE_ADMINISTRATIVA U, ',
'        UNIDADE_DE_NEGOCIO N, ',
'        ATIVIDADE A, ',
'        PE_JORNADAS r ',
'    WHERE I.cod_empresa = c.cod_empresa ',
'    and I.cod_empresa = u.cod_empresa (+)',
'    and c.cod_empresa = n.cod_empresa (+)',
'    and I.cod_empresa = x.cod_empresa (+)',
'    and I.matricula = x.matricula (+)',
'    AND I.FILIAL = U.COD_FILIAL (+)',
'    and I.cod_ccusto = c.cod (+)',
'    and I.unidade_adm = u.cod_unidade_adm (+)',
'    and I.cod_atividade = a.cod (+)',
'    and c.cod_ccusto_cont = n.cod_ccusto_contab (+)',
'',
'    and x.cod_jornada = r.cod_jornada (+)',
'    --and x.cod_escala = e.cod_escala(+)',
'    and ((x.cod_sit_req = :p180_sit_req) or (:p180_sit_req is null))',
'    and (((trunc(sysdate) - trunc(x.dt_req)) <= :p180_periodo) or (:p180_periodo = 0))',
'    and ((:p180_TJ is not null and r.tipo_jornada = :p180_TJ) or :p180_TJ is null)',
'    and (:p180_cod_empresa IS NULL OR :p180_cod_empresa = I.cod_empresa)',
'    and (:p180_matricula     is null or I.MATRICULA in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_matricula, '','')) t))',
'    and (:p180_filial     is null or I.FILIAL in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_filial, '','')) t))',
'    and (:p180_cod_ccusto     is null or I.COD_CCUSTO in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_cod_ccusto, '','')) t))',
'    and (:p180_cod_ccusto_cont     is null or c.cod_ccusto_cont in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_cod_ccusto_cont, '','')) t))',
'    and (:p180_cod_localizacao     is null or I.COD_LOCALIZACAO in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_cod_localizacao, '','')) t))',
'',
'    and (:p180_unidade_adm     is null or I.unidade_adm in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_unidade_adm, '','')) t))',
'    and (:p180_un_negocio     is null or c.cod_un_negocio in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_un_negocio, '','')) t))',
'    and (:p180_atividade     is null or I.cod_atividade in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_atividade, '','')) t))',
'    and (:p180_cargo     is null or I.CARGO in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_cargo, '','')) t))',
'    and (:p180_jornada     is null or x.cod_jornada in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_jornada, '','')) t))',
'    and (:p180_escala     is null or x.cod_ESCALA in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p180_escala, '','')) t))',
'    and ((:p180_data_ini IS NULL) OR (( x.inicio between :p180_data_ini and :p180_data_fim ) or ( x.fim between :p180_data_ini and :p180_data_fim ) or (:p180_data_ini between x.inicio and x.fim) or (:p180_data_fim between x.inicio and x.fim)))',
'    and ((x.excecao = ''S'' and :p180_excecao = ''S'') or (x.excecao = ''N'' and :p180_excecao = ''N'') or (:p180_excecao = ''A''))',
'    AND f_acesso_pg_apex(i.cod_empresa, i.matricula, i.filial, i.cd_nivel, :p_usuario, :P_PAINEL, ''PONTO'') = ''S''        ',
'order by I.cod_empresa, I.matricula '))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P180_COD_EMPRESA,P180_FILIAL,P180_COD_CCUSTO,P180_COD_CCUSTO_CONT,P180_COD_LOCAL,P180_UNIDADE_ADM,P180_UN_NEGOCIO,P180_ATIVIDADE,P180_CARGO,P180_MATRICULA,P180_JORNADA,P180_ESCALA,P180_DATA_INI,P180_DATA_FIM,P180_GT,P180_TJ'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
