'    :p181_cod_sit_req := 1;',
'    :p181_dt_req := sysdate;',
'    :p181_dt_sit_req := sysdate;',
'    :p181_cod_emp_req := :P_EMPRESA_USER;',
'    :p181_mat_req := :P_MATRICULA_USER;',
