'SELECT -- r."ROWID",',
'       r.cod_empresa empresa,',
'       --(select cod||'' - ''||initcap(nome) from empresas_cad where cod = r.cod_empresa) nome_empresa,',
'	   fnct_nome_empresa(r.cod_empresa,''S'') nome_empresa,',
'       r.matricula, ',
'       /*(select matricula||'' - ''||initcap(fnct_nome_func(cod_empresa, matricula)) search_matricula',
'            from informacoes_funcionais_cad i',
'              where cod_empresa = r.cod_empresa',
'        and matricula = r.matricula) nome_colaborador, */',
'       fnct_nome_func(r.cod_empresa, r.matricula) nome_colaborador,',
'	   r.data, ',
'	   r.cod_evento, ',
'	   r.cod_evento||'' - ''||b.descricao descricao,',
unistr('	   decode(b.tipo,''C'',''Cr\00E9dito'',''D'',''D\00E9bito'') tipo,  '),
'	   r.qtd_horas,',
'	   Initcap(r.tipo_evento) tipo_evento,',
'	   decode(r.bh_apurado,''A'',''Aberto'',''F'',''Fechado'',''M'',''Manual'',r.bh_apurado) bh_apurado_desc,',
'       r.bh_apurado,',
'	   r.posicao,',
'       r.id_apuracao,',
'       r.cod_item',
'  FROM pe_resultado_apuracao r,',
'       pe_eventos_banco b,',
'       parametros_recursos_humanos h',
' WHERE r.cod_empresa = b.cod_empresa ',
'   AND r.cod_empresa = h.cod_empresa',
'   AND r.cod_evento = b.cod_evento_banco ',
'   AND r.tipo_evento = ''BANCO''',
'   AND r.cod_empresa = :P182_EMP',
'   AND r.matricula = :P182_MAT',
'   AND r.data = nvl( to_date(:P182_DATA, ''dd/mm/yyyy''), r.data)',
'   AND r.tipo_evento = nvl( :P182_TIPO_EVENTO, r.tipo_evento )',
'   AND r.cod_evento = nvl( :P182_COD_EVENTO, r.cod_evento)',
'   --and ((:p_painel = ''PO'') or (r.data between nvl(h.dt_ini_ponto_gestor,r.data) and nvl(h.dt_fim_ponto_gestor,r.data)))',
'  union',
'SELECT -- r."ROWID",',
'       r.cod_empresa, ',
'       (select cod||'' - ''||initcap(nome) from empresas_cad where cod = r.cod_empresa) nome_empresa,',
'	   r.matricula, ',
'       (select matricula||'' - ''||initcap(fnct_nome_func(cod_empresa, matricula)) matricula',
'            from informacoes_funcionais_cad i',
'              where cod_empresa = r.cod_empresa',
'        and matricula = r.matricula) nome_colaborador, ',
'	   r.data, ',
'	   r.cod_evento, ',
'	   r.cod_evento||'' - ''||p.descricao descricao,',
'	   CASE ',
unistr('      WHEN :p_base <> ''PREVCOM'' and p.folha = ''S''  AND p.cod_ocorr < 500 THEN ''Cr\00E9dito'' '),
unistr('			WHEN :p_base <> ''PREVCOM'' and p.folha = ''S''  AND p.cod_ocorr >= 500 THEN ''D\00E9bito'' '),
unistr('      WHEN :p_base = ''PREVCOM'' and p.folha = ''S''  AND p.cod_ocorr < 5000 THEN ''Cr\00E9dito'' '),
unistr('			WHEN :p_base = ''PREVCOM'' and p.folha = ''S''  AND p.cod_ocorr >= 5000 THEN ''D\00E9bito'' '),
'	   END tipo,  ',
'	   r.qtd_horas,',
'	   Initcap(r.tipo_evento) tipo_evento,',
'	   decode(r.bh_apurado,''A'',''Aberto'',''F'',''Fechado'',''M'',''Manual'',r.bh_apurado) bh_apurado_desc,',
'       r.bh_apurado,',
'	   r.posicao,',
'       r.id_apuracao,',
'       r.cod_item',
'  FROM pe_resultado_apuracao r,',
'	   pe_eventos_folha p,',
'       parametros_recursos_humanos h',
' WHERE r.cod_empresa = p.cod_empresa ',
'   AND r.cod_empresa = h.cod_empresa',
'   AND r.cod_evento = p.cod_evento_folha ',
'   AND r.tipo_evento = ''PONTO''',
