,p_button_redirect_url=>unistr('f?p=REQ_APROV_&P_BASE.:CONFIRMACAO:&SESSION.::&DEBUG.:RP,CONFIRMACAO:P1_COD_REQ,P1_STATUS,P1_TEXTO:&P183_COD_REQ.,R,Deseja Reprovar esta requisi\00E7\00E3o? Informe uma justificativa.')
,p_button_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno     varchar2(3);',
'v_msg_retorno     varchar2(4000);',
'v_aprova_apuracao varchar2(1);',
'',
'begin',
'',
'    if :P_PAINEL = ''PC'' then',
'        return false;',
'    end if;',
'',
'    PKG_REQ_APURACAO.Valida_Sequencia(nvl( :P183_EMP, :P183_COD_EMP_REQ), :P183_COD_REQ, :P_EMPRESA_USER, :P_MATRICULA_USER, v_flg_retorno, v_msg_retorno);',
'    if v_flg_retorno = ''N'' and trim(v_msg_retorno) is not null then',
'        begin',
'            select cd_aprova_apuracao',
'                into v_aprova_apuracao',
'                from perfil_aprova_requisicao',
'                where cod_empresa = :P_EMPRESA_USER',
'                and cd_perfil = :P_PERFIL;',
'        exception',
'            when others then',
'                v_aprova_apuracao := ''N'';',
'        end;',
'        if v_aprova_apuracao = ''S'' then',
'            return true;',
'        end if;',
'    ',
'        return false;',
'    else',
'        return true;',
'    end if;',
' ',
'end;'))
,p_button_condition_type=>'FUNCTION_BODY'
,p_icon_css_classes=>'fa-close'
);
