,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
unistr('select decode(tipo_rubrica, 1, ''Cr\00E9dito'', 2, ''D\00E9bito'', 3, ''Base'') tipo_Desc, to_char(cod_ocorr) tipo, FOLHA folha'),
'  from pe_eventos_folha f, ocorr_pagto op',
' where ',
'  op.cod_empresa = f.cod_empresa ',
' and op.cod = f.cod_ocorr',
'    and f.cod_empresa = :p183_emp',
'   and f.cod_evento_folha = :P183_COD_EVENTO_NOVO --p214_cod_evento_novo',
'   and :p183_tipo_evento_novo = ''PONTO''',
'union ',
unistr('select decode(b.tipo,''C'',''Cr\00E9dito'',''D'',''D\00E9bito'') tipo_Desc, b.tipo tipo, ''S'' Folha'),
'  from pe_eventos_banco b',
' where b.cod_empresa = :p183_emp',
'   and b.cod_evento_banco = :P183_COD_EVENTO_NOVO --p214_cod_evento_novo',
'   and :p183_tipo_evento_novo = ''BANCO'';',
'   ',
'v_c1 c1%rowtype;',
'',
'begin',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'    :p183_tipo_novo := '''';',
'	:p183_tipo_disp_novo := '''';',
'    :p183_tipo_disp_novo := v_c1.tipo_desc;',
'    if v_c1.tipo is not null then',
'        :p183_tipo_novo := v_c1.tipo;',
'        if v_c1.folha = ''S'' then',
'        :p183_tipo_disp_novo := v_c1.tipo_desc;',
'        end if;',
'    end if;',
'',
'exception',
'    when others then',
'        :p183_tipo_disp_novo := ''Erro'';',
'end;',
''))
,p_attribute_02=>'P183_COD_EVENTO_NOVO'
,p_attribute_03=>'P183_TIPO_NOVO,P183_TIPO_DISP_NOVO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
