,p_event_id=>wwv_flow_api.id(150135973993148967293)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select  min(C.ROWID) ROWID_REMAN,',
'            FUNC_DEC_TO_HORA(nvl(sum(FUNC_HORA_TO_DEC(C.QTD_HORAS)),''00:00''))',
'    into	:P183_ROWID_REMAN,',
'            :P183_SALDO_REMAN',
'    from    PE_FUNC_PARAMETROS_BH A,',
'            PE_PARAMETROS_BH B,',
'            PE_RESULTADO_APURACAO C,',
'            PE_EVENTOS_BANCO D',
'    where   A.COD_EMPRESA = :P183_EMP',
'    and     A.MATRICULA = :P183_MAT',
'    and     C.TIPO_EVENTO = ''BANCO''',
'    and     C.BH_APURADO = ''A''',
'    and     D.TIPO != :P183_TIPO_NOVO',
'    and     C.DATA < B.DT_INI_BH',
'    and     A.COD_EMPRESA = B.COD_EMPRESA',
'    and     A.COD_PARAM_BH = B.COD_PARAM_BH',
'    and     A.COD_EMPRESA = C.COD_EMPRESA',
'    and     A.MATRICULA = C.MATRICULA',
'    and     C.COD_EMPRESA = D.COD_EMPRESA',
'    and     C.COD_EVENTO = D.COD_EVENTO_BANCO;',
'    ',
'    ',
'    ',
'exception',
'    when others then',
'        :P183_SALDO_REMAN := ''00:00'';',
'end;'))
,p_attribute_02=>'P183_EMP,P183_MAT,P183_TIPO_NOVO'
,p_attribute_03=>'P183_SALDO_REMAN,P183_ROWID_REMAN'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
