,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_total_requisicoes NUMBER := 0;',
'    l_total_horas       NUMBER := 0;',
'    l_erro    varchar2(4000);',
'begin',
'    if :P183_COD_REQ is null then',
'        begin',
'            select nvl(sum(substr(trim(QTD_HORAS), 1, 2)+round((substr(trim(QTD_HORAS), 4, 2)/100),2)), 0)',
'                into l_total_requisicoes',
'            from pe_req_apuracao',
'                where cod_emp_req = :P183_EMP',
'                and matricula = :P183_MAT ',
'                and cod_evento_atual = :P183_COD_EVENTO',
'                and cod_item = :P183_COD_ITEM',
'                and data_ponto = to_date(:P183_DATA_PONTO, ''dd/mm/yyyy'')',
'                and COD_SIT_REQ not in (3, 4);',
'        exception ',
'            when others then',
'                l_total_requisicoes := 0;',
'        end;',
'        --',
'        begin',
'            /*select nvl(sum((substr(trim(qtd_horas), 1,2) + (substr(trim(qtd_horas), 4,2)/100))), 0)',
'            into l_total_horas',
'             from pe_resultado_apuracao',
'            where cod_empresa = :P183_EMP',
'            and matricula = :P183_MAT',
'            and data = to_date(:P183_DATA, ''dd/mm/yyyy'')',
'            and cod_item = :P183_COD_ITEM',
'            and cod_evento = :P183_COD_EVENTO;*/',
'            ',
'            select nvl(sum((substr(trim(qtd_horas_ant), 1,2) + (substr(trim(qtd_horas_ant), 4,2)/100))), 0)',
'            into l_total_horas',
'             from PE_HIST_RESUL_APURACAO',
'            where cod_empresa = :P183_EMP',
'            and matricula = :P183_MAT',
'            and data = to_date(:P183_DATA, ''dd/mm/yyyy'')',
'            --and cod_item = :P183_COD_ITEM',
'            and cod_evento_ant = :P183_COD_EVENTO;',
'                        ',
'            ',
'            ',
'        exception ',
'            when others then',
'                l_total_horas := 0;',
'        end;',
'        --  ',
'        if to_number(l_total_horas) >= to_number(l_total_requisicoes) then',
'             :P183_TOTAL_HORAS_REQUISICOES := null;',
'        else',
'            :P183_TOTAL_HORAS_REQUISICOES := l_total_requisicoes;        ',
'        end if;    ',
'    end if;',
'exception',
'    when others then',
'        l_erro := SQLERRM;',
'        :P183_TOTAL_HORAS_REQUISICOES := null;',
'end;'))
,p_attribute_02=>'P183_EMP,P183_MAT,P183_COD_EVENTO,P183_DATA_PONTO'
,p_attribute_03=>'P183_TOTAL_HORAS_REQUISICOES'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
