,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'    CURSOR creq IS ',
'        SELECT COUNT(*)  as contador',
'            FROM  PE_REQ_TRATAMENTO_BATIMENTOS',
'        WHERE COD_EMPRESA = :P183_EMP',
'        AND MATRICULA = :P183_MAT',
'        AND DATA_PONTO = TO_DATE(:P183_DATA, ''DD/MM/YYYY'')',
'        AND COD_SIT_REQ not in ( 2, 3, 4 );',
'    r_req creq%ROWTYPE;        ',
'',
'begin',
'    :P183_CHECAR_APURACAO := NULL;    ',
'    OPEN creq;',
'    FETCH creq INTO r_req;',
'    CLOSE creq;',
'',
'    IF r_req.contador > 0 OR r_req.contador IS NULL THEN',
'        :P183_CHECAR_APURACAO := r_req.contador;',
'    ELSE',
'        :P183_CHECAR_APURACAO := NULL;    ',
'    END IF;',
'exception',
'    when others then',
'        :P183_CHECAR_APURACAO := NULL;',
'end;'))
,p_attribute_02=>'P183_EMP,P183_MAT,P183_DATA_PONTO'
,p_attribute_03=>'P183_CHECAR_APURACAO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
