'cursor c1 is',
'select cod_req, mat_req',
'  from pe_req_apuracao',
' where cod_req = :P183_COD_REQ;',
' ',
'v_c1 c1%rowtype;',
'',
'begin',
'    begin',
'         -- Passa a considerar o parametro de operador cancela a requisicao - ANDRE - 13-10-2023',
'        select operador_cancela_requisicoes',
'            into v_cancela',
'            from parametros_recursos_humanos',
'            where cod_empresa = :P183_EMP;',
'    exception',
'        when others then',
'            v_cancela := ''N'';',
'    end;',
'    --',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'    if v_c1.mat_req != :P_MATRICULA_USER then',
'        if :P183_COD_SIT_REQ = 3 then',
'            if v_cancela = ''N'' then',
unistr('                :P183_MUDA_COD_SIT_REQ := ''Somente o usu\00E1rio solocitante pode cancelar a requisi\00E7\00E3o'';'),
