'    if (e) {',
'        $x(''P183_FLAG'').value = ''S'';',
'        $x(''P183_MENSAGEM'').value = '''';',
'        $x(''P183_OK'').value = ''S'';',
'',
'    } else {',
'        $x(''P183_OK'').value = ''N'';',
'',
'    }',
'});',
'} else {',
'',
'    if ($x(''P183_MENSAGEM'').value.length  > 0 ) {',
'        ',
'        if ($x(''P183_FLAG'').value == "N") {',
'            $x(''P183_OK'').value = ''N'';',
'',
'        } else {',
'            if ($x(''P183_ITEM_VALIDACAO'').value.length == 0){',
'            $x(''P183_OK'').value = ''S'';',
'            }',
'        }',
'            ',
'        alertify.alert($v(''P183_MENSAGEM''));',
'        ',
'        ',
'    }else{',
'            if ($x(''P183_ITEM_VALIDACAO'').value.length == 0){',
'            $x(''P183_OK'').value = ''S'';',
'            }',
'    }',
'    ',
'    if ($x(''P183_ITEM_VALIDACAO'').value == ''P183_CREATE''){',
'            $x(''P183_OK'').value = ''S'';',
'        $x(''P183_ITEM_VALIDACAO'').value = '''';',
'    }',
'',
'}'))
);
