,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'    v_seq number;',
'    cursor c1 is',
'    select filial',
'      from informacoes_funcionais_cad',
'     where cod_empresa = :P_EMPRESA_USER',
'       and matricula = :P_MATRICULA_USER;',
'',
'    v_c1 c1%rowtype;   ',
'',
'    v_data date := :P183_DATA;',
'',
'begin',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'',
'    begin',
'        SELECT seq_requisicao.NEXTVAL',
'        INTO v_seq ',
'        FROM DUAL;',
'    end;',
'    :p183_cod_req := v_seq;',
'    :p183_cod_sit_req := 1;',
'    :p183_dt_req := sysdate;',
'    :p183_dt_sit_req := sysdate;',
'    :p183_cod_emp_req := :P_EMPRESA_USER;',
'    :p183_mat_req := :P_MATRICULA_USER;',
'    :p183_fil_req := v_c1.filial;',
'    :p183_usuario := :p_usuario;',
'end;'))
,p_attribute_02=>'P_EMPRESA_USER,P_MATRICULA_USER,P183_DATA'
,p_attribute_03=>'P183_COD_REQ,P183_COD_SIT_REQ,P183_DT_REQ,P183_DT_SIT_REQ,P183_COD_EMP_REQ,P183_MAT_REQ,P183_FIL_REQ,P183_USUARIO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
