wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(150136004357861967300)
,p_event_id=>wwv_flow_api.id(150136002787369967299)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_conta number := 0;',
'    v_erro  varchar2(4000);',
'    ',
'    cursor c_info_fun is',
'    select filial, cod_ccusto, cod_localizacao ',
'      from      informacoes_funcionais',
'           where cod_empresa = :P183_EMP',
'           and matricula = :P183_MAT;',
'       ',
'    r_c_info_fun c_info_fun%rowtype;',
'begin',
'',
'    update pe_req_apuracao',
'        set cod_sit_req = (select cod_sit_req',
'                                 from sit_req',
'                                where desc_sit_req = ''CANCELADA'')',
'        , dt_sit_req = SYSDATE',
'    where cod_req = :P183_COD_REQ;',
'    --',
'    v_conta := SQL%ROWCOUNT;',
'    if v_conta != 0 then',
'        --',
'        begin',
'                delete  from PE_HIST_RESUL_APURACAO',
'                where cod_empresa = :P183_EMP',
'                and matricula = :P183_MAT',
'                and data = :P183_DATA_PONTO',
'                and cod_evento_ant = :P183_COD_EVENTO',
'                and qtd_horas_ant = :P183_QTD_HORAS',
'                and id_apuracao = :P183_ID_APURACAO;',
'        exception ',
'            when others then',
'                v_erro := SQLERRM;',
'        end; ',
'        ',
'        v_conta := SQL%ROWCOUNT;',
'        ',
'        open  c_info_fun;',
'        fetch c_info_fun into r_c_info_fun;',
'        close c_info_fun;',
'        --CHAMADA DA APURACAO',
'        PKG_APURACAO_PONTO.APURA(p_empresa         => :P183_EMP,',
'                                  p_filial_ini     => r_c_info_fun.filial,',
'                                  p_filial_fin     => r_c_info_fun.filial,',
'                                  p_ccusto_ini     => r_c_info_fun.cod_ccusto,',
'                                  p_ccusto_fin     => r_c_info_fun.cod_ccusto,',
'                                  p_local_ini      => r_c_info_fun.cod_localizacao,',
'                                  p_local_fin      => r_c_info_fun.cod_localizacao,',
'                                  p_grupo_ini      => null,',
'                                  p_grupo_fin      => null,',
'                                  p_matricula_ini  => :P183_MAT,',
'                                  p_matricula_fin  => :P183_MAT,',
'                                  p_data_ini       => :P183_DATA_PONTO,',
'                                  p_data_fin       => :P183_DATA_PONTO,',
'                                  p_id_apuracao    => :P183_ID_APURACAO,',
'                                  p_erro           => v_erro,',
'                                  P_USUARIO        => :P_USUARIO,',
'                                  P_DT_ATUALIZACAO => SYSDATE,',
'                                  p_manter_hist    => ''N'');',
'',
'        if v_erro is null then',
'        --',
'            :P183_OK       := ''S'';',
'            :P183_FLAG     := ''S'';',
unistr('            :P183_MENSAGEM := ''Cancelamento da Requisi\00E7\00E3o ''||:P183_COD_REQ||'' executado com sucesso.'';'),
'        else',
'            :P183_OK       := ''N'';',
'            :P183_FLAG     := ''N'';',
'            :P183_MENSAGEM := ''Erro ao cancelar.''||SQLERRM;        ',
'        ',
'        end if;',
'    end if;',
'end;',
''))
,p_attribute_02=>'P183_COD_REQ,P183_EMP,P183_MAT,P183_DATA_PONTO,P183_COD_EVENTO,P183_QTD_HORAS,P183_ID_APURACAO'
,p_attribute_03=>'P183_MENSAGEM,P183_FLAG,P183_OK'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
