wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(150136006592503967300)
,p_event_id=>wwv_flow_api.id(150136006128735967300)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_horas_req number;',
'    v_horas_info varchar2(50);',
'begin',
'',
'    begin',
'        select sum((substr(qtd_horas, 1, instr(qtd_horas, '':'')-1) + (substr(qtd_horas, instr(qtd_horas, '':'')+1)/60)))',
'        into v_horas_req',
'           from pe_req_apuracao ',
'           where cod_empresa = :P183_EMP',
'           and matricula = :P183_MAT ',
'           and data_ponto = :P183_DATA_PONTO',
'        and cod_sit_req not in (2,3,4)',
'        and :P_PAINEL = ''PC'';',
'    exception',
'        when others then',
'            v_horas_req :=NULL;',
'    end;',
'    ',
'    v_horas_info := substr(:P183_QTD_HORAS, 1, instr(:P183_QTD_HORAS, '':'')-1) + (substr(:P183_QTD_HORAS, instr(:P183_QTD_HORAS, '':'')+1)/60)*60;',
'    if v_horas_req is null then',
'        :P183_HORAS_REQ_NAPROV := null; ',
'    elsif v_horas_info is null then',
'        :P183_HORAS_REQ_NAPROV := null; ',
'    elsif v_horas_req is not null then',
'        if v_horas_req >= v_horas_info then',
'            :P183_HORAS_REQ_NAPROV := 1;',
'        end if;    ',
'    end if;',
'end; '))
,p_attribute_02=>'P183_EMP,P183_MAT,P183_DATA_PONTO,P183_COD_EVENTO'
,p_attribute_03=>'P183_HORAS_REQ_NAPROV'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
