wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(87758689359458658060)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Cria Requisi\00E7\00F5es - Passo 0')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' ',
'BEGIN',
'DELETE FROM TESTEX WHERE  texto like ''ANDRE%'';',
'    FOR r IN 1..APEX_APPLICATION.G_F01.COUNT ',
'    loop',
'    insert into testex values (-1, ''ANDRE- ID = ''||APEX_APPLICATION.G_F01(r) );',
'        IF APEX_APPLICATION.G_F01(r) IS NOT NULL THEN ',
'            UPDATE PE_RESULTADO_APURACAO_TEMP_REQ ',
'            SET CRIAR_REQUISICAO = ''S''',
'            WHERE ROWID = APEX_APPLICATION.G_F01(r) ;',
'        END IF;',
'    END LOOP;',
'',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(148950932152831198814)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Cria Requisi\00E7\00F5es - Passo 1')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'    v_seq number;',
'    cursor c1 is',
'    select filial',
'      from informacoes_funcionais_cad',
'     where cod_empresa = :P_EMPRESA_USER',
'       and matricula = :P_MATRICULA_USER;',
'',
'    v_c1 c1%rowtype;   ',
'',
'    --v_data date := :P183_DATA;',
'',
'begin',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'/*',
'    begin',
'        SELECT seq_requisicao.NEXTVAL',
'        INTO v_seq ',
'        FROM DUAL;',
'    end;',
'    :p183_cod_req := v_seq;',
'    */',
'    :p183_cod_sit_req := 1;',
'    :p183_dt_req := sysdate;',
'    :p183_dt_sit_req := sysdate;',
'    :p183_cod_emp_req := :P_EMPRESA_USER;',
'    :p183_mat_req := :P_MATRICULA_USER;',
'    :p183_fil_req := v_c1.filial;',
'    :p183_usuario := :p_usuario;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(148950928856213198781)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Cria Requisi\00E7\00F5es - Passo 2')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_use_matricula     PE_REQ_APURACAO.MATRICULA%TYPE;',
'    l_cod_sit_req       PE_REQ_APURACAO.cod_sit_req%type;',
'    l_ok                VARCHAR2(10); ',
'    l_apurado           VARCHAR2(20);',
'    l_tipo              VARCHAR2(20);',
'    l_tipo_novo         VARCHAR2(20);         ',
'    l_mensagem          VARCHAR2(4000);',
'    ',
'    l_seq                number;',
'    v_informado          number; ',
'    v_registrado         number;',
'    v_calculado          number;  ',
'            ',
'begin',
'    FOR r IN (SELECT * FROM PE_RESULTADO_APURACAO_TEMP_REQ',
'                WHERE SEQ_ID = :P183_SEQ',
'             and  CRIAR_REQUISICAO = ''S'')',
'    loop',
'        if :P183_NOVA_REQUISICAO is null then',
'            l_use_matricula := :P183_MAT;',
'        else',
'            l_use_matricula := :P183_USUARIO;    ',
'        end if;',
unistr('        --Considerar que uma nova requisi\00E7\00E3o \00E9 um evento Manual.'),
'        --select decode( :P183_BH_APURADO , ''Aberto'', ''A'', ''Fechado'', ''F'', ''Manual'', ''M'', ''A'') ',
'        l_apurado := ''M'';',
'',
unistr('        select decode(:P183_TIPO, ''Cr\00E9dito'', ''C'', ''D\00E9bito'', ''D'')'),
'            into l_tipo',
'        from dual;',
'        --',
unistr('        select decode(:P183_TIPO_DISP_NOVO, ''Cr\00E9dito'', ''C'', ''D\00E9bito'', ''D'')'),
'            into l_tipo_novo',
'        from dual;',
'        --    ',
'        begin',
'            SELECT seq_requisicao.NEXTVAL',
'            INTO l_seq ',
'            FROM DUAL;',
'        end;',
'        :p183_cod_req := l_seq;',
'',
'        v_informado  := substr(r.qtd_horas, 1, instr(r.qtd_horas, '':'') -1) + (substr(r.qtd_horas, instr(r.qtd_horas, '':'') +1) / 60);',
'        v_registrado := substr(r.qtd_horas_original, 1, instr(r.qtd_horas_original, '':'') -1) + (substr(r.qtd_horas_original, instr(r.qtd_horas_original, '':'') +1) / 60);',
'        v_calculado  := to_number(v_registrado) - to_number(v_informado);',
'',
'insert into testex values (-31, ''ANDRE - v_calculado = ''||v_calculado);',
'insert into testex values (-32, ''ANDRE - r.qtd_horas = ''||r.qtd_horas );',
'insert into testex values (-33, ''ANDRE - r.qtd_horas_original = ''||r.qtd_horas_original);',
'',
'        PKG_REQ_APURACAO.insere_requisicao( p_cod_req             => :P183_COD_REQ   ',
'                                            , p_dt_req            => trunc(sysdate)            ',
'                                            , p_cod_sit_req       => 1           ',
'                                            , p_dt_sit_req        => trunc(sysdate)          ',
'                                            , p_cod_emp_req       => :p183_cod_emp_req             ',
'                                            , p_fil_req           => :p183_fil_req            ',
'                                            , p_mat_req           => :p183_mat_req              ',
'                                            , p_cod_empresa       => :P183_EMP              ',
'                                            , p_matricula         => l_use_matricula --:p183_matricula            ',
'                                            , p_data_ponto        => r.data          ',
'                                            , p_num_horas         =>  r.qtd_horas          ',
'                                            , p_comentarios       => null             ',
'                                            , p_usuario           => :p183_usuario              ',
'                                            , p_dt_atualizacao    => trunc(sysdate)             ',
'                                            , p_tipo_evento       => :P183_TIPO_EVENTO_NOVO              ',
'                                            , p_cod_evento        => :P183_COD_EVENTO_NOVO  ',
'                                            , p_cod_evento_atual  => :P183_COD_EVENTO',
'                                            , p_tipo              => l_tipo_novo --:P183_TIPO_DISP_NOVO --:P183_TIPO_NOVO ',
'                                            , p_cod_item          => r.cod_item',
'                                            , p_id_apuracao       => r.id_apuracao',
'                                            , p_tipo_evento_atual => :P183_TIPO_EVENTO',
'                                            , p_qtd_horas_atual   => r.qtd_horas_original',
'                                            , p_apuracao_atual    => l_apurado ',
'                                            , p_tipo_atual        => l_tipo',
'                                            , p_justificativa     => :P183_COD_JUSTIFICATIVA',
'                                            , p_ccusto_contabil   => :P183_COD_CCUSTO_CONTABIL   ',
'                                            , p_origem            => 1',
'                                            , p_mensagem          => l_mensagem',
'                                            );',
'                                            ',
'        if l_mensagem is not null then                                     ',
'            :p183_msg_close := l_mensagem;',
'        else',
'            begin',
'                PKG_REQ_APURACAO.Post_Insert( pcod_empresa      => :P183_EMP',
'                                            , psolicitacao      => :P183_COD_REQ   ',
'                                            , pflg_retorno      => l_ok       ',
'                                            , pmsg_retorno      => l_mensagem);',
'                if l_mensagem is not null then                                     ',
'                    :p183_msg_close := l_mensagem;',
'                end if;',
'            end;',
'',
'        end if; ',
'    end loop;',
unistr('     apex_application.g_print_success_message := ''Requisi\00E7\00F5es criadas com sucesso.'';'),
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
/
begin
