wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(150135958269189967289)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Novo Salvar - Passo 1'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'cursor c_req is',
'select cod_sit_req',
'  from PE_REQ_APURACAO',
' where cod_req = :P183_COD_REQ;',
'',
'v_req c_req%rowtype;',
'',
'begin',
'    PKG_REQ_APURACAO.Valida_Sit_Req(:P183_EMP, :P183_COD_REQ, :P183_MAT, :P183_COD_SIT_REQ, :p_usuario, v_flg_retorno, v_msg_retorno, :p_painel);',
'',
' if v_flg_retorno <> ''N'' and trim(v_msg_retorno) is null or (:P183_COD_SIT_REQ = 3) then',
'    update PE_REQ_APURACAO',
'       set cod_sit_req = :P183_COD_SIT_REQ,',
'           dt_sit_req = sysdate,',
'           usuario = :p_usuario,',
'           dt_atualizacao = sysdate',
'     where cod_req = :P183_COD_REQ;',
'     ',
' end if;',
' if :P183_COD_SIT_REQ != 3 then',
'',
'    PKG_REQ_APURACAO.Post_Update(:P183_EMP,',
'                                    :P183_COD_REQ,',
'                                    V_flg_retorno,',
'                                    V_msg_retorno);',
'',
' end if;',
' if v_msg_retorno is not null then',
'    :p183_ok       := ''N'';',
'    :p183_FLAG     := v_flg_retorno;',
'    :p183_mensagem := v_msg_retorno;',
' else',
'    :p183_flag     := null;',
'    :p183_mensagem := null;',
'    :p183_ok       := ''S'';',
' end if;',
' ',
'end;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(150135919684757967275)
,p_process_when_type=>'NEVER'
);
