wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(150135959854875967289)
,p_process_sequence=>100
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Pre Insert'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'/*',
'cursor c1 is',
'select nvl(max(cod_req),1) seq',
'  from pe_req_tratamento_batimentos;',
'',
'v_c1 c1%rowtype;',
'*/',
'v_seq number;',
'cursor c1 is',
'select filial',
'  from informacoes_funcionais_cad',
' where cod_empresa = :P_EMPRESA_USER',
'   and matricula = :P_MATRICULA_USER;',
'   ',
'v_c1 c1%rowtype;   ',
'',
'v_data date := :p183_data;',
'',
'begin',
'    ',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'',
'    begin',
'        SELECT seq_requisicao.NEXTVAL',
'        INTO v_seq ',
'        FROM DUAL;',
'    end;',
'        :p183_cod_req := v_seq;',
'',
'    :p183_cod_sit_req := 1;',
'    :p183_dt_req := sysdate;',
'    :p183_dt_sit_req := sysdate;',
'    :p183_cod_emp_req := :P_EMPRESA_USER;',
'    :p183_mat_req := :P_MATRICULA_USER;',
'    :p183_fil_req := v_c1.filial;',
'    :p183_usuario := :p_usuario;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(150135960229891967289)
,p_process_sequence=>110
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Requisition'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_mensagem          VARCHAR2(4000);',
'    l_use_matricula     PE_REQ_APURACAO.MATRICULA%TYPE;',
'    l_apurado           VARCHAR2(20);',
'    l_tipo              VARCHAR2(20);',
'begin',
'    if :P183_NOVA_REQUISICAO is null then',
'        l_use_matricula := :P183_MAT;',
'    else',
'        l_use_matricula := :P183_USUARIO;    ',
'    end if;',
'    --',
'    select decode( :P183_BH_APURADO , ''Aberto'', ''A'', ''Fechado'', ''F'', ''Manual'', ''M'', ''A'') ',
'        into l_apurado',
'    from dual;',
'    --',
unistr('    select decode(:P183_TIPO, ''Cr\00E9dito'', ''C'', ''D\00E9bito'', ''D'')'),
'        into l_tipo',
'    from dual;',
'    --',
'    PKG_REQ_APURACAO.insere_requisicao( p_cod_req             => :P183_COD_REQ   ',
'                                        , p_dt_req            => trunc(sysdate)            ',
'                                        , p_cod_sit_req       => 1           ',
'                                        , p_dt_sit_req        => trunc(sysdate)          ',
'                                        , p_cod_emp_req       => :p183_cod_emp_req             ',
'                                        , p_fil_req           => :p183_fil_req            ',
'                                        , p_mat_req           => :p183_mat_req              ',
'                                        , p_cod_empresa       => :P183_EMP              ',
'                                        , p_matricula         => l_use_matricula --:p183_matricula            ',
'                                        , p_data_ponto        => :p183_data_ponto          ',
'                                        , p_num_horas         => :p183_qtd_horas_novo              ',
'                                        , p_comentarios       => null             ',
'                                        , p_usuario           => :p183_usuario              ',
'                                        , p_dt_atualizacao    => trunc(sysdate)             ',
'                                        , p_tipo_evento       => :P183_TIPO_EVENTO_NOVO              ',
'                                        , p_cod_evento        => :P183_COD_EVENTO_NOVO  ',
'                                        , p_cod_evento_atual  => :P183_COD_EVENTO',
'                                        , p_tipo              => :P183_TIPO_NOVO ',
'                                        , p_cod_item          => :p183_cod_item',
'                                        , p_id_apuracao       => :p183_id_apuracao',
'                                        , p_tipo_evento_atual => :P183_TIPO_EVENTO',
'                                        , p_qtd_horas_atual   => :P183_QTD_HORAS',
'                                        , p_apuracao_atual    => l_apurado ',
'                                        , p_tipo_atual        => l_tipo',
'                                        , p_mensagem          => l_mensagem',
'                                        );',
'    COMMIT;',
'    if l_mensagem is not null then                                     ',
'        :p183_msg_close := l_mensagem;',
'    end if;',
'end;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
);
