wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(150135962593639967290)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('recupera_evento_requisi\00E7\00E3o')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'l_erro VARCHAR2(4000);',
'l_step number := 0;',
'l_pos  number := 0;',
'--',
'l_cod_item     PE_REQ_APURACAO.cod_item%type;',
'begin',
'',
'    if :P183_EMP is null then',
'        :P183_EMP := :P183_COD_EMP_REQ;',
'    end if;',
'    ',
'    begin',
'        select cod_empresa||'' - ''||nome_abrev',
'        into :P183_COD_EMPRESA',
'        from empresas',
'        where cod_empresa = :P183_EMP;',
'    exception',
'        when others then',
'          :P183_COD_EMPRESA := NULL;    ',
'    end;',
'    --',
'    begin',
'        select matricula||'' - ''||initcap(NOME)',
'            into :P183_MATRICULA',
'            from inf_pessoais',
'            where cod_empresa = :P183_EMP',
'            and matricula = :P183_MAT;',
'    exception',
'        when others then',
'          :P183_MATRICULA := NULL;    ',
'    end;',
'    ',
'   ',
'    ',
'    l_step := 1001;',
'    if :P183_COD_REQ is null then',
'        :P183_NOVA_REQUISICAO := null;',
'        SELECT TIPO,',
'                COD_EVENTO ,',
'                (HORAS||'':''||lpad(MINUTOS, 2,''0'')),',
unistr('                ''De ''||:P183_DT_INI||'' At\00E9 ''||:P183_DT_FIM,'),
'                 decode( BH_APURADO, ''Aberto'', ''A'', ''Fechado'', ''F'', ''Manual'', ''M'', ''A'')',
'',
'            INTO :P183_TIPO_EVENTO',
'                        , :P183_COD_EVENTO_NOVO_DSP            ',
'                        , :P183_QTD_HORAS',
'                        , :P183_DATA',
'                        , :p183_BH_APURADO',
'        FROM (',
'        select ',
'                ''BANCO''     TIPO,',
'                e.COD_EVENTO,',
'                B.DESCRICAO,',
'                e.TIPO_EVENTO,',
'                e.BH_APURADO,',
'                sum(substr(e.QTD_HORAS,1,instr(e.QTD_HORAS,'':'')-1)) HORAS,',
'                sum(substr(e.QTD_HORAS,instr(e.QTD_HORAS,'':'')+1) ) MINUTOS',
'                from pe_resultado_apuracao e, pe_eventos_banco b',
'                where 1=1',
'                and e.cod_empresa = b.cod_empresa',
'                and e.cod_evento = b.cod_evento_banco',
'                and e.cod_empresa = :P183_EMP',
'                and e.matricula =  :P183_MAT ',
'                and e.data between :P183_DT_INI AND :P183_DT_FIM',
'                and e.cod_evento =  :P183_COD_EVENTO',
'                and E.QTD_HORAS != ''00:00''',
'                group by  ',
'                ''BANCO'',',
'                e.COD_EVENTO,',
'                B.DESCRICAO,',
'                e.TIPO_EVENTO,',
'                e.BH_APURADO',
'',
'          union',
'',
'                select ''PONTO'', --B.TIPO,',
'                e.COD_EVENTO,',
'                B.DESCRICAO,',
'                e.TIPO_EVENTO,',
'                e.BH_APURADO,',
'                sum(substr(e.QTD_HORAS,1,instr(e.QTD_HORAS,'':'')-1)) HORAS,',
'                sum(substr(e.QTD_HORAS,instr(e.QTD_HORAS,'':'')+1) ) MINUTOS',
'',
'                from pe_resultado_apuracao e, pe_eventos_folha b',
'                where 1=1',
'                and e.cod_empresa = b.cod_empresa',
'                and e.cod_evento = b.cod_evento_folha',
'                and e.cod_empresa = :P183_EMP',
'                and e.matricula = :P183_MAT  ',
'                and e.data between :P183_DT_INI AND :P183_DT_FIM',
'                and e.cod_evento =  :P183_COD_EVENTO',
'                and E.QTD_HORAS != ''00:00''',
'                group by  ',
'                ''PONTO'',',
'                e.COD_EVENTO,',
'                B.DESCRICAO,',
'                e.TIPO_EVENTO,',
'                e.BH_APURADO);',
'',
'',
'        if :P183_TIPO_EVENTO = ''PONTO'' then',
'            l_step := 110;',
'             begin   ',
'                select ',
unistr('                        decode(tipo_rubrica, 1, ''Cr\00E9dito'', 2, ''D\00E9bito'', 3, ''Base'') tipo,'),
'                        decode(tipo_rubrica, 1, ''C'', 2, ''D'', 3, ''B'') tipo_code,',
'                       cod_evento_folha||'' - ''||descricao descricao',
'                into :P183_TIPO',
'                    , :P183_TIPO_CODE',
'                    , :P183_EVENTO',
'                     from pe_eventos_folha p, ocorr_pagto op',
'                     where p.cod_evento_folha = :P183_COD_EVENTO',
'                     and op.cod_empresa = p.cod_empresa ',
'                     and op.cod = p.cod_ocorr',
'                     and p.cod_empresa = nvl(:P183_EMP, :P183_COD_EMP_REQ); ',
'            exception',
'                when others then',
'                    l_erro := SQLERRM;',
'                    apex_error.add_error(p_message => ''(''||l_step||'') Erro ao recuperar dados do evento folha atual ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);',
'            end;',
'        else',
'            l_step := 120;',
'            begin',
unistr('                select  decode(b.tipo,''C'',''Cr\00E9dito'',''D'',''D\00E9bito'') tipo,'),
'                    cod_evento_banco||'' - ''||descricao descricao,',
'                    b.tipo tipo_code',
'                into :P183_TIPO',
'                    , :P183_EVENTO',
'                    , :P183_TIPO_CODE',
'                from pe_eventos_banco b',
'                where cod_evento_banco =  :P183_COD_EVENTO',
'                     and b.cod_empresa = nvl(:P183_EMP, :P183_COD_EMP_REQ); ',
'                ',
'            exception',
'                when others then',
'                    l_erro := SQLERRM;',
'                    apex_error.add_error(p_message => ''(''||l_step||'') Erro ao recuperar dados do evento banco atual ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);',
'            end;',
'        end if;  ',
'    else',
'        l_step := 2;',
'        begin',
'            select 1',
'                   , r.cod_item           cod_item_req',
'                   , r.dt_req           data_requisicao',
'                   , r.dt_sit_req       data_situacao_req',
'                   , r.cod_sit_req',
'                   /*, decode (r.cod_sit_req, 1, ''Aberta'',',
unistr('                                        2,''Conclu\00EDda'','),
'                                        3,''Cancelada'',',
'                                        4,''Reprovada'',',
'                                        5,''aprovada'',',
unistr('                                        6,''Suspens\00E3o'') cod_sit_req*/'),
unistr('                   , decode( r.tipo_atual, ''C'', ''Cr\00E9dito'', ''D'', ''D\00E9bito'' ) tipo_atual                    '),
unistr('                   , decode( r.tipo, ''C'', ''Cr\00E9dito'', ''D'', ''D\00E9bito'' ) tipo '),
'                   , r.tipo tipo_cod',
'                   , r.cod_emp_req           cod_emp_req',
'                   , r.mat_req               mat_req',
'                   , r.tipo_evento_atual     tipo_evento_atual',
'                   , r.cod_evento_atual      cod_evento_atual',
'                   , r.qtd_horas_atual       qtd_horas_atual',
'                   , r.data_ponto            data_ponto',
'                   , r.tipo_evento           tipo_evento_novo',
'                   , r.cod_evento            cod_evento_novo',
'                   , r.qtd_horas             qtd_horas_novo ',
'                   , decode( r.bh_apurado_atual,''A'',''Aberto'',''F'',''Fechado'',''M'',''Manual'', r.bh_apurado_atual ) apurado_atual',
'                   , decode( r.bh_apurado,''A'',''Aberto'',''F'',''Fechado'',''M'',''Manual'', r.bh_apurado ) apurado_req',
'                   , r.cod_empresa||'' - ''||(select nome from empresas_cad where cod = r.cod_empresa) empresa',
'                   --, r.matricula||'' - ''||(select distinct nome from inf_pessoais_cad where matricula = r.matricula) matricula',
'                    , r.matricula||'' - ''||( select distinct  nome',
'                                            from inf_pessoais_cad ip,  ',
'                                                 informacoes_funcionais_cad if',
'                                            where if.matricula = ip.matricula',
'                                            and if.cod_empresa =  ip.cod_empresa',
'                                            and if.cod_empresa =  r.cod_empresa',
'                                            and if.matricula = r.matricula) matricula',
'                    , (select descricao from pe_tipo_justificativa where cod_empresa = r.cod_emp_req  and COD_JUSTIFICATIVA = r.COD_JUSTIFICATIVA) COD_JUSTIFICATIVA',
'                    , r.COD_CCUSTO_CONTABIL',
'              into l_pos',
'                  , :P183_COD_ITEM',
'                  , :P183_DT_REQ',
'                  , :P183_DT_SIT_REQ',
'                  , :P183_COD_SIT_REQ',
'                  , :P183_TIPO',
'                  , :P183_TIPO_DISP_NOVO_DSP',
'                  , :P183_TIPO_CODE',
'                  , :P183_COD_EMP_REQ',
'                  , :p183_MAT_REQ',
'                  , :P183_TIPO_EVENTO',
'                  , :P183_COD_EVENTO',
'                  , :P183_QTD_HORAS',
'                  , :P183_DATA',
'                  , :P183_TIPO_EVENTO_NOVO_DSP',
'                  , :P183_COD_EVENTO_NOVO_DSP',
'                  , :P183_QTD_HORAS_NOVO_DSP',
'                  , :P183_BH_APURADO',
'                  , :P183_BH_APURADO_DSP',
'                  , :P183_COD_EMPRESA',
'                  , :P183_MATRICULA',
'                  , :P183_COD_JUSTIFICATIVA_DSP',
'                  , :P183_COD_CCUSTO_CONTABIL_DSP',
'                  ',
'            from PE_REQ_APURACAO r    --, PE_RESULTADO_APURACAO a',
'            where  r.cod_req = :P183_COD_REQ;',
'            ',
'            :P183_DATA_PONTO_DSP     := :P183_DATA;',
'            :P183_NOVA_REQUISICAO    := :P183_COD_REQ;',
'        exception',
'            when others then',
'                l_pos  := 0; ',
'                l_erro := SQLERRM;',
unistr('                apex_error.add_error(p_message => ''(''||l_step||'') Erro geral ao recuperar dados da requisi\00E7\00E3o ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);'),
'        end;',
'        if l_pos != 0 then',
'            l_step := 3;',
'            if :P183_TIPO_EVENTO = ''PONTO'' then',
'                  l_step := 3.5;',
'                  begin   ',
'                      select      cod_evento_folha||'' - ''||descricao descricao',
'                      into :P183_EVENTO',
'                        from pe_eventos_folha p',
'                        where cod_evento_folha = :P183_COD_EVENTO',
'                     and p.cod_empresa = nvl(:P183_EMP, :P183_COD_EMP_REQ); ',
'                  exception',
'                      when others then',
'                    l_erro := SQLERRM;',
'                    apex_error.add_error(p_message => ''(''||l_step||'') Erro geral ao recuperar dados do evento folha atual ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);',
'                  end;',
'            else',
'            l_step := 3.6;',
'                begin',
'                    select    cod_evento_banco||'' - ''||descricao descricao',
'                    into :P183_EVENTO',
'                    from pe_eventos_banco b',
'                    where cod_evento_banco =  :P183_COD_EVENTO',
'                     and b.cod_empresa = nvl(:P183_EMP, :P183_COD_EMP_REQ); ',
'                exception',
'                    when others then',
'                        l_erro := SQLERRM;',
'                        apex_error.add_error(p_message => ''(''||l_step||'') Erro ao recuperar dados do evento banco atual ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);',
'                end;',
'            end if;',
'            --',
'            l_step := 4;',
'            if :P183_TIPO_EVENTO_NOVO_DSP = ''PONTO'' then',
'            l_step := 4.5;',
'                  begin   ',
'                      select      cod_evento_folha||'' - ''||descricao descricao',
'                      into :P183_COD_EVENTO_NOVO_DSP',
'                        from pe_eventos_folha p',
'                        where cod_evento_folha = :P183_COD_EVENTO_NOVO_DSP',
'                     and p.cod_empresa = nvl(:P183_EMP, :P183_COD_EMP_REQ); ',
'                  exception',
'                      when others then',
'                    l_erro := SQLERRM;',
'                    apex_error.add_error(p_message => ''(''||l_step||'') Erro geral ao recuperar dados do evento folha novo ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);',
'                  end;',
'            else',
'            l_step := 4.6;',
'                begin',
'                    select    cod_evento_banco||'' - ''||descricao descricao',
'                    into :P183_COD_EVENTO_NOVO_DSP',
'                    from pe_eventos_banco b',
'                    where cod_evento_banco =  :P183_COD_EVENTO_NOVO_DSP',
'                     and b.cod_empresa = nvl(:P183_EMP, :P183_COD_EMP_REQ); ',
'                exception',
'                    when others then',
'                        l_erro := SQLERRM;',
'                        apex_error.add_error(p_message => ''(''||l_step||'') Erro ao recuperar dados do evento banco novo ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);',
'                end;',
'            end if;',
'            --:P183_DATA_PONTO_DSP     := :P183_DATA;',
'            --:P183_TIPO_DISP_NOVO_DSP := :P183_TIPO;        ',
'        end if;',
'        ',
'    end if;',
'exception',
'    when others then',
'        l_erro := SQLERRM;',
'        l_step := 999;',
unistr('        apex_error.add_error(p_message => ''(''||l_step||'') Erro geral ao recuperar dados da requisi\00E7\00E3o ''||:P183_COD_REQ||''. => ''||l_erro, p_display_location => apex_error.c_inline_in_notification);'),
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
