begin
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(150135958604476967289)
,p_process_sequence=>60
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Permite cancelar concluida'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_operador_cancela_concluida       parametros_recursos_humanos.operador_cancela_concluida%type;',
'    l_operador_cancela_requisicoes     parametros_recursos_humanos.operador_cancela_requisicoes%type;',
'begin',
'    :P183_OPERADOR_DELETA := ''N'';',
'    :P183_OPERADOR_DELETA_DEMAIS := ''N'';',
'    --',
'    if :P183_COD_SIT_REQ != 3 then    -- Nao cancelada',
'        select operador_cancela_concluida',
'            into l_operador_cancela_concluida',
'        from parametros_recursos_humanos',
'            where cod_empresa = :P_EMPRESA_USER;',
'        --',
'        select operador_cancela_requisicoes',
'            into l_operador_cancela_requisicoes',
'        from parametros_recursos_humanos',
'            where cod_empresa = :P_EMPRESA_USER;',
'        --',
'        if :P_PAINEL = ''PO'' then      -- Painel do Operador',
'            --',
'            if l_operador_cancela_concluida = ''S'' and :P183_COD_SIT_REQ = 2 then',
'                :P183_OPERADOR_DELETA := ''S'';',
'            end if;',
'            if l_operador_cancela_requisicoes = ''S''  then',
'                :P183_OPERADOR_DELETA_DEMAIS := ''S'';',
'            end if;',
'            ',
'        elsif :P_PAINEL = ''PG'' then     -- Painel do Gestor',
'        --sekect periodo gestor',
'            if (:P183_COD_SIT_REQ = 2 or :P183_COD_SIT_REQ = 1 )  then',
'                :P183_OPERADOR_DELETA := ''S'';',
'                :P183_OPERADOR_DELETA_DEMAIS := ''S'';',
'            end if;',
'            ',
'        else    -- Painel do Colaborador',
'            --',
'            if :P183_COD_SIT_REQ = 1 then',
'                :P183_OPERADOR_DELETA := ''S'';',
'                :P183_OPERADOR_DELETA_DEMAIS := ''S'';',
'            end if;        ',
'        end if;',
'   end if;',
'end;      ',
'',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(148950930408108198797)
,p_process_sequence=>70
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Carrega tempor\00E1ria')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_cod_req    pe_req_apuracao.cod_req%type;',
'begin',
'    if :p183_seq is null then',
'        :p183_seq := to_number(to_char(sysdate,''ddmmrrrrhh24miss''));',
'    end if;',
'',
'    DELETE FROM PE_RESULTADO_APURACAO_TEMP_REQ',
'        WHERE SEQ_ID = :p183_seq;',
'        ',
'    for c1 in (SELECT DATA , POSICAO, QTD_HORAS , COD_ITEM, ID_APURACAO',
'                FROM PE_RESULTADO_APURACAO',
'                WHERE COD_EMPRESA = :P183_EMP',
'                AND MATRICULA = :P183_MAT',
'                AND DATA BETWEEN :P183_DT_INI AND :P183_DT_FIM',
'                AND COD_EVENTO = :P183_COD_EVENTO',
'                AND QTD_HORAS != ''00:00''',
'    )',
'    loop',
'    /*',
'        begin ',
'            select cod_req',
'                into v_cod_req',
'            from pe_req_apuracao',
'                where cod_empresa = :P183_EMP',
'                and matricula = :P183_MAT',
'                and data_ponto = c1.data',
'                and cod_evento_atual = :P183_COD_EVENTO;',
'        exception',
'            when others then',
'                v_cod_req := null;',
'        end;',
'        */',
'        insert into PE_RESULTADO_APURACAO_TEMP_REQ',
'        (cod_empresa ',
'            ,matricula',
'            ,cod_evento',
'            ,data',
'            ,posicao',
'            ,qtd_horas',
'            ,qtd_horas_original',
'            ,cod_item',
'            ,id_apuracao',
'            ,seq_id',
'            ,usuario',
'            ,dt_atualizacao',
'            , cod_req)',
'            values',
'            ( :P183_EMP',
'            , :P183_MAT',
'            , :P183_COD_EVENTO',
'            , c1.data',
'            , c1.posicao',
'            , c1.qtd_horas',
'            , c1.qtd_horas',
'            , c1.cod_item',
'            , c1.id_apuracao',
'            , :p183_seq',
'            , :P_USUARIO',
'            , SYSDATE',
'             , v_cod_req',
'            );',
'    end loop;',
'end;',
'    '))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
