wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(311128435917773585857)
,p_plug_name=>unistr('Requisi\00E7\00E3o de Apura\00E7\00E3o')
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(209353570115087209769)
,p_plug_display_sequence=>50
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct',
'       c.solicitacao solicitacao,',
'       c.dt_solicitacao data_abertura,',
'       c.cod_empresa||'' - ''||initcap(fnct_nome_empresa(c.cod_empresa)) Empresa, ',
'       r.matricula||'' - ''||initcap(fnct_nome_func(r.cod_empresa, r.matricula)) Matricula_Solicitada,',
'       c.cod_empresa_solicitante||'' - ''||Initcap(fnct_nome_empresa(c.cod_empresa_solicitante)) Empresa_Solicitante,',
'       c.mat_solicitante||'' - ''||initcap(fnct_nome_func(c.cod_empresa_solicitante, c.mat_solicitante)) Solicitante,',
'       decode(cod_sit_req,1,''<span class="fa fa-play-circle colorNone" aria-hidden="true"></span> ''||''Aberta'',',
unistr('                            2,''<span aria-hidden="true" class="fa fa-check-circle colorSuccess"></span> ''||''Conclu\00EDda'','),
'                            3,''<span aria-hidden="true" class="fa fa-times-circle colorDanger"></span> ''||''Cancelada'',',
'                            4,''<span aria-hidden="true" class="fa fa-times-circle colorDanger"></span> ''||''Reprovada'',',
'                            5,''<span aria-hidden="true" class="fa fa-check-circle colorInfo"></span> ''||''Aprovada'',',
unistr('                            6,''<span aria-hidden="true" class="fa fa-pause-circle colorAlert"></span> ''||''Suspens\00E3o'') Situacao,'),
'       r.cod_empresa,',
'       r.cod_req cod_solicitacao,',
'       c.cod_empresa_solicitante,',
'       c.mat_solicitante,',
'       r.matricula,',
'       r.data_ponto,',
'       r.qtd_horas,',
'       --r.hora_final,',
'       i.filial||'' - ''||initcap(fnct_nome_filial(i.cod_empresa, i.filial)) Filial,',
'       i.cod_ccusto||'' - ''||initcap(fnct_nome_ccusto(i.cod_empresa, i.cod_ccusto)) centro_de_custo,',
'       i.unidade_adm||'' - ''||initcap(fnct_nome_unidade_adm(i.cod_empresa, null, i.unidade_adm)) unidade_adm,',
'       i.cod_atividade||'' - ''||initcap(fnct_nome_atividade(i.cod_atividade)) atividade,',
'       i.cargo||'' - ''||initcap(fnct_nome_cargo(i.cargo)) cargo,',
'        r.obs_aprovador, ',
'        ',
'        r.tipo_evento_atual    TIPO_EVENTO_ORIGINAL, ',
'        r.cod_evento_atual||'' -''||',
'        (SELECT DESCRICAO FROM PE_EVENTOS_BANCO BANCO ',
'                WHERE r.tipo_evento_atual = ''BANCO'' ',
'                AND r.cod_evento_atual = BANCO.COD_EVENTO_BANCO ',
'                AND R.COD_EMPRESA = BANCO.COD_EMPRESA',
'                UNION',
'                SELECT DESCRICAO FROM PE_EVENTOS_FOLHA FOLHA',
'                WHERE r.tipo_evento_atual = ''PONTO'' ',
'                AND r.cod_evento_atual = FOLHA.COD_EVENTO_FOLHA',
'                AND R.COD_EMPRESA = FOLHA.COD_EMPRESA                ',
'                ) EVENTO_DESCRICAO_ATUAL,',
'         ',
unistr('        decode(r.tipo, ''C'', ''Cr\00E9dito'', ''D'', ''D\00E9bito'') TIPO_ORIGINAL, '),
'        ',
'        r.tipo_evento TIPO_EVENTO_SOLICITADO, ',
'        r.cod_evento||'' - ''||',
'        (SELECT DESCRICAO FROM PE_EVENTOS_BANCO BANCO ',
'                WHERE r.tipo_evento = ''BANCO'' ',
'                AND r.cod_evento = BANCO.COD_EVENTO_BANCO ',
'                AND R.COD_EMPRESA = BANCO.COD_EMPRESA',
'                UNION',
'                SELECT DESCRICAO FROM PE_EVENTOS_FOLHA FOLHA',
'                WHERE r.tipo_evento = ''PONTO'' ',
'                AND r.cod_evento = FOLHA.COD_EVENTO_FOLHA',
'                AND R.COD_EMPRESA = FOLHA.COD_EMPRESA                ',
'                ) EVENTO_DESCRICAO_NOVO,',
'                         ',
unistr('        decode(r.tipo, ''C'', ''Cr\00E9dito'', ''D'', ''D\00E9bito'') TIPO_SOLICITADO, '),
'',
'        r.cod_justificativa, ',
'        r.cod_ccusto_contabil,',
'        r.usuario, ',
'        r.dt_atualizacao, ',
'       R.COD_ITEM,',
'        case',
'            when cod_sit_req = 3 then',
'            :P_USUARIO',
'        else',
'            null',
'        end usuario_cancelamento,',
'        case',
'            when cod_sit_req = 3 then',
'            r.dt_atualizacao',
'        else',
'            null',
'        end dt_cancelamento',
'',
' from consulta_requisicoes c,',
'       PE_REQ_APURACAO r,',
'       informacoes_funcionais_cad i',
' where upper(c.tipo_req) = ''REQ_APURA''',
'   and c.cod_empresa     = r.cod_empresa',
'   and c.solicitacao     = r.cod_req',
'   and r.cod_empresa = i.cod_empresa',
'   and r.matricula = i.matricula',
'   and (((c.cod_empresa_solicitante = :P_EMPRESA_USER',
'   and           c.mat_solicitante = :P_MATRICULA_USER) or ',
'        (c.cod_emp_aprov = :P_EMPRESA_USER',
'   and       c.mat_aprov = :P_MATRICULA_USER) and :p_painel = ''PG'') or',
'        ((((f_acesso_pg_apex(i.cod_empresa, i.matricula, i.filial, i.cd_nivel, :p_usuario, :p_painel) = ''S'') or (COD_EMP_APROV = :P_EMPRESA_USER AND MAT_APROV = :P_MATRICULA_USER)))',
'         and :p_painel = ''PO'') or',
'        (i.cod_empresa = :P_EMPRESA_USER and i.matricula = :P_MATRICULA_USER and :p_painel = ''PC'') or',
'        (r.cod_empresa = :p200_emp and r.matricula = :p200_mat and :p200_mat is not null))',
'   and ((r.cod_sit_req = :p200_sit_req) or (:p200_sit_req is null))',
'   and (((trunc(sysdate) - trunc(r.dt_req)) <= :p200_periodo) or (:p200_periodo = 0))',
'   and (:p200_REQUISICAO  is null or c.solicitacao        in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(REPLACE(TRIM(:p200_REQUISICAO),'' ''), '','')) t))',
'   and (:p200_empresa     is null or i.cod_empresa in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p200_EMPRESA, '','')) t))',
'   and (:p200_FILIAL      is null or i.filial        in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p200_FILIAL, '','')) t))',
'   and (:p200_CCUSTO      is null or i.cod_ccusto    in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p200_CCUSTO, '','')) t))',
'   and (:p200_UNIDADE_ADM is null or i.unidade_adm   in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p200_UNIDADE_ADM, '','')) t))',
'   and (:p200_ATIVIDADE   is null or i.cod_atividade in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p200_ATIVIDADE, '','')) t))',
'   and (:p200_CARGO       is null or i.cargo         in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p200_CARGO, '','')) t))',
'   and (:p200_MATRICULA_1   is null or i.matricula    in (select /*+ cardinality (t 1)*/ column_value from table(apex_string.split(:p200_MATRICULA_1, '','')) t))   ',
' order by solicitacao desc'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_document_header=>'APEX'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
