 p_id=>wwv_flow_api.id(176794784204566020966)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'popula_colab'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select i.cod_empresa||'' - ''||initcap(fnct_nome_empresa(i.cod_empresa)) empresa,',
'       i.matricula||'' - ''||initcap(fnct_nome_func(i.cod_empresa, i.matricula)) matricula,',
'       i.situacao||'' - ''||initcap(fnct_nome_situacao(i.situacao))||'' - ''||i.dt_situacao situacao,',
'       i.dt_admissao',
'  from informacoes_funcionais i',
' where i.cod_empresa = :p200_emp',
'   and i.matricula = :p200_mat;',
'                   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'if :p_painel = ''PC'' then',
'',
':p200_emp := :p_empresa_user;',
':p200_mat := :p_matricula_user;',
'',
'end if;',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
':p200_cod_empresa1 := v_c1.empresa;',
':p200_matricula := v_c1.matricula;',
':p200_situacao := v_c1.situacao;',
':p200_dt_admissao := v_c1.dt_admissao;',
'',
'--:p200_OK := ''S'';',
'',
'exception',
'when others then',
':p200_cod_empresa := :p200_emp;',
':p200_matricula := :p200_mat;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
