wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(196793935067361122623)
,p_name=>'P214_COD_EVENTO_NOVO'
,p_is_required=>true
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_api.id(220464141659890672820)
,p_prompt=>'Evento'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  lsql         varchar2(4000);',
'  lcoeficiente pe_eventos_folha.COEFICIENTE%type;',
'begin',
'    lsql := ''select ''''001 - descricao'''', ''''code'''' from dual'';',
'    if :P214_TIPO_EVENTO_NOVO is not null then',
'        if :P214_TIPO_EVENTO_NOVO = ''BANCO'' then ',
'            begin',
'                if :P214_TIPO_EVENTO = :P214_TIPO_EVENTO_NOVO then',
'                    select nvl(COEFICIENTE_PONTO, 1) into lcoeficiente from pe_eventos_banco where cod_evento_banco = :P214_COD_EVENTO and cod_empresa = :P214_EMP;',
'                else',
'                         select nvl(COEFICIENTE, 1) into lcoeficiente from pe_eventos_folha  where cod_evento_folha = :P214_COD_EVENTO and cod_empresa = :P214_EMP;',
'                end if;',
'            exception',
'                when others then',
'                    lcoeficiente := 1;',
'            end;',
'            --            ',
'            lsql := ''select COD_EVENTO_BANCO||'''' - ''''||e.DESCRICAO descricao, e.COD_EVENTO_BANCO COD_EVENTO from pe_eventos_banco e ',
'                    where e.cod_empresa = ''''''||:P214_EMP||''''''  and e.tipo = ''''''||:P214_TIPO_CODE||'''''' and e.coeficiente_ponto = ''||replace(lcoeficiente, '','', ''.'')||''',
'                  AND NOT EXISTS  (select 1 from pe_eventos_perfil P  where p.tipo_evento = ''''''||:P214_TIPO_EVENTO_NOVO||'''''' and p.cd_perfil = ''''''||:P_PERFIL||'''''' ',
'                              and p.cod_empresa = ''''''||:P214_EMP||'''''') union',
'                select COD_EVENTO_BANCO||'''' - ''''||e.DESCRICAO descricao, e.COD_EVENTO_BANCO COD_EVENTO',
'                 from pe_eventos_perfil p, pe_eventos_banco e where e.cod_evento_banco = p.cod_evento  and e.coeficiente_ponto = ''||replace(lcoeficiente, '','', ''.'')||''',
'                    and e.tipo = ''''''||:P214_TIPO_CODE ||'''''' and e.cod_empresa =''''''||:P214_EMP||''''''  and p.tipo_evento = ''''''||:P214_TIPO_EVENTO_NOVO||'''''' and p.cd_perfil = ''''''||:P_PERFIL||''''''  '';    ',
'       else     ',
'            begin',
'                if :P214_TIPO_EVENTO = :P214_TIPO_EVENTO_NOVO then',
'                    select nvl(COEFICIENTE, 1) into lcoeficiente from pe_eventos_folha  where cod_evento_folha = :P214_COD_EVENTO and cod_empresa = :P214_EMP;',
'                else',
'                    select nvl(COEFICIENTE_PONTO, 1) into lcoeficiente from pe_eventos_banco where cod_evento_banco = :P214_COD_EVENTO and cod_empresa = :P214_EMP;                         ',
'                end if;',
'            exception',
'                when others then',
'                    lcoeficiente := 1;',
'            end;',
'            --            ',
'           lsql := ''select  COD_EVENTO_FOLHA||'''' - ''''||e.DESCRICAO descricao, e.COD_EVENTO_FOLHA COD_EVENTO from pe_eventos_folha e , ocorr_pagto op',
'                    where e.cod_empresa = ''''''||:P214_EMP||'''''' and e.coeficiente = ''||replace(lcoeficiente, '','', ''.'')||''',
'                    and e.cod_empresa =  op.cod_empresa and e.cod_ocorr = op.cod ',
'                    and ( (op.tipo_rubrica in ( 1, 3) and ''''''||:P214_TIPO_CODE||'''''' = ''''C'''') or ( op.tipo_rubrica in ( 2, 3 ) and ''''''||:P214_TIPO_CODE||'''''' = ''''D'''') )',
'              AND NOT EXISTS  (select 1 from pe_eventos_perfil P where p.tipo_evento = ''''''||:P214_TIPO_EVENTO_NOVO||'''''' and p.cd_perfil = ''''''||:P_PERFIL||'''''' and p.cod_empresa = ''''''||:P214_EMP||'''''') union',
'            select COD_EVENTO_FOLHA||'''' - ''''||e.DESCRICAO descricao, e.COD_EVENTO_FOLHA COD_EVENTO from pe_eventos_perfil p, pe_eventos_folha e, ocorr_pagto op',
'            where e.cod_evento_folha = p.cod_evento and e.cod_empresa =''''''||:P214_EMP||'''''' and e.cod_empresa =  op.cod_empresa and e.cod_ocorr = op.cod ',
'                    and e.coeficiente = ''||replace(lcoeficiente, '','', ''.'')||''',
'                    and ( (op.tipo_rubrica in ( 1, 3) and ''''''||:P214_TIPO_CODE||'''''' = ''''C'''') or ( op.tipo_rubrica in ( 2, 3 ) and ''''''||:P214_TIPO_CODE||'''''' = ''''D'''') )',
'              and tipo_evento = ''''''||:P214_TIPO_EVENTO_NOVO||'''''' and cd_perfil = ''''''||:P_PERFIL||'''''' ''; ',
'       end if;',
'       lsql := lsql||'' order by 2'';',
'    end if;',
'   return lsql;',
'end;'))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P214_TIPO_EVENTO_NOVO,P214_EMP,P214_COD_EVENTO,P214_TIPO_EVENTO'
,p_ajax_optimize_refresh=>'N'
,p_cHeight=>1
,p_grid_label_column_span=>4
,p_field_template=>wwv_flow_api.id(209353590986122209808)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'NONE'
,p_attribute_02=>'N'
);
