wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(196793938805434122630)
,p_validation_name=>'DATA_LIMITE'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  --',
'  v_data_ref_ponto DATE;',
'  v_cod_evento NUMBER(3);',
'  vl_qtd_horas VARCHAR2(8);',
'--  ',
'BEGIN',
'  --',
'  BEGIN',
'	  --',
'	  SELECT NVL(data_ref_ponto,TRUNC(SYSDATE))',
'	    INTO v_data_ref_ponto',
'	    FROM parametros_recursos_humanos',
'	   WHERE cod_empresa = :P214_EMP;',
'  --',
'  EXCEPTION',
'  	--',
'	  WHEN OTHERS THEN',
'	    --',
'	    v_data_ref_ponto := TRUNC(SYSDATE);',
'  --',
'  END;',
'  --',
'  IF :P214_DATA < v_data_ref_ponto THEN',
'	  --',
'    RETURN (''Data fora do limite permitido: '' || v_data_ref_ponto);',
'',
'  --',
'  END IF; ',
'  ',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_message=>unistr('Erro: Valida\00E7\00E3o')
,p_always_execute=>'Y'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
