wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(197340065372589256758)
,p_validation_name=>unistr('Valida Apura\00E7\00E3o Novo Evento')
,p_validation_sequence=>70
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  vReturn  VARCHAR2(550) DEFAULT NULL;',
'  --',
'  CURSOR cParamRH IS',
'    SELECT x.verif_regsemanal_oper',
'     FROM parametros_recursos_humanos x',
'    WHERE x.cod_empresa = :P214_EMP;',
'  --',
'  rParamRH    cParamRH%ROWTYPE;',
'BEGIN',
'  OPEN cParamRH;',
'  FETCH cParamRH INTO rParamRH;',
'  CLOSE cParamRH;',
'  --',
'  IF (NVL(rParamRH.verif_regsemanal_oper, ''N'') = ''S'' OR :P_PAINEL IN(''PG'',''PC'')) THEN',
'    IF :P214_TIPO_EVENTO_NOVO = ''BANCO'' THEN',
'      IF :P214_DATA_NOVO IS NOT NULL AND :P214_QTD_HORAS_NOVO IS NOT NULL AND :P214_TIPO_NOVO IS NOT NULL THEN',
'        vReturn := PKG_REQ_HE.fnc_ValApuracaoNovoEvento(pEmpresa   => :P214_EMP',
'                                                       ,pMatricula => :P214_MAT',
'                                                       ,pDtInicio  => :P214_DATA_NOVO',
'                                                       ,pHora      => :P214_QTD_HORAS_NOVO',
'                                                       ,pTipEvento => :P214_TIPO_NOVO);',
'      END IF; ',
'    END IF;',
'  END IF;',
'  --',
'  IF vReturn IS NOT NULL THEN',
unistr('    vReturn := ''<strong>Inclus\00E3o de Novo Evento N\00C3O Permitida!</strong><br>''||REPLACE(REPLACE(REPLACE(vReturn, ''|'', ''<br>''), ''['',''<strong>''), '']'',''</strong>'');'),
'  END IF;',
'  --',
'  RETURN(vReturn);',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
