wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196793940715631122631)
,p_process_sequence=>70
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Popula_campos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select f.cod_evento_folha||'' - ''||f.descricao descricao, TO_CHAR(F.COD_OCORR) TIPO, FOLHA FOLHA',
'  from pe_eventos_folha f',
' where f.cod_empresa = :p214_emp',
'   and f.cod_evento_folha = :p214_cod_evento',
'   and :p214_tipo_evento = ''PONTO''',
'union ',
'select b.cod_evento_banco||'' - ''||b.descricao descricao, B.TIPO TIPO, ''S'' FOLHA',
'  from pe_eventos_banco b',
' where b.cod_empresa = :p214_emp',
'   and b.cod_evento_banco = :p214_cod_evento',
'   and :p214_tipo_evento = ''BANCO'';',
'   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
':p214_evento := v_c1.descricao;',
'',
'IF :P_BASE <> ''PREVCOM'' AND :P214_TIPO_EVENTO = ''PONTO'' AND TO_NUMBER(V_C1.TIPO) < 500 /*AND V_C1.FOLHA = ''S''*/ THEN',
unistr('   :P214_TIPO := ''Cr\00E9dito'';'),
'   :P214_TIPO_CODE := ''C'';',
'elsif :P_BASE <> ''PREVCOM'' AND :P214_TIPO_EVENTO = ''PONTO'' AND TO_NUMBER(V_C1.TIPO) >= 500 /*AND V_C1.FOLHA = ''S''*/ THEN',
unistr('    :P214_TIPO := ''D\00E9bito'';'),
'   :P214_TIPO_CODE := ''D'';',
'    ',
'ELSIF :P_BASE = ''PREVCOM'' AND :P214_TIPO_EVENTO = ''PONTO'' AND TO_NUMBER(V_C1.TIPO) < 5000 /*AND V_C1.FOLHA = ''S''*/ THEN',
unistr('   :P214_TIPO := ''Cr\00E9dito'';'),
'   :P214_TIPO_CODE := ''C'';',
'   ',
'elsif :P_BASE = ''PREVCOM'' AND :P214_TIPO_EVENTO = ''PONTO'' AND TO_NUMBER(V_C1.TIPO) >= 5000 /*AND V_C1.FOLHA = ''S''*/ THEN',
unistr('    :P214_TIPO := ''D\00E9bito'';'),
'   :P214_TIPO_CODE := ''D'';',
'    ',
'elsif :P214_TIPO_EVENTO = ''PONTO'' AND V_C1.FOLHA = ''N''  THEN',
