wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(196793941098787122632)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Salvar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_cod_evento NUMBER(5);',
'    vl_qtd_horas VARCHAR2(8);',
'	dDATA_NOVO date;',
'	dDT_FIM date;',
'	dDATA date;',
'    ',
'    pflg_retorno     VARCHAR2(4000);',
'    pmsg_retorno     VARCHAR2(4000);    ',
'begin',
'    execute immediate ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= ''''.,'''' '';',
'    PKG_IDIOMA.SETA_IDIOMA(''AMERICAN'');',
'    ',
'	dDATA_NOVO := :P214_DATA_NOVO;',
'	dDT_FIM := :P215_DT_FIM;',
'	dDATA := :P214_DATA;',
'    select  max(A.COD_EVENTO),',
'            max(A.QTD_HORAS)',
'    into    v_cod_evento,',
'            vl_qtd_horas',
'    from    PE_RESULTADO_APURACAO A',
'    where   A.COD_EMPRESA = :P214_EMP',
'    and     A.MATRICULA = :P214_MAT',
'    and     A.TIPO_EVENTO = :P214_TIPO_EVENTO_NOVO',
'    and     A.COD_EVENTO = :P214_COD_EVENTO_NOVO',
'    and     A.DATA = dDATA_NOVO;',
'    ',
'    if vl_qtd_horas is null or dDT_FIM != dDATA then',
'            PKG_PE_ABONO.PRC_INSERE_APURACAO(:P214_EMP, ',
'                                           :P214_MAT, ',
'                                           dDATA, ',
'                                           dDATA_NOVO, ',
'                                           :P214_TIPO_EVENTO, ',
'                                           :P214_TIPO_EVENTO_NOVO,',
'                                           :P214_COD_EVENTO, ',
'                                           :P214_COD_EVENTO_NOVO, ',
'                                           :P214_COD_ITEM, ',
'                                           :P214_QTD_HORAS, ',
'                                           :P214_QTD_HORAS_NOVO, ',
'                                           :P_USUARIO,',
'                                           :P214_ROWID_REMAN,',
'                                           :P214_SALDO_REMAN',
'                                           );',
'    end if;',
'    --',
'    PKG_PE_ABONO.PRC_UPDATE_APURACAO(',
'                :P214_EMP, ',
'                :P214_MAT, ',
'                dDATA, ',
'                dDATA_NOVO, ',
'                :P214_TIPO_EVENTO, ',
'                :P214_TIPO_EVENTO_NOVO,',
'                case when vl_qtd_horas is not null and dDATA_NOVO = dDATA then vl_qtd_horas end,',
'                case when vl_qtd_horas is not null and dDATA_NOVO = dDATA then v_cod_evento end,',
'                :P214_COD_EVENTO,',
'                :P214_COD_EVENTO_NOVO,',
'                :P214_COD_ITEM, ',
'                :P214_QTD_HORAS, ',
'                :P214_QTD_HORAS_NOVO, ',
'                :P_USUARIO',
'    );    ',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SALVAR'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>'Dados gravados com sucesso!'
);
