,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Salvar_old'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  v_data_ref_ponto DATE;',
'  v_cod_evento NUMBER(3);',
'  vl_qtd_horas VARCHAR2(8);',
'  v_cod_item NUMBER(15);',
'  ',
'  v_cod_evento_novo NUMBER(3);',
'  vl_qtd_horas_novo VARCHAR2(8);',
'  ',
'  V_DATA      DATE;',
'  V_DATA_NOVO DATE;',
'  ',
'  V_QTD_HORAS      VARCHAR2(6);',
'  V_QTD_HORAS_NOVO VARCHAR2(6);',
'  ',
'begin',
'',
'EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= ''''.,'''' '';',
'',
'BEGIN',
'PKG_IDIOMA.SETA_IDIOMA(''AMERICAN'');',
'END;',
'',
'    V_DATA      := :P214_DATA;',
'    V_DATA_NOVO := :P214_DATA_NOVO;',
'',
'    V_QTD_HORAS      := :P214_QTD_HORAS; --TO_CHAR(:P214_QTD_HORAS     ,''HH24:MI'');',
'    V_QTD_HORAS_NOVO := :P214_QTD_HORAS_NOVO; --TO_CHAR(:P214_QTD_HORAS_NOVO,''HH24:MI'');',
'    ',
'      BEGIN',
'',
'        SELECT qtd_horas, cod_evento',
'          INTO vl_qtd_horas, v_cod_evento',
'          FROM pe_resultado_apuracao',
'         WHERE cod_empresa = :P214_EMP',
'           AND matricula = :P214_MAT',
'           AND cod_evento = :P214_COD_EVENTO_NOVO',
'           AND tipo_evento = :P214_TIPO_EVENTO_NOVO',
'           AND data = :P214_DATA_NOVO;',
'',
'      EXCEPTION',
'        WHEN no_data_found THEN',
'          vl_qtd_horas := NULL;',
'      END;',
' ',
'      ',
'      IF vl_qtd_horas IS NULL THEN',
'      ',
'      --dbms_output.put_line(''#01'');',
'      ',
'        BEGIN',
'          PKG_PE_ABONO.PRC_INSERE_APURACAO(:P214_EMP, ',
'                                           :P214_MAT, ',
'                                           V_DATA, ',
'                                           V_DATA_NOVO, ',
'                                           :P214_tipo_evento, ',
'                                           :P214_tipo_evento_NOVO, ',
'                                           :P214_COD_EVENTO, ',
'                                           :P214_COD_EVENTO_NOVO, ',
'                                           :P214_COD_ITEM, ',
'                                           V_QTD_HORAS, ',
'                                           V_QTD_HORAS_NOVO, ',
'                                           :P_USUARIO',
'                                           );',
'        END;',
'        BEGIN',
'            PKG_PE_ABONO.PRC_UPDATE_APURACAO(:P214_EMP, ',
'                                           :P214_MAT, ',
'                                           V_DATA, ',
'                                           V_DATA_NOVO, ',
'                                           :P214_tipo_evento, ',
'                                           :P214_tipo_evento_NOVO,',
'                                           NULL,',
'                                           NULL, ',
'                                           :P214_COD_EVENTO,',
'                                           :P214_COD_EVENTO_NOVO, ',
'                                           :P214_COD_ITEM, ',
'                                           V_QTD_HORAS, ',
'                                           V_QTD_HORAS_NOVO, ',
'                                           :P_USUARIO',
'                                           );',
'        END;',
'        ',
'        NULL;',
'      ELSE',
'        BEGIN',
'          IF V_DATA_NOVO <> V_DATA THEN',
'          --dbms_output.put_line(''#03'');',
'          null;',
'          ',
'            PKG_PE_ABONO.PRC_INSERE_APURACAO(:P214_EMP, ',
'                                           :P214_MAT, ',
'                                           V_DATA, ',
'                                           V_DATA_NOVO, ',
'                                           :P214_tipo_evento, ',
'                                           :P214_tipo_evento_NOVO, ',
'                                           :P214_COD_EVENTO, ',
'                                           :P214_COD_EVENTO_NOVO, ',
'                                           :P214_COD_ITEM, ',
'                                           V_QTD_HORAS, ',
'                                           V_QTD_HORAS_NOVO, ',
'                                           :P_USUARIO',
'                                           );',
'            BEGIN',
'                PKG_PE_ABONO.PRC_UPDATE_APURACAO(:P214_EMP, ',
'                                               :P214_MAT, ',
'                                               V_DATA, ',
'                                               V_DATA_NOVO, ',
'                                               :P214_tipo_evento, ',
'                                               :P214_tipo_evento_NOVO,',
'                                               NULL,',
'                                               NULL, ',
'                                               :P214_COD_EVENTO,',
'                                               :P214_COD_EVENTO_NOVO, ',
'                                               :P214_COD_ITEM, ',
'                                               V_QTD_HORAS, ',
'                                               V_QTD_HORAS_NOVO, ',
'                                               :P_USUARIO',
'                                               );',
'            END;',
'            ',
'          ELSE',
'          --dbms_output.put_line(''#04'');',
'          null;',
'          ',
'            PKG_PE_ABONO.PRC_UPDATE_APURACAO(:P214_EMP, ',
'                                           :P214_MAT, ',
'                                           V_DATA, ',
'                                           V_DATA_NOVO, ',
'                                           :P214_tipo_evento, ',
'                                           :P214_tipo_evento_NOVO,',
'                                           vl_qtd_horas,',
'                                           v_cod_evento, ',
'                                           :P214_COD_EVENTO,',
'                                           :P214_COD_EVENTO_NOVO, ',
'                                           :P214_COD_ITEM, ',
'                                           V_QTD_HORAS, ',
'                                           V_QTD_HORAS_NOVO, ',
'                                           :P_USUARIO',
'                                           );',
'                                           NULL;',
'                                           ',
'          END IF;',
'        END;',
'      END IF;',
'end;'))
