wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(194417023998889806072)
,p_name=>'P215_COD_EVENTO_NOVO'
,p_is_required=>true
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_api.id(194410894860419932379)
,p_prompt=>'Evento'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT e.COD_EVENTO_FOLHA||'' - ''||e.DESCRICAO descricao, e.COD_EVENTO_FOLHA COD_EVENTO',
'FROM PE_EVENTOS_FOLHA e',
'WHERE e.COD_EMPRESA = :P215_EMP',
'AND upper(:P215_TIPO_EVENTO_NOVO) = ''PONTO''',
'AND e.VISUALIZAR = ''S''',
'AND e.COD_EVENTO_FOLHA IN (select p.COD_EVENTO',
'from pe_eventos_perfil p',
'where p.cd_perfil in (select u.cd_perfil',
'from usuario_oracle u',
'where u.nm_usuario_oracle = :P_USUARIO)',
'and p.tipo_evento = ''PONTO''',
'and exists (select px.cod_evento from pe_eventos_perfil px where px.tipo_evento = ''PONTO''))',
'and e.COD_EVENTO_FOLHA in (select a.cod_evento_folha',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''BANCO'' and b.cod_evento_banco = :P215_cod_evento',
'union',
'select b.cod_evento_banco',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''PONTO'' and a.cod_evento_folha = :P215_cod_evento)',
'UNION',
'SELECT e.COD_EVENTO_BANCO||'' - ''||e.DESCRICAO descricao, e.COD_EVENTO_BANCO COD_EVENTO',
'FROM PE_EVENTOS_BANCO e',
'WHERE e.COD_EMPRESA = :P215_EMP',
'AND e.TIPO = :P215_COD_TIPO',
'',
'AND upper(:P215_TIPO_EVENTO_NOVO) = ''BANCO''',
'AND e.COD_EVENTO_BANCO IN (select p.COD_EVENTO',
'from pe_eventos_perfil p',
'where p.cd_perfil in (select u.cd_perfil',
'from usuario_oracle u',
'where u.nm_usuario_oracle = :P_USUARIO)',
'and p.tipo_evento = ''BANCO''',
'and exists (select px.cod_evento from pe_eventos_perfil px where px.tipo_evento = ''BANCO''))',
'and e.COD_EVENTO_BANCO in (select a.cod_evento_folha',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''BANCO'' and b.cod_evento_banco = :P215_cod_evento',
'union',
'select b.cod_evento_banco',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''PONTO'' and a.cod_evento_folha = :P215_cod_evento)',
'UNION',
'SELECT e.COD_EVENTO_FOLHA||'' - ''||e.DESCRICAO descricao, e.COD_EVENTO_FOLHA COD_EVENTO',
'FROM PE_EVENTOS_FOLHA e',
'WHERE e.COD_EMPRESA = :P215_EMP',
'AND e.VISUALIZAR = ''S''',
'AND upper(:P215_TIPO_EVENTO_NOVO) = ''PONTO''',
'and NOT exists (select p.cod_evento from pe_eventos_perfil p where p.CD_PERFIL = (select u.cd_perfil',
'from usuario_oracle u',
'where u.nm_usuario_oracle = :P_USUARIO))',
'and e.COD_EVENTO_FOLHA in (select a.cod_evento_folha',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''BANCO'' and b.cod_evento_banco = :P215_cod_evento',
'union',
'select b.cod_evento_banco',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''PONTO'' and a.cod_evento_folha = :P215_cod_evento)',
'UNION',
'SELECT e.COD_EVENTO_BANCO||'' - ''||e.DESCRICAO descricao, e.COD_EVENTO_BANCO COD_EVENTO',
'FROM PE_EVENTOS_BANCO e',
'WHERE e.COD_EMPRESA = :P215_EMP',
'AND upper(:P215_TIPO_EVENTO_NOVO) = ''BANCO''',
'AND e.TIPO = :P215_COD_TIPO',
'and NOT exists (select p.cod_evento from pe_eventos_perfil p where p.CD_PERFIL = (select u.cd_perfil',
'from usuario_oracle u',
'where u.nm_usuario_oracle = :P_USUARIO))',
'and e.COD_EVENTO_BANCO in (select a.cod_evento_folha',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''BANCO'' and b.cod_evento_banco = :P215_cod_evento',
'union',
'select b.cod_evento_banco',
'from pe_eventos_folha a, pe_eventos_banco b',
'where a.cod_empresa = b.cod_empresa',
'and a.coeficiente = b.coeficiente_ponto',
'and b.cod_empresa = :P215_emp',
'and :P215_tipo_evento = ''PONTO'' and a.cod_evento_folha = :P215_cod_evento)',
'ORDER BY 2'))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P215_TIPO_EVENTO_NOVO,P215_EMP,P215_COD_EVENTO,P215_TIPO_EVENTO'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_grid_label_column_span=>5
,p_field_template=>wwv_flow_api.id(209353591168387209809)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'NONE'
,p_attribute_02=>'N'
);
