'    if v_c1.tipo is not null then',
'        :p215_tipo_novo := v_c1.tipo;',
'        if v_c1.folha = ''S'' then',
'        :p215_tipo_disp_novo := v_c1.tipo_desc;',
'        end if;',
'    end if;',
'    ',
'end;'))
