wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(194410897407743932404)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Salvar'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    nCOD_ITEM number;',
'    nHORA_PROC number(15,3) := 0;',
'    nHORA_TRANSF constant number(15,3) := FUNC_HORA_TO_DEC(:P215_QTD_HORAS_NOVO);',
'	nHORA_TOT_REMAN number(15,3);',
'    nHORA number(15,3);',
'	nHORA_REMAN number(15,3);',
'    cHORA varchar2(8);',
'	cHORA_REMAN varchar2(8);',
'    vMSG varchar2(4000);',
'	cROWID_REMAN varchar2(50);',
'    ',
'    v_cod_evento NUMBER(3);',
'    vl_qtd_horas VARCHAR2(8);',
'  ',
'begin',
'    EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= ''''.,'''' '';',
'    PKG_IDIOMA.SETA_IDIOMA(''AMERICAN'');',
'    ',
'	if :P215_ROWID_REMAN is not null then',
'		nHORA_TOT_REMAN := FUNC_HORA_TO_DEC(:P214_SALDO_REMAN);',
'		cROWID_REMAN := :P215_ROWID_REMAN;',
'	end if;',
'    for C in (',
'        select  A.COD_ITEM,',
'                A.DATA,',
'                FUNC_HORA_TO_DEC(A.QTD_HORAS) HORA_DEC,',
'                A.QTD_HORAS',
'        from    PE_RESULTADO_APURACAO A',
'        where   A.COD_EMPRESA = :P215_EMP',
'        and     A.MATRICULA = :P215_MAT',
'        and     A.TIPO_EVENTO = :P215_TIPO_EVENTO',
'        and     A.COD_EVENTO = :P215_COD_EVENTO',
'        and     A.DATA between to_date(:P215_DT_INI,''DD/MM/YYYY'') and to_date(:P215_DT_FIM,''DD/MM/YYYY'')',
'        order by A.DATA',
'    ) loop',
'        -- Calcular hora',
'        if nHORA_PROC = nHORA_TRANSF then',
'            exit;',
'        end if;',
'		if C.HORA_DEC > (nHORA_TRANSF - nHORA_PROC) then',
'			nHORA := nHORA_TRANSF - nHORA_PROC;',
'		else',
'			nHORA := C.HORA_DEC;',
'		end if;',
'		-- Horas remanescentes',
'		if cROWID_REMAN is not null then',
'			if nHORA > nHORA_TOT_REMAN then',
'				nHORA_REMAN := nHORA_TOT_REMAN;',
'			else',
'				nHORA_REMAN := nHORA;',
'			end if;',
'		end if;',
'		',
'        cHORA := FUNC_DEC_TO_HORA(nHORA);',
'        ',
'        -- Validar operacao',
'        if :P215_TIPO_EVENTO_NOVO = ''BANCO'' then',
'            vMSG := PKG_REQ_HE.fnc_ValApuracaoNovoEvento(',
'                                                      pEmpresa   => :P215_EMP',
'                                                     ,pMatricula => :P215_MAT',
'                                                     ,pDtInicio  => to_date(:P215_DT_FIM,''DD/MM/YYYY'')',
'                                                     ,pHora      => cHORA',
'                                                     ,pTipEvento => :P215_TIPO_NOVO);',
'            if vMSG is not null then',
'                dbms_output.put_line(''vMSG: ''||vMSG);',
'                -- Tratar aqui quando os dados nao passar na validacao',
'                exit;',
'            end if;',
'        end if;',
'		',
'        if nHORA_REMAN > 0 then',
'			cHORA_REMAN := FUNC_DEC_TO_HORA(nHORA_REMAN);',
'		else',
'			cROWID_REMAN := '''';',
'			cHORA_REMAN := '''';',
'		end if;',
'		',
'        select  max(A.COD_EVENTO),',
'                max(A.QTD_HORAS)',
'        into    v_cod_evento,',
'                vl_qtd_horas',
'        from    PE_RESULTADO_APURACAO A',
'        where   A.COD_EMPRESA = :P215_EMP',
'        and     A.MATRICULA = :P215_MAT',
'        and     A.TIPO_EVENTO = :P215_TIPO_EVENTO_NOVO',
'        and     A.COD_EVENTO = :P215_COD_EVENTO_NOVO',
'        and     A.DATA = to_date(:P215_DT_FIM,''DD/MM/YYYY'');',
'',
'        if vl_qtd_horas is null or to_date(:P215_DT_FIM,''DD/MM/YYYY'') != C.DATA then',
'            PKG_PE_ABONO.PRC_INSERE_APURACAO(',
'                    :P215_EMP,',
'                    :P215_MAT,',
'                    C.DATA,',
'                    to_date(:P215_DT_FIM,''DD/MM/YYYY''),',
'                    :P215_TIPO_EVENTO,',
'                    :P215_TIPO_EVENTO_NOVO,',
'                    :P215_COD_EVENTO,',
'                    :P215_COD_EVENTO_NOVO,',
'                    C.COD_ITEM,',
'                    C.QTD_HORAS,',
'                    cHORA,',
'                    :P_USUARIO,',
'					cROWID_REMAN,',
'					cHORA_REMAN',
'            );',
'        end if;',
'        ',
'        PKG_PE_ABONO.PRC_UPDATE_APURACAO(',
'                    :P215_EMP, ',
'                    :P215_MAT, ',
'                    C.DATA, ',
'                    to_date(:P215_DT_FIM,''DD/MM/YYYY''), ',
'                    :P215_TIPO_EVENTO, ',
'                    :P215_TIPO_EVENTO_NOVO,',
'                    case when vl_qtd_horas is not null and to_date(:P215_DT_FIM,''DD/MM/YYYY'') = C.DATA then vl_qtd_horas end,',
'                    case when vl_qtd_horas is not null and to_date(:P215_DT_FIM,''DD/MM/YYYY'') = C.DATA then v_cod_evento end,',
'                    :P215_COD_EVENTO,',
'                    :P215_COD_EVENTO_NOVO,',
'                    C.COD_ITEM, ',
'                    C.QTD_HORAS, ',
'                    cHORA, ',
'                    :P_USUARIO					',
'        );',
'        ',
'        -- Atualizar andamento do processamento',
'        nHORA_PROC := nHORA_PROC + nHORA;',
'		if nHORA_REMAN > 0 then',
'			nHORA_TOT_REMAN := nHORA_TOT_REMAN - nHORA_REMAN;',
'		end if;',
'    end loop;',
'end;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SALVAR'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
);
