wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(194410895406884932384)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Popular itens'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_cod_tipo varchar2(1);',
'begin ',
'with',
'    TP_TIPOS_EV as (',
'        select  A.COD_EVENTO_FOLHA COD_EVENTO,',
'                A.DESCRICAO,',
'                to_char(A.COD_OCORR) TIPO, ',
'                A.FOLHA,',
'                ''PONTO'' TIPO_EVENTO',
'        from    PE_EVENTOS_FOLHA A',
'        where   A.COD_EMPRESA = :P215_EMP',
'        and     A.COD_EVENTO_FOLHA = :P215_COD_EVENTO',
'        union ',
'        select  B.COD_EVENTO_BANCO COD_EVENTO,',
'                B.DESCRICAO, ',
'                B.TIPO, ',
'                ''S'' FOLHA,',
'                ''BANCO'' TIPO_EVENTO',
'        from    PE_EVENTOS_BANCO b',
'        where   B.COD_EMPRESA = :P215_EMP',
'        and     B.COD_EVENTO_BANCO = :P215_COD_EVENTO',
'   )',
'select  A.TIPO_EVENTO,',
'        B.COD_EVENTO||'' - ''||B.DESCRICAO EVENTO,',
'        case',
unistr('            when :p_base <> ''PREVCOM'' AND A.TIPO_EVENTO = ''PONTO'' and to_number(B.TIPO) < 500 /*and B.FOLHA = ''S''*/ then ''Cr\00E9dito'''),
unistr('            when :p_base <> ''PREVCOM'' AND A.TIPO_EVENTO = ''PONTO'' and to_number(B.TIPO) >= 500 /*and B.FOLHA = ''S''*/ then ''D\00E9bito'''),
unistr('            when :p_base = ''PREVCOM'' AND A.TIPO_EVENTO = ''PONTO'' and to_number(B.TIPO) < 5000 /*and B.FOLHA = ''S''*/ then ''Cr\00E9dito'''),
unistr('            when :p_base = ''PREVCOM'' AND A.TIPO_EVENTO = ''PONTO'' and to_number(B.TIPO) >= 5000 /*and B.FOLHA = ''S''*/ then ''D\00E9bito'''),
'            when A.TIPO_EVENTO = ''PONTO'' and B.FOLHA = ''N'' then ''''',
unistr('            else decode(B.TIPO,''C'',''Cr\00E9dito'',''D'',''D\00E9bito'')'),
'        end TIPO,',
'        replace(:P215_HORAS,''.'','':''),',
'        b.tipo',
'into    :P215_TIPO_EVENTO,',
'        :P215_EVENTO,',
'        :P215_TIPO,',
'        :P215_HORAS,',
'        :P215_COD_TIPO',
'from    PE_RESULTADO_APURACAO A,',
'        TP_TIPOS_EV B',
'where   A.COD_EMPRESA = :P215_EMP',
'and     A.MATRICULA = :P215_MAT',
'and     A.COD_EVENTO = :P215_COD_EVENTO',
'and		UPPER( A.TIPO_EVENTO ) = UPPER( :P215_TIPO_EVENTO )',
'and     A.DATA between to_date(:P215_DT_INI,''DD/MM/YYYY'') and to_date(:P215_DT_FIM,''DD/MM/YYYY'')',
'and     A.TIPO_EVENTO = B.TIPO_EVENTO',
'and     A.COD_EVENTO = B.COD_EVENTO',
'group by',
'        A.TIPO_EVENTO,',
'        B.COD_EVENTO,',
'        B.DESCRICAO,',
'        A.TIPO_EVENTO,',
'        B.TIPO,',
'        B.FOLHA;',
'        ',
unistr(' select case when :P215_TIPO = ''Cr\00E9dito'' then  ''C'''),
'             else  ''D'' end ',
'             into v_cod_tipo',
'from dual;',
'',
':P215_COD_TIPO := v_cod_tipo;',
'end;        '))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
/
prompt --application/pages/page_00220
begin
wwv_flow_api.create_page(
 p_id=>220
,p_user_interface_id=>wwv_flow_api.id(209353596631966209865)
,p_name=>unistr('Ajuste de Resultado de Apura\00E7\00E3o ')
,p_step_title=>unistr('Ajuste de Resultado de Apura\00E7\00E3o')
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'ON'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// =============================================================',
unistr('// M\00E1scara HH:MI no campo QTD_HORAS do IG (suporta HHHH:MI)'),
'// =============================================================',
'var QTD_HORAS_INPUT_ID = null;',
'',
'function getQtdHorasInputId() {',
'    if (!QTD_HORAS_INPUT_ID) {',
unistr('        // o id do <span> do header \00E9 "C{N}_HDR" e o id do input \00E9 "C{N}"'),
'        $("#GRID_ID_ig .a-GV-headerLabel").each(function() {',
'            if ($(this).text().trim() === "Qtd Horas") {',
'                QTD_HORAS_INPUT_ID = this.id.replace("_HDR", "");',
'                return false;  // break',
'            }',
'        });',
'    }',
'    return QTD_HORAS_INPUT_ID;',
'}',
'',
'function formatarQtdHoras(input) {',
unistr('    // remove tudo que n\00E3o \00E9 d\00EDgito'),
'    var v = input.value.replace(/[^\d]/g, '''');',
'',
unistr('    // limita a 6 d\00EDgitos (HHHH MM)'),
'    if (v.length > 6) { v = v.substring(0, 6); }',
'',
'    var formatado;',
'    if (v.length === 0) {',
'        formatado = '''';',
'    } else if (v.length <= 2) {',
'        formatado = v;                                  // ainda digitando',
'    } else {',
unistr('        // \00FAltimos 2 d\00EDgitos = minutos; o resto = horas'),
'        formatado = v.substring(0, v.length - 2)',
'                  + '':''',
'                  + v.substring(v.length - 2);',
'    }',
'',
'    if (input.value !== formatado) {',
'        input.value = formatado;',
'        try { input.setSelectionRange(formatado.length, formatado.length); } catch (e) {}',
'    }',
'}',
'',
unistr('// listener delegado \00BF funciona pra qualquer linha do grid'),
'$(document)',
'    .off("input.qtdhoras")',
'    .on("input.qtdhoras", "#GRID_ID_ig input", function() {',
'        var qtdId = getQtdHorasInputId();',
'        if (qtdId && this.id === qtdId) {',
'            formatarQtdHoras(this);',
'        }',
'    });',
'',
'',
'',
'',
'',
'// =============================================================',
unistr('// CONFIG \00BF edite s\00F3 estes arrays pra adicionar/remover bloqueios'),
'// =============================================================',
'// =============================================================',
unistr('// Observer \00BF reaplica regras quando o IG troca de p\00E1gina, ordena, etc.'),
'// =============================================================',
'var _gridObserverConfigurado = false;',
'',
'function setupGridObserver() {',
'    if (_gridObserverConfigurado) { return; }',
'',
'    var alvo = document.querySelector("#GRID_ID_ig div.a-GV-bdy");',
'    if (!alvo) { return; }',
'',
'    var debounceTimer;',
'    var observer = new MutationObserver(function() {',
'        clearTimeout(debounceTimer);',
'        debounceTimer = setTimeout(function() {',
'            aplicaBloqueioRequisicao();',
'            aplicaColunasReadonly();',
'        }, 80);',
'    });',
'',
unistr('    // childList+subtree dispara s\00F3 em adi\00E7\00E3o/remo\00E7\00E3o de n\00F3s (n\00E3o em troca de class),'),
unistr('    // portanto N\00C3O entra em loop quando o pr\00F3prio JS aplica .is-locked / .col-locked'),
'    observer.observe(alvo, { childList: true, subtree: true });',
'',
'    _gridObserverConfigurado = true;',
'}',
'',
'',
unistr('// Colunas sempre read-only (use o LABEL exato exibido no cabe\00E7alho)'),
'var COLUNAS_READONLY = [',
'    "Empresa",',
unistr('    "Matr\00EDcula",'),
'    "Data",',
'    "Cod Req",',
'    "Cod Req 2",',
unistr('    "Usu\00E1rio",'),
unistr('    "Data Atualiza\00E7\00E3o",'),
unistr('    "Trava Apura\00E7\00E3o"'),
'];',
'',
'// =============================================================',
unistr('// REGRA 1 \00BF Linha bloqueada quando tem requisi\00E7\00E3o (COD_REQ / COD_REQ_2)'),
'// =============================================================',
'function aplicaBloqueioRequisicao() {',
'    try {',
'        var region = apex.region("GRID_ID");',
'        if (!region) { return; }',
'',
'        var model = region.widget().interactiveGrid("getViews", "grid").model;',
'',
'        $("#GRID_ID_ig tr.a-GV-row.is-locked").removeClass("is-locked");',
'',
'        model.forEach(function(record, index, id) {',
'            var codReq  = model.getValue(record, "COD_REQ");',
'            var codReq2 = model.getValue(record, "COD_REQ_2");',
'',
'            var temReq = (codReq  !== null && codReq  !== undefined && String(codReq).trim()  !== "")',
'                      || (codReq2 !== null && codReq2 !== undefined && String(codReq2).trim() !== "");',
'',
'            if (temReq) {',
'                $(''#GRID_ID_ig tr.a-GV-row[data-id="'' + id + ''"]'').addClass("is-locked");',
'                if (typeof model.setRecordMetadata === "function") {',
'                    model.setRecordMetadata(id, { canEdit: false });',
'                }',
'            }',
'        });',
'    } catch (e) {',
'        console.warn("aplicaBloqueioRequisicao falhou:", e);',
'    }',
'}',
'',
'// =============================================================',
unistr('// REGRA 2 \00BF Colunas sempre read-only (lista em COLUNAS_READONLY)'),
'// =============================================================',
'function aplicaColunasReadonly() {',
'    try {',
'        // limpa marcas antigas',
'        $("#GRID_ID_ig .col-locked").removeClass("col-locked");',
'',
unistr('        // 1) Descobre os data-id das linhas NOVAS (rec\00E9m-inseridas, n\00E3o salvas)'),
'        var idsLinhasNovas = [];',
'        try {',
'            var model = apex.region("GRID_ID").widget()',
'                                              .interactiveGrid("getViews", "grid").model;',
'            model.forEach(function(record, index, id) {',
'                var meta = model.getRecordMetadata(id);',
'                if (meta && meta.inserted) {',
'                    idsLinhasNovas.push(String(id));',
'                }',
'            });',
unistr('        } catch (e) { /* segue sem exclus\00E3o */ }'),
'',
'        // 2) Pinta as colunas, exceto nas linhas novas',
'        var $headers = $("#GRID_ID_ig div.a-GV-hdr div.a-GV-w-hdr table > thead > tr > th.a-GV-header");',
'',
'        $headers.each(function(position) {',
'            var $th    = $(this);',
'            var label  = $th.find(".a-GV-headerLabel").text().trim();',
'',
'            if (COLUNAS_READONLY.indexOf(label) >= 0) {',
'                var nth = ":nth-child(" + (position + 1) + ")";',
'',
'                $("#GRID_ID_ig div.a-GV-bdy div.a-GV-w-scroll table > tbody > tr").each(function() {',
'                    var $tr  = $(this);',
'                    var trId = String($tr.attr("data-id"));',
'',
'                    // pula linhas novas',
'                    if (idsLinhasNovas.indexOf(trId) !== -1) { return; }',
'',
'                    $tr.find("> td" + nth).addClass("col-locked");',
'                });',
'            }',
'        });',
'    } catch (e) {',
'        console.warn("aplicaColunasReadonly falhou:", e);',
'    }',
'}',
'',
'// =============================================================',
unistr('// Wrapper \00BF chame este na DA After Refresh'),
'// =============================================================',
'function aplicaTodasRegrasIG() {',
'    aplicaBloqueioRequisicao();',
'    aplicaColunasReadonly();',
unistr('    setupGridObserver();   // idempotente \00BF s\00F3 configura na 1\00AA chamada'),
'}',
'',
'// =============================================================',
unistr('// Mensagem ao clicar em c\00E9lula bloqueada (linha OU coluna)'),
'// =============================================================',
'function aviseCelulaBloqueada(e) {',
'    var $cell = $(e.target).closest("td.a-GV-cell, th.a-GV-cell");',
'    var $row  = $(e.target).closest("tr.a-GV-row.is-locked");',
'    var isColLocked = $cell.hasClass("col-locked");',
'',
'    if ($row.length || isColLocked) {',
'        apex.message.clearErrors();',
'        apex.message.showErrors([{',
'            type:     "warning",',
'            location: "page",',
'            message:  $row.length',
unistr('                ? "Esta linha possui requisi\00E7\00E3o associada e n\00E3o pode ser alterada."'),
unistr('                : "Esta coluna \00E9 somente leitura."'),
'        }]);',
'    }',
'}',
'',
'$(document)',
'    .off("click.aviseBloq")',
'    .on("click.aviseBloq",',
'        "#GRID_ID_ig tr.a-GV-row.is-locked td.a-GV-cell, " +',
'        "#GRID_ID_ig td.a-GV-cell.col-locked",',
'        aviseCelulaBloqueada);',
'',
''))
,p_javascript_code_onload=>'aplicaTodasRegrasIG();'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
