wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(33289436657293797824)
,p_plug_name=>'Novo'
,p_region_name=>'GRID_ID'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(209353570115087209769)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    a.cod_item,',
'    a.id_apuracao,',
'    a.step,',
'    a.plantao,',
'    a.cod_empresa,',
'    a.cod_empresa || '' - '' || INITCAP(fnct_nome_empresa(a.cod_empresa,''S'')) AS empresa_desc,',
'    a.matricula,',
'    a.matricula || '' - '' || INITCAP(fnct_nome_func(a.cod_empresa, a.matricula)) AS matricula_desc,',
'    a.data,',
'    a.tipo_evento,',
'    a.cod_evento,',
'    a.qtd_horas,',
'    a.posicao,',
'    a.bh_apurado,',
'    a.complemento,',
'    a.cod_req,',
'    a.cod_req_2,',
'    a.usuario,',
'    a.dt_atualizacao,',
'    a.trava_apuracao',
'FROM pe_resultado_apuracao a',
'WHERE (:P220_DT_INI IS NULL OR a.data >= :P220_DT_INI)',
'  AND (:P220_DT_FIM IS NULL OR a.data <= :P220_DT_FIM)',
'',
' AND (',
'      :P220_EMPRESA IS NULL',
'      OR a.cod_empresa IN (',
'            SELECT TO_NUMBER(TRIM(column_value))',
'            FROM TABLE(apex_string.split(:P220_EMPRESA, '',''))',
'            WHERE REGEXP_LIKE(column_value, ''^\d+$'')',
'      )',
')',
'  AND (:P220_MATRICULA IS NULL',
'       OR a.matricula IN (',
'            SELECT TO_NUMBER(column_value)',
'            FROM TABLE(apex_string.split(:P220_MATRICULA, '',''))',
'       ))',
'',
'  AND (',
'        :P220_TIPO_PERIODO IS NULL',
'',
'        OR (',
'             :P220_TIPO_PERIODO = ''DENTRO''',
'             AND EXISTS (',
'                    SELECT 1',
'                    FROM parametros_recursos_humanos b',
'                    WHERE b.cod_empresa = a.cod_empresa',
'                      AND a.data BETWEEN b.data_ini_ref_ponto',
'                                     AND b.data_fim_ref_ponto',
'             )',
'           )',
'',
'        OR (',
'             :P220_TIPO_PERIODO = ''FORA''',
'             AND NOT EXISTS (',
'                    SELECT 1',
'                    FROM parametros_recursos_humanos b',
'                    WHERE b.cod_empresa = a.cod_empresa',
'                      AND a.data BETWEEN b.data_ini_ref_ponto',
'                                     AND b.data_fim_ref_ponto',
'             )',
'            )',
'      )',
'',
'  AND (:P220_EVENTO IS NULL',
'       OR a.cod_evento IN (',
'            SELECT TO_NUMBER(column_value)',
'            FROM TABLE(apex_string.split(:P220_EVENTO, '',''))',
'       ))',
'',
'  AND (:P220_TIPO_EVENTO IS NULL',
'       OR a.tipo_evento IN (',
'            SELECT TRIM(column_value)',
'            FROM TABLE(apex_string.split(:P220_TIPO_EVENTO, '',''))',
'       ))'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_plug_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    a.cod_item,',
'    a.id_apuracao,',
'    a.step,',
'    a.plantao,',
'    a.cod_empresa,',
'    a.cod_empresa || '' - '' || INITCAP(fnct_nome_empresa(a.cod_empresa,''S'')) AS empresa_desc,',
'    a.matricula,',
'    a.matricula || '' - '' || INITCAP(fnct_nome_func(a.cod_empresa, a.matricula)) AS matricula_desc,',
'    a.data,',
'    a.tipo_evento,',
'    a.cod_evento,',
'    a.qtd_horas,',
'    a.posicao,',
'    a.bh_apurado,',
'    a.complemento,',
'    a.cod_req,',
'    a.cod_req_2,',
'    a.usuario,',
'    a.dt_atualizacao',
'FROM pe_resultado_apuracao a',
'WHERE a.data BETWEEN :P220_DT_INI AND :P220_DT_FIM',
'  AND (:P220_EMPRESA IS NULL',
'       OR a.cod_empresa IN (SELECT /*+ cardinality (t 1) */ TO_NUMBER(column_value)',
'                              FROM TABLE(apex_string.split(:P220_EMPRESA, '','')) t))',
'  AND (:P220_MATRICULA IS NULL',
'       OR a.matricula IN (SELECT /*+ cardinality (t 1) */ TO_NUMBER(column_value)',
'                            FROM TABLE(apex_string.split(:P220_MATRICULA, '','')) t))',
'  AND ( (:P220_TIPO_PERIODO = ''DENTRO''',
'         AND EXISTS (SELECT 1 FROM parametros_recursos_humanos b',
'                      WHERE b.cod_empresa = a.cod_empresa',
'                        AND a.data BETWEEN b.data_ini_ref_ponto AND b.data_fim_ref_ponto))',
'     OR (:P220_TIPO_PERIODO = ''FORA''',
'         AND EXISTS (SELECT 1 FROM parametros_recursos_humanos b',
'                      WHERE b.cod_empresa = a.cod_empresa',
'                        AND a.dt_atualizacao < b.data_ini_ref_ponto))',
'      )',
'      ',
'      ',
'      AND (:P220_EVENTO IS NULL',
'       OR a.cod_evento IN (SELECT /*+ cardinality (t 1) */ TO_NUMBER(column_value)',
'                            FROM TABLE(apex_string.split(:P220_EVENTO, '','')) t))',
'                            ',
'        AND (:P220_TIPO_EVENTO IS NULL',
'       OR a.tipo_evento IN (SELECT /*+ cardinality (t 1) */ (column_value)',
'                            FROM TABLE(apex_string.split(:P220_TIPO_EVENTO, '','')) t))        '))
);
