wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(33289439057953797848)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_api.id(33289436657293797824)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Novo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('  -- snapshot do estado ANTES da opera\00E7\00E3o'),
'  v_data         DATE;',
'  v_qtd_horas    VARCHAR2(8);',
'  v_cod_evento   VARCHAR2(4);',
'  v_tipo_evento  VARCHAR2(5);',
'  v_posicao      NUMBER;',
'  v_bh_apurado   VARCHAR2(1);',
'  v_complemento  VARCHAR2(300);',
'  v_cod_req      NUMBER;',
'  v_cod_req_2    NUMBER;',
'  v_usuario      VARCHAR2(30);',
'  v_dt_atu       DATE;',
'',
'  v_novo_cod_item NUMBER;',
'  v_existe        NUMBER;',
'  v_tem_req       NUMBER;',
'',
unistr('  -- c\00F3digo de requisi\00E7\00E3o buscado na PE_REQ_APURACAO (NULL se n\00E3o houver)'),
'  v_cod_req_novo  NUMBER;',
'',
'  -- =====================================================================',
unistr('  -- Busca o c\00F3digo de requisi\00E7\00E3o em PE_REQ_APURACAO para a mesma'),
unistr('  -- empresa + matr\00EDcula + data. Retorna NULL se n\00E3o existir requisi\00E7\00E3o.'),
'  --',
unistr('  -- >>> AJUSTE OS NOMES DE COLUNA conforme o dicion\00E1rio da PE_REQ_APURACAO:'),
'  --     cod_req / cod_empresa / matricula / data',
unistr('  -- Se houver coluna de situa\00E7\00E3o (ex.: s\00F3 requisi\00E7\00F5es aprovadas/ativas),'),
'  -- acrescente o filtro no WHERE indicado abaixo.',
'  -- =====================================================================',
'  FUNCTION func_busca_cod_req (',
'      p_cod_empresa IN NUMBER,',
'      p_matricula   IN NUMBER,',
'      p_data        IN DATE',
'  ) RETURN NUMBER IS',
'    v_ret NUMBER;',
'  BEGIN',
unistr('    -- MAX evita NO_DATA_FOUND e TOO_MANY_ROWS: se n\00E3o houver linha, retorna NULL.'),
'    SELECT MAX(r.cod_req)',
'      INTO v_ret',
'      FROM pe_req_apuracao r',
'     WHERE r.cod_empresa = p_cod_empresa',
'       AND r.matricula   = p_matricula',
'       AND TRUNC(r.data_ponto) = TRUNC(p_data)',
unistr('       -- AND r.situacao   = ''A''      -- <<< opcional: s\00F3 requisi\00E7\00F5es v\00E1lidas'),
'    ;',
'    RETURN v_ret;',
'  END func_busca_cod_req;',
'',
'  PROCEDURE prc_log_resultado_apuracao (',
'    p_operacao         IN VARCHAR2,',
'    p_usuario          IN VARCHAR2,',
'    p_cod_item         IN NUMBER,',
'    p_matricula        IN NUMBER,',
'    p_cod_empresa      IN NUMBER,',
'    p_id_apuracao      IN NUMBER,',
'    -- estado ANTES',
'    p_data_old         IN DATE,',
'    p_qtd_horas_old    IN VARCHAR2,',
'    p_cod_evento_old   IN VARCHAR2,',
'    p_tipo_evento_old  IN VARCHAR2,',
'    p_posicao_old      IN NUMBER,',
'    p_bh_apurado_old   IN VARCHAR2,',
'    p_complemento_old  IN VARCHAR2,',
'    -- estado DEPOIS',
'    p_data_new         IN DATE     DEFAULT NULL,',
'    p_qtd_horas_new    IN VARCHAR2 DEFAULT NULL,',
'    p_cod_evento_new   IN VARCHAR2 DEFAULT NULL,',
'    p_tipo_evento_new  IN VARCHAR2 DEFAULT NULL,',
'    p_posicao_new      IN NUMBER   DEFAULT NULL,',
'    p_bh_apurado_new   IN VARCHAR2 DEFAULT NULL,',
'    p_complemento_new  IN VARCHAR2 DEFAULT NULL,',
'    -- auditoria adicional',
'    p_cod_req          IN NUMBER,',
'    p_cod_req_2        IN NUMBER,',
'    p_usuario_original IN VARCHAR2,',
'    p_dt_atu_original  IN DATE',
'  ) IS',
'  BEGIN',
'    INSERT INTO log_pe_resultado_apuracao (',
'        log_id, log_data, log_usuario, log_operacao,',
'        cod_item, matricula, cod_empresa, id_apuracao,',
'        data_old, qtd_horas_old, cod_evento_old, tipo_evento_old,',
'        posicao_old, bh_apurado_old, complemento_old,',
'        data_new, qtd_horas_new, cod_evento_new, tipo_evento_new,',
'        posicao_new, bh_apurado_new, complemento_new,',
'        cod_req, cod_req_2,',
'        usuario_original, dt_atualizacao_orig',
'    ) VALUES (',
'        seq_log_pe_resultado_apuracao.NEXTVAL,',
'        SYSDATE, p_usuario, p_operacao,',
'        p_cod_item, p_matricula, p_cod_empresa, p_id_apuracao,',
'        p_data_old, p_qtd_horas_old, p_cod_evento_old, p_tipo_evento_old,',
'        p_posicao_old, p_bh_apurado_old, p_complemento_old,',
'        p_data_new, p_qtd_horas_new, p_cod_evento_new, p_tipo_evento_new,',
'        p_posicao_new, p_bh_apurado_new, p_complemento_new,',
'        p_cod_req, p_cod_req_2,',
'        p_usuario_original, p_dt_atu_original',
'    );',
'  END;',
'',
'BEGIN',
'  ----------------------------------------------------------------',
'  IF :APEX$ROW_STATUS = ''U'' THEN',
'  ----------------------------------------------------------------',
'    BEGIN',
'      SELECT data, qtd_horas, cod_evento, tipo_evento, posicao,',
'             bh_apurado, complemento, cod_req, cod_req_2,',
'             usuario, dt_atualizacao',
'        INTO v_data, v_qtd_horas, v_cod_evento, v_tipo_evento, v_posicao,',
'             v_bh_apurado, v_complemento, v_cod_req, v_cod_req_2,',
'             v_usuario, v_dt_atu',
'        FROM pe_resultado_apuracao',
'       WHERE cod_item    = :COD_ITEM',
'         AND matricula   = :MATRICULA',
'         AND cod_empresa = :COD_EMPRESA',
'         AND id_apuracao = :ID_APURACAO',
'         AND cod_req     IS NULL',
'         AND cod_req_2   IS NULL;',
'    EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'        NULL;',
'    END;',
'',
unistr('    -- Busca requisi\00E7\00E3o para empresa+matr\00EDcula+data (data da pr\00F3pria linha).'),
'    v_cod_req_novo := func_busca_cod_req(:COD_EMPRESA, :MATRICULA, v_data);',
'',
'    UPDATE pe_resultado_apuracao',
'       SET tipo_evento    = :TIPO_EVENTO,',
'           cod_evento     = :COD_EVENTO,',
'           qtd_horas      = :QTD_HORAS,',
'           posicao        = :POSICAO,',
'           complemento    = :COMPLEMENTO,',
'           bh_apurado     = DECODE(bh_apurado, ''F'', ''A'', bh_apurado),',
unistr('           cod_req        = v_cod_req_novo,   -- grava s\00F3 se a linha estava vazia (garantido pelo WHERE)'),
'           trava_apuracao = ''S'',',
'           usuario        = NVL(:APP_USER, USER),',
'           dt_atualizacao = SYSDATE',
'     WHERE cod_item    = :COD_ITEM',
'       AND matricula   = :MATRICULA',
'       AND cod_empresa = :COD_EMPRESA',
'       AND id_apuracao = :ID_APURACAO',
'       AND cod_req     IS NULL',
'       AND cod_req_2   IS NULL;',
'',
'    IF SQL%ROWCOUNT > 0 THEN',
'      prc_log_resultado_apuracao(',
'          p_operacao         => ''U'',',
'          p_usuario          => NVL(:APP_USER, USER),',
'          p_cod_item         => :COD_ITEM,',
'          p_matricula        => :MATRICULA,',
'          p_cod_empresa      => :COD_EMPRESA,',
'          p_id_apuracao      => :ID_APURACAO,',
'          -- OLD (snapshot capturado antes do UPDATE)',
'          p_data_old         => v_data,',
'          p_qtd_horas_old    => v_qtd_horas,',
'          p_cod_evento_old   => v_cod_evento,',
'          p_tipo_evento_old  => v_tipo_evento,',
'          p_posicao_old      => v_posicao,',
'          p_bh_apurado_old   => v_bh_apurado,',
'          p_complemento_old  => v_complemento,',
'          -- NEW (valores que ficaram na linha)',
'          p_data_new         => v_data,',
'          p_qtd_horas_new    => :QTD_HORAS,',
'          p_cod_evento_new   => :COD_EVENTO,',
'          p_tipo_evento_new  => :TIPO_EVENTO,',
'          p_posicao_new      => :POSICAO,',
'          p_bh_apurado_new   => CASE WHEN v_bh_apurado = ''F'' THEN ''A'' ELSE v_bh_apurado END,',
'          p_complemento_new  => :COMPLEMENTO,',
'          --',
unistr('          p_cod_req          => v_cod_req_novo,   -- registra no log a requisi\00E7\00E3o vinculada'),
'          p_cod_req_2        => v_cod_req_2,',
'          p_usuario_original => v_usuario,',
'          p_dt_atu_original  => v_dt_atu);',
'    ELSE',
'      SELECT COUNT(*),',
'             SUM(CASE WHEN cod_req IS NOT NULL OR cod_req_2 IS NOT NULL THEN 1 ELSE 0 END)',
'        INTO v_existe, v_tem_req',
'        FROM pe_resultado_apuracao',
'       WHERE cod_item    = :COD_ITEM',
'         AND matricula   = :MATRICULA',
'         AND cod_empresa = :COD_EMPRESA',
'         AND id_apuracao = :ID_APURACAO;',
'',
'      IF v_existe = 0 THEN',
'        apex_error.add_error(',
unistr('          p_message => ''Altera\00E7\00E3o falhou: registro n\00E3o encontrado (PK: '''),
'                       || :COD_ITEM || ''/'' || :MATRICULA || ''/''',
'                       || :COD_EMPRESA || ''/'' || :ID_APURACAO || '').'',',
'          p_display_location => apex_error.c_inline_in_notification);',
'      ELSIF NVL(v_tem_req,0) > 0 THEN',
'        apex_error.add_error(',
unistr('          p_message => ''Altera\00E7\00E3o bloqueada: registro possui requisi\00E7\00E3o (COD_REQ/COD_REQ_2).'','),
'          p_display_location => apex_error.c_inline_in_notification);',
'      ELSE',
'        apex_error.add_error(',
unistr('          p_message => ''Altera\00E7\00E3o n\00E3o realizada por motivo desconhecido.'','),
'          p_display_location => apex_error.c_inline_in_notification);',
'      END IF;',
'    END IF;',
'',
'  ----------------------------------------------------------------',
'  ELSIF :APEX$ROW_STATUS = ''C'' THEN',
'  ----------------------------------------------------------------',
'    v_novo_cod_item := func_pe_contador(''PE_RESULTADO_APURACAO'');',
'',
unistr('    -- Busca requisi\00E7\00E3o para empresa+matr\00EDcula+data informados na inclus\00E3o.'),
'    v_cod_req_novo := func_busca_cod_req(:COD_EMPRESA, :MATRICULA, :DATA);',
'',
'    INSERT INTO pe_resultado_apuracao (',
'        cod_item,        data,            qtd_horas,',
'        matricula,       cod_empresa,     cod_evento,',
'        id_apuracao,     posicao,         tipo_evento,',
'        complemento,     bh_apurado,      trava_apuracao,',
'        usuario,         dt_atualizacao,  cod_req',
'    ) VALUES (',
'        v_novo_cod_item,',
'        :DATA,',
'        :QTD_HORAS,',
'        :MATRICULA,',
'        :COD_EMPRESA,',
'        :COD_EVENTO,',
'        1212,                              -- id_apuracao fixo',
'        :POSICAO,',
'        :TIPO_EVENTO,',
'        :COMPLEMENTO,',
'        ''A'',                               -- bh_apurado inicial',
'        ''S'',                               -- trava_apuracao = S',
'        NVL(:APP_USER, USER),',
'        SYSDATE,',
unistr('        v_cod_req_novo                     -- requisi\00E7\00E3o (NULL se n\00E3o existir)'),
'    );',
'',
'    prc_log_resultado_apuracao(',
'        p_operacao         => ''I'',',
'        p_usuario          => NVL(:APP_USER, USER),',
'        p_cod_item         => v_novo_cod_item,',
'        p_matricula        => :MATRICULA,',
'        p_cod_empresa      => :COD_EMPRESA,',
'        p_id_apuracao      => 1212,',
'        -- OLD: NULL (linha nova, sem estado anterior)',
'        p_data_old         => NULL,',
'        p_qtd_horas_old    => NULL,',
'        p_cod_evento_old   => NULL,',
'        p_tipo_evento_old  => NULL,',
'        p_posicao_old      => NULL,',
'        p_bh_apurado_old   => NULL,',
'        p_complemento_old  => NULL,',
'        -- NEW: valores inseridos',
'        p_data_new         => :DATA,',
'        p_qtd_horas_new    => :QTD_HORAS,',
'        p_cod_evento_new   => :COD_EVENTO,',
'        p_tipo_evento_new  => :TIPO_EVENTO,',
'        p_posicao_new      => :POSICAO,',
'        p_bh_apurado_new   => ''A'',',
'        p_complemento_new  => :COMPLEMENTO,',
'        --',
unistr('        p_cod_req          => v_cod_req_novo,   -- registra no log a requisi\00E7\00E3o vinculada'),
'        p_cod_req_2        => NULL,',
'        p_usuario_original => NULL,',
'        p_dt_atu_original  => NULL);',
'',
'  ----------------------------------------------------------------',
'  ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'  ----------------------------------------------------------------',
'    DELETE FROM pe_resultado_apuracao',
'     WHERE cod_item    = :COD_ITEM',
'       AND matricula   = :MATRICULA',
'       AND cod_empresa = :COD_EMPRESA',
'       AND id_apuracao = :ID_APURACAO',
'       AND cod_req     IS NULL',
'       AND cod_req_2   IS NULL',
'    RETURNING data, qtd_horas, cod_evento, tipo_evento, posicao,',
'              bh_apurado, complemento, cod_req, cod_req_2,',
'              usuario, dt_atualizacao',
'         INTO v_data, v_qtd_horas, v_cod_evento, v_tipo_evento, v_posicao,',
'              v_bh_apurado, v_complemento, v_cod_req, v_cod_req_2,',
'              v_usuario, v_dt_atu;',
'',
'    IF SQL%ROWCOUNT > 0 THEN',
'      prc_log_resultado_apuracao(',
'          p_operacao         => ''D'',',
'          p_usuario          => NVL(:APP_USER, USER),',
'          p_cod_item         => :COD_ITEM,',
'          p_matricula        => :MATRICULA,',
'          p_cod_empresa      => :COD_EMPRESA,',
'          p_id_apuracao      => :ID_APURACAO,',
'          -- OLD: snapshot via RETURNING',
'          p_data_old         => v_data,',
'          p_qtd_horas_old    => v_qtd_horas,',
'          p_cod_evento_old   => v_cod_evento,',
'          p_tipo_evento_old  => v_tipo_evento,',
'          p_posicao_old      => v_posicao,',
'          p_bh_apurado_old   => v_bh_apurado,',
'          p_complemento_old  => v_complemento,',
'          -- NEW: deixa default NULL (linha foi apagada)',
'          p_cod_req          => v_cod_req,',
'          p_cod_req_2        => v_cod_req_2,',
'          p_usuario_original => v_usuario,',
'          p_dt_atu_original  => v_dt_atu);',
'    ELSE',
'      SELECT COUNT(*),',
'             SUM(CASE WHEN cod_req IS NOT NULL OR cod_req_2 IS NOT NULL THEN 1 ELSE 0 END)',
'        INTO v_existe, v_tem_req',
'        FROM pe_resultado_apuracao',
'       WHERE cod_item    = :COD_ITEM',
'         AND matricula   = :MATRICULA',
'         AND cod_empresa = :COD_EMPRESA',
'         AND id_apuracao = :ID_APURACAO;',
'',
'      IF v_existe = 0 THEN',
'        apex_error.add_error(',
unistr('          p_message => ''Exclus\00E3o falhou: registro n\00E3o encontrado (PK: '''),
'                       || :COD_ITEM || ''/'' || :MATRICULA || ''/''',
'                       || :COD_EMPRESA || ''/'' || :ID_APURACAO || '').'',',
'          p_display_location => apex_error.c_inline_in_notification);',
'      ELSIF NVL(v_tem_req,0) > 0 THEN',
'        apex_error.add_error(',
unistr('          p_message => ''Exclus\00E3o bloqueada: registro possui requisi\00E7\00E3o (COD_REQ/COD_REQ_2).'','),
'          p_display_location => apex_error.c_inline_in_notification);',
'      ELSE',
'        apex_error.add_error(',
unistr('          p_message => ''Exclus\00E3o n\00E3o realizada por motivo desconhecido.'','),
'          p_display_location => apex_error.c_inline_in_notification);',
'      END IF;',
'    END IF;',
'  END IF;',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    apex_error.add_error(',
'      p_message => ''Erro Oracle: '' || SQLERRM',
'                   || '' (PK: '' || :COD_ITEM || ''/'' || :MATRICULA || ''/''',
'                   || :COD_EMPRESA || ''/'' || :ID_APURACAO || '')'',',
'      p_display_location => apex_error.c_inline_in_notification);',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
/
