wwv_flow_api.create_page(
 p_id=>230
,p_user_interface_id=>wwv_flow_api.id(209353596631966209865)
,p_name=>unistr('Ajuste de Marca\00E7\00F5es de Ponto ')
,p_step_title=>unistr('Ajuste de Marca\00E7\00F5es de Ponto')
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'ON'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*****************************************/',
'/*  MASCARA DE TODOS OS CAMPOS DE HORA   */',
'/*****************************************/',
'function aplicaMascaraHora(value) {',
'    var digits = value.replace(/\D/g, '''').substring(0, 4);',
'    return digits.length <= 2 ? digits : digits.substring(0, 2) + '':'' + digits.substring(2);',
'}',
'',
'function bindMascaraInput($input) {',
'    $input.off(''keypress.maskHora input.maskHora'');',
'',
'    $input.on(''keypress.maskHora'', function(e) {',
'        var charCode = e.which || e.keyCode;',
'        var charTyped = String.fromCharCode(charCode);',
'',
unistr('        // Permite apenas d\00EDgitos (0-9) e dois-pontos (:)'),
'        if (!/[0-9:]/.test(charTyped)) {',
'            e.preventDefault();',
'            return false;',
'        }',
'    });',
'',
'    $input.on(''input.maskHora'', function() {',
'        var cursorPos = this.selectionStart;',
'        var oldValue  = $(this).val();',
'        var newValue  = aplicaMascaraHora(oldValue);',
'',
'        if (oldValue !== newValue) {',
unistr('            // Calcula quantos d\00EDgitos existiam antes do cursor para reposicionar corretamente'),
'            var digitsBeforeCursor = oldValue.substring(0, cursorPos).replace(/\D/g, '''').length;',
'            $(this).val(newValue);',
'',
'            var newPos = digitsBeforeCursor;',
'            if (digitsBeforeCursor > 2) {',
'                newPos = digitsBeforeCursor + 1; // soma 1 pelo ":"',
'            }',
'            this.setSelectionRange(newPos, newPos);',
'        }',
'    });',
'}',
'',
'function inicializaMascaraHoraGrid() {',
'    var container = document.querySelector(''#GRID_ID .a-GV-columnItemContainer'');',
'    if (!container) { return; }',
'',
'    var colunasHora = [''HORA_1'',''HORA_2'',''HORA_3'',''HORA_4'',''HORA_5'',',
'                       ''HORA_6'',''HORA_7'',''HORA_8'',''HORA_9'',''HORA_10''];',
'',
'    var seletores = [];',
'    $(''#GRID_ID .a-GV-headerLabel'').each(function() {',
'        var texto = $(this).text().trim();',
'        if (/^Hora\s+\d{1,2}$/i.test(texto)) {',
'            var spanId = $(this).attr(''id'');',
'            if (spanId) {',
'                var colId = spanId.replace(''_HDR'', '''');',
'                if ($(''#'' + colId).length > 0) {',
'                    seletores.push(''#'' + colId);',
'                }',
'            }',
'        }',
'    });',
'',
'    if (seletores.length === 0) { return; }',
'    var selector = seletores.join('','');',
'',
'    var observer = new MutationObserver(function() {',
'        $(selector).each(function() {',
'            if (!$(this).data(''maskHoraAtiva'')) {',
'                $(this).data(''maskHoraAtiva'', true);',
'                bindMascaraInput($(this));',
'            }',
'        });',
'    });',
'',
'    observer.observe(container, { attributes: true, childList: true, subtree: true });',
'',
'    $(selector).each(function() {',
'        $(this).data(''maskHoraAtiva'', true);',
'        bindMascaraInput($(this));',
'    });',
'}',
'',
'$(window).on(''load'', function() {',
'    setTimeout(inicializaMascaraHoraGrid, 1500);',
'});',
'',
'',
'/*****************************/',
'/*  COLUNAS SOMENTE LEITURA  */',
'/*****************************/',
'',
'',
'function aplicaColunasReadOnly() {',
unistr('    var colunasReadOnly = [''Empresa'', ''Matricula'', ''Data Ponto'', ''Dia'', ''Usu\00E1rio'', ''Data Atualiza\00E7\00E3o''];'),
'',
'    // Descobre os data-idx pelo texto do header',
'    var idxReadOnly = [];',
'    $(''#GRID_ID .a-GV-headerLabel'').each(function() {',
'        var texto = $(this).text().trim();',
'        if (colunasReadOnly.indexOf(texto) >= 0) {',
'            var $th = $(this).closest(''th[data-idx]'');',
'            if ($th.length > 0) {',
'                idxReadOnly.push($th.attr(''data-idx''));',
'            }',
'        }',
'    });',
'',
'    if (idxReadOnly.length === 0) { return; }',
'',
'    function aplicaNasCelulas() {',
'        $.each(idxReadOnly, function(i, idx) {',
'            var $th = $(''#GRID_ID th[data-idx="'' + idx + ''"]'');',
'            var $headerTable = $th.closest(''table'');',
'            var colPos = $headerTable.find(''th[data-idx]'').index($th);',
'            if (colPos < 0) { return; }',
'',
unistr('            // Aplica apenas nas c\00E9lulas de dados, n\00E3o no header'),
'            $(''#GRID_ID .a-GV-w-scroll tbody tr.a-GV-row'').each(function() {',
'                var $cells = $(this).find(''td[role="gridcell"]'');',
'                if ($cells.eq(colPos).length) {',
'                    $cells.eq(colPos)',
'                        .addClass(''col-locked'')',
'                        .css(''pointer-events'', ''none'');',
'                }',
'            });',
'        });',
'    }',
'',
'    aplicaNasCelulas();',
'',
'    // Reaplica quando novas linhas forem renderizadas (scroll virtual)',
'    var container = document.querySelector(''#GRID_ID .a-GV-bdy'');',
'    if (container) {',
'        var observer = new MutationObserver(function() {',
'            aplicaNasCelulas();',
'        });',
'        observer.observe(container, { childList: true, subtree: true });',
'    }',
'}',
'',
'$(window).on(''load'', function() {',
'    setTimeout(function() {',
'        inicializaMascaraHoraGrid();',
'        aplicaColunasReadOnly();',
'    }, 500); // reduzido de 1500 para 500',
'});',
'',
'',
'',
'',
'',
'/*************************************************************/',
unistr('/*  NOTIFICA\00C7\00C3O DE SUCESSO: recarrega a p\00E1gina ao fechar     */'),
'/*************************************************************/',
'$(document).on("click", "button.t-Button--closeAlert", function() {',
'    if ($(this).closest("#NOTIFICATION_MESSAGE, .t-Body-alert").length > 0) {',
'        location.reload();',
'    }',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
