wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(33288162316314587005)
,p_plug_name=>'Grid'
,p_region_name=>'GRID_ID'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--noBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(209353570115087209769)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    b.cod_empresa,',
'    b.matricula,',
'    NVL(b.vira_dia, b.data_ponto)                                                AS data_ponto,   -- << ALTERADO: mostra a data FISICA de inicio da jornada (era NVL(vira_dia,data_ponto))',
'    b.cod_empresa || '' - '' || INITCAP(fnct_nome_empresa(b.cod_empresa))            AS empresa,',
'    b.matricula   || '' - '' || INITCAP(fnct_nome_func(b.cod_empresa, b.matricula))  AS matricula_nome,',
'    -- << ALTERADO: coluna Dia agora calcula pela data fisica MIN(data_ponto), consistente com a coluna Data Ponto (era NVL(vira_dia,data_ponto))',
'    DECODE(',
'        Fnct_Pe_Retorna_Situacao(b.cod_empresa, b.matricula, NVL(b.vira_dia, b.data_ponto)),',
'        NULL,',
'        DECODE(',
'            NVL(pkg_pe_abono.RETORNA_FOLGA_FERIADO(b.cod_empresa, b.matricula, NVL(b.vira_dia, b.data_ponto)), NULL),',
'            NULL, TO_CHAR(NVL(b.vira_dia, b.data_ponto), ''dy''),',
'            TO_CHAR(NVL(b.vira_dia, b.data_ponto), ''dy'') || '' - '' || pkg_pe_abono.RETORNA_FOLGA_FERIADO(b.cod_empresa, b.matricula, NVL(b.vira_dia, b.data_ponto))',
'        ),',
'        SUBSTR(Fnct_Pe_Retorna_Situacao(b.cod_empresa, b.matricula, NVL(b.vira_dia, b.data_ponto)), 1, 20)',
'    ) AS dia,',
'    COALESCE(',
'        MAX(CASE WHEN b.posicao = 1 THEN TO_CHAR(b.vira_dia, ''DD/MM/RRRR'') END),',
'        MAX(CASE WHEN b.posicao = 2 THEN TO_CHAR(b.vira_dia, ''DD/MM/RRRR'') END)',
'    ) AS vira_dia,',
'    MAX(b.plantao)                                                                  AS plantao,',
'    MAX(CASE WHEN b.posicao = 1 THEN b.cod_justificativa END)                      AS justificativa,',
'    MAX(CASE WHEN b.posicao = 1  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_1,',
'    MAX(CASE WHEN b.posicao = 2  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_2,',
'    MAX(CASE WHEN b.posicao = 3  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_3,',
'    MAX(CASE WHEN b.posicao = 4  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_4,',
'    MAX(CASE WHEN b.posicao = 5  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_5,',
'    MAX(CASE WHEN b.posicao = 6  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_6,',
'    MAX(CASE WHEN b.posicao = 7  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_7,',
'    MAX(CASE WHEN b.posicao = 8  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_8,',
'    MAX(CASE WHEN b.posicao = 9  THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_9,',
'    MAX(CASE WHEN b.posicao = 10 THEN TO_CHAR(NVL(b.hora_batida_abono, b.hora_batida), ''HH24:MI'') END) AS hora_10,',
'    MAX(b.usuario)        AS usuario,',
'    MAX(b.dt_atualizacao) AS dt_atualizacao',
'FROM (',
'    /*',
'     * BLOCO 1 - Registros do proprio dia',
'     * Traz todas as posicoes cuja data_ponto esta dentro do periodo filtrado.',
'     * Inclui tambem posicoes com vira_dia preenchido que ainda caem dentro do filtro',
'     * pelo NVL(vira_dia, data_ponto) na condicao FORA.',
'     * O GROUP BY externo usa NVL(vira_dia, data_ponto), entao:',
'     *   - Posicao sem vira_dia  -> agrupa pela data_ponto (dia normal)',
'     *   - Posicao com vira_dia  -> agrupa pelo vira_dia  (pertence a jornada desse dia)',
'     */',
'    SELECT cod_empresa, matricula, data_ponto, hora_batida, hora_batida_abono,',
'           posicao, cod_justificativa, plantao, vira_dia, usuario, dt_atualizacao',
'    FROM pe_tratamento_batimentos',
'    WHERE (:P230_EMPRESA   IS NULL OR cod_empresa IN (SELECT /*+ cardinality(t 1)*/ column_value FROM TABLE(apex_string.split(:P230_EMPRESA,   '','')) t))',
'      AND (:P230_MATRICULA IS NULL OR matricula   IN (SELECT /*+ cardinality(t 1)*/ column_value FROM TABLE(apex_string.split(:P230_MATRICULA, '','')) t))',
'   ',
'      AND (',
'            (:P230_TIPO_PERIODO = ''DENTRO''',
'             AND data_ponto BETWEEN TO_DATE(:P230_DT_INI, ''DD/MM/RRRR'')',
'                                AND TO_DATE(:P230_DT_FIM, ''DD/MM/RRRR''))',
'            OR',
'            (:P230_TIPO_PERIODO = ''FORA''',
'             AND NVL(vira_dia, data_ponto) BETWEEN TO_DATE(:P230_DT_INI, ''DD/MM/RRRR'')',
'                                               AND TO_DATE(:P230_DT_FIM, ''DD/MM/RRRR''))',
'          )',
'',
'    UNION ALL',
'',
'    /*',
'     * BLOCO 2 - Registros de jornada noturna que cruzaram a meia-noite',
'     * Problema: uma jornada que comeca em 31/05 e termina em 01/06 as 07:00',
'     * tem data_ponto = 01/06 mas vira_dia = 31/05.',
'     * O BLOCO 1 filtra por data_ponto, entao a posicao das 07:00 (data_ponto = 01/06)',
'     * nao seria trazida quando o filtro e ate 31/05.',
'     * Este bloco resolve isso: busca posicoes cujo vira_dia esta dentro do periodo,',
'     * independente da data_ponto fisica.',
'     * Assim, a posicao das 07:00 entra aqui e o GROUP BY externo a agrupa',
'     * junto com as demais posicoes do dia 31/05 pelo NVL(vira_dia, data_ponto).',
'     * Filtro vira_dia != data_ponto evita duplicar registros do BLOCO 1.',
'     */',
'    SELECT cod_empresa, matricula, data_ponto, hora_batida, hora_batida_abono,',
'           posicao, cod_justificativa, plantao, vira_dia, usuario, dt_atualizacao',
'    FROM pe_tratamento_batimentos',
'    WHERE (:P230_EMPRESA   IS NULL OR cod_empresa IN (SELECT /*+ cardinality(t 1)*/ column_value FROM TABLE(apex_string.split(:P230_EMPRESA,   '','')) t))',
'      AND (:P230_MATRICULA IS NULL OR matricula   IN (SELECT /*+ cardinality(t 1)*/ column_value FROM TABLE(apex_string.split(:P230_MATRICULA, '','')) t))',
'      AND vira_dia IS NOT NULL',
'      AND vira_dia != data_ponto',
'      AND (',
'            (:P230_TIPO_PERIODO = ''DENTRO''',
'             AND vira_dia BETWEEN TO_DATE(:P230_DT_INI, ''DD/MM/RRRR'')',
'                              AND TO_DATE(:P230_DT_FIM, ''DD/MM/RRRR''))',
'            OR',
'            (:P230_TIPO_PERIODO = ''FORA''',
'             AND vira_dia BETWEEN TO_DATE(:P230_DT_INI, ''DD/MM/RRRR'')',
'                              AND TO_DATE(:P230_DT_FIM, ''DD/MM/RRRR''))',
'          )',
') b',
'GROUP BY',
'    b.cod_empresa,',
'    b.matricula,',
'    NVL(b.vira_dia, b.data_ponto),',
'    fnct_nome_empresa(b.cod_empresa),',
'    fnct_nome_func(b.cod_empresa, b.matricula)'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P230_EMPRESA,P230_MATRICULA,P230_DT_INI,P230_DT_FIM,P230_USUARIO'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
