wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(33288240123652529202)
,p_name=>'P230_EVENTO'
,p_item_sequence=>120
,p_item_plug_id=>wwv_flow_api.id(215761772438562692467)
,p_prompt=>'EVENTO'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT',
'       TO_CHAR(a.cod_evento) || '' - '' ||',
'       CASE',
'         WHEN a.tipo_evento = ''BANCO'' THEN eb.descricao',
'         WHEN a.tipo_evento = ''PONTO'' THEN ef.descricao',
'       END d,',
'       TO_CHAR(a.cod_evento) r',
'FROM pe_resultado_apuracao a',
'LEFT JOIN pe_eventos_banco eb',
'       ON a.tipo_evento = ''BANCO''',
'      AND eb.cod_empresa = a.cod_empresa',
'      AND eb.cod_evento_banco = a.cod_evento',
'LEFT JOIN pe_eventos_folha ef',
'       ON a.tipo_evento = ''PONTO''',
'      AND ef.cod_empresa = a.cod_empresa',
'      AND ef.cod_evento_folha = a.cod_evento',
'WHERE (:P230_DT_INI IS NULL OR a.data >= :P230_DT_INI)',
'  AND (:P230_DT_FIM IS NULL OR a.data <= :P230_DT_FIM)',
'',
'  AND (',
'      :P230_EMPRESA IS NULL',
'      OR a.cod_empresa IN (',
'            SELECT TO_NUMBER(TRIM(column_value))',
'            FROM TABLE(apex_string.split(:P230_EMPRESA, '',''))',
'            WHERE REGEXP_LIKE(column_value, ''^\d+$'')',
'      )',
'  )',
'',
'  AND (',
'      :P230_MATRICULA IS NULL',
'      OR a.matricula IN (',
'            SELECT TO_NUMBER(column_value)',
'            FROM TABLE(apex_string.split(:P230_MATRICULA, '',''))',
'      )',
'  )',
'',
'  AND (',
'        :P230_TIPO_PERIODO IS NULL',
'',
'        OR (',
'             :P230_TIPO_PERIODO = ''DENTRO''',
'             AND EXISTS (',
'                    SELECT 1',
'                      FROM parametros_recursos_humanos b',
'                     WHERE b.cod_empresa = a.cod_empresa',
'                       AND a.data BETWEEN b.data_ini_ref_ponto',
'                                      AND b.data_fim_ref_ponto',
'             )',
'           )',
'',
'        OR (',
'             :P230_TIPO_PERIODO = ''FORA''',
'             AND EXISTS (',
'                    SELECT 1',
'                      FROM parametros_recursos_humanos b',
'                     WHERE b.cod_empresa = a.cod_empresa',
'                       AND a.dt_atualizacao < b.data_ini_ref_ponto',
'             )',
'           )',
'      )',
'',
'  AND (',
'      :P230_TIPO_EVENTO IS NULL',
'      OR a.tipo_evento IN (',
'            SELECT TRIM(column_value)',
'            FROM TABLE(apex_string.split(:P230_TIPO_EVENTO, '',''))',
'      )',
'  )',
'',
'ORDER BY 1;'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- TODOS -'
,p_lov_cascade_parent_items=>'P230_EMPRESA,P230_TIPO_EVENTO'
,p_ajax_items_to_submit=>'P230_EMPRESA,P230_TIPO_EVENTO,P230_DT_INI,P230_DT_FIM'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>30
,p_display_when_type=>'NEVER'
,p_field_template=>wwv_flow_api.id(200038886480471188975)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'DIALOG'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
,p_attribute_07=>'Evento'
,p_attribute_08=>'500'
,p_item_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT TO_CHAR(eb.cod_evento_banco) || '' - '' || eb.descricao d,',
'       TO_CHAR(eb.cod_evento_banco)                          r',
'  FROM pe_eventos_banco eb',
' WHERE eb.cod_empresa = :P230_EMPRESA',
'   AND (:P230_TIPO_EVENTO IS NULL OR :P230_TIPO_EVENTO = ''BANCO'')',
