wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(24785636591109807030)
,p_tabular_form_region_id=>wwv_flow_api.id(33288162316314587005)
,p_validation_name=>'Novo'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_emp   NUMBER := :COD_EMPRESA;',
'    v_mat   NUMBER := :MATRICULA;',
'    v_data  DATE   := :DATA_PONTO;',
'',
'    TYPE t_arr IS TABLE OF VARCHAR2(5);',
'    v_sub t_arr := t_arr(:HORA_1, :HORA_2, :HORA_3, :HORA_4, :HORA_5,',
'                         :HORA_6, :HORA_7, :HORA_8, :HORA_9, :HORA_10);',
'',
'    v_new        VARCHAR2(5);',
'    v_old        VARCHAR2(5);',
'    v_tem_dado   BOOLEAN := FALSE;   -- sobrou alguma hora preenchida?',
'    v_mudou      BOOLEAN := FALSE;   -- houve diferenca em relacao ao banco?',
'BEGIN',
'    FOR p IN 1..10 LOOP',
'        v_new := NULLIF(TRIM(v_sub(p)), '''');',
'',
'        IF v_new IS NOT NULL THEN',
'            v_tem_dado := TRUE;',
'        END IF;',
'',
'        -- valor atual no banco nesta posicao (mesma exibicao do grid)',
'        SELECT MAX(TO_CHAR(NVL(hora_batida_abono, hora_batida), ''HH24:MI''))',
'        INTO   v_old',
'        FROM   pe_tratamento_batimentos',
'        WHERE  cod_empresa = v_emp',
'        AND    matricula   = v_mat',
'        AND    data_ponto  = v_data',
'        AND    posicao     = p;',
'',
'        IF NVL(v_new, ''#'') <> NVL(v_old, ''#'') THEN',
'            v_mudou := TRUE;',
'        END IF;',
'    END LOOP;',
'',
'    -- So exige justificativa se sobrou dado E algo mudou.',
'    -- Limpar tudo (sem dado) ou nao mexer em nada -> nao exige.',
'    IF v_tem_dado AND v_mudou AND :JUSTIFICATIVA IS NULL THEN',
unistr('        RETURN ''Informe a Justificativa: a linha tem marca\00E7\00E3o de ponto inclu\00EDda ou alterada.'';'),
'    END IF;',
'',
'    RETURN NULL;',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_associated_column=>'JUSTIFICATIVA'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
