wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(33288164481561587027)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_api.id(33288162316314587005)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Processamento Grid'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
unistr('    -- Vari\00E1veis principais da linha editada no grid'),
'    v_emp      NUMBER := :COD_EMPRESA;',
'    v_mat      NUMBER := :MATRICULA;',
'    v_data     DATE   := :DATA_PONTO;',
'',
unistr('    -- Vari\00E1veis auxiliares'),
'    v_hora              DATE;',
'    v_vira_dia          DATE;',
'    v_dt_pos2           DATE;   -- dia FISICO onde a posicao 2 deve ficar',
'    v_next_id           NUMBER;',
'    v_filial            NUMBER;',
'    v_houve_alteracao   BOOLEAN := FALSE;',
'',
'    TYPE t_snapshot IS RECORD (',
'        posicao             NUMBER,',
'        hora_batida_abono   DATE,',
'        hora_batida         DATE,',
'        vira_dia            DATE,',
'        plantao             VARCHAR2(3),',
'        cod_justificativa   NUMBER,',
'        usuario             VARCHAR2(30),',
'        dt_atualizacao      DATE',
'    );',
'    TYPE t_snapshot_tab IS TABLE OF t_snapshot INDEX BY PLS_INTEGER;',
'    v_old t_snapshot_tab;',
'    v_idx PLS_INTEGER := 0;',
'',
'BEGIN',
'  /*==========================================================================',
unistr('     * BLOCO 1 - CONFIGURA\00C7\00D5ES INICIAIS'),
'     *==========================================================================*/',
'    IF INSTR(1/2, '','') > 0 THEN',
'        EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS=''''.,'''''';',
'    END IF;',
'',
'    BEGIN',
'        SELECT filial',
'        INTO   v_filial',
'        FROM   informacoes_funcionais',
'        WHERE  matricula   = v_mat',
'        AND    cod_empresa = v_emp',
'        AND    ROWNUM      = 1;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_filial := NULL;',
'    END;',
'',
'    /*==========================================================================',
unistr('     * BLOCO 2 - SNAPSHOT ANTES DAS ALTERA\00C7\00D5ES'),
unistr('     * Inclui hora_batida para compara\00E7\00E3o correta no log'),
'     *==========================================================================*/',
'    FOR r IN (',
'        SELECT posicao, hora_batida_abono, hora_batida, vira_dia,',
'               plantao, cod_justificativa, usuario, dt_atualizacao',
'        FROM   pe_tratamento_batimentos',
'        WHERE  cod_empresa = v_emp',
'        AND    matricula   = v_mat',
'        AND    NVL(vira_dia, data_ponto) = v_data',
'        ORDER BY posicao',
'    ) LOOP',
'        v_idx := v_idx + 1;',
'        v_old(v_idx).posicao           := r.posicao;',
'        v_old(v_idx).hora_batida_abono := r.hora_batida_abono;',
'        v_old(v_idx).hora_batida       := r.hora_batida;',
'        v_old(v_idx).vira_dia          := r.vira_dia;',
'        v_old(v_idx).plantao           := r.plantao;',
'        v_old(v_idx).cod_justificativa := r.cod_justificativa;',
'        v_old(v_idx).usuario           := r.usuario;',
'        v_old(v_idx).dt_atualizacao    := r.dt_atualizacao;',
'    END LOOP;',
'',
'    /*==========================================================================',
unistr('     * BLOCO 3 - PLANT\00C3O'),
'     *==========================================================================*/',
'    UPDATE pe_tratamento_batimentos',
'    SET    plantao        = :PLANTAO,',
'           usuario        = :P230_USUARIO,',
'           dt_atualizacao = SYSDATE',
'    WHERE  cod_empresa = v_emp',
'    AND    matricula   = v_mat',
'    AND    NVL(vira_dia, data_ponto) = v_data;',
'',
'    /*==========================================================================',
unistr('     * BLOCO 4 - C\00C1LCULO DO VIRA_DIA'),
'     *==========================================================================*/',
'   /*==========================================================================',
'     * BLOCO 4 - VIRA_DIA (automatico pelas horas OU manual pelo usuario)',
'     *   - Usuario NAO mexeu na coluna Vira Dia (grid == exibido) -> recalcula',
'     *     automaticamente pelas horas (comportamento antigo).',
'     *   - Usuario DIGITOU uma data OU APAGOU a coluna (grid != exibido) ->',
'     *     respeita exatamente o que ele fez.',
'     *==========================================================================*/',
'    DECLARE',
'        v_vira_pos1  DATE;           -- vira_dia gravado hoje na posicao 1',
'        v_old_txt    VARCHAR2(10);   -- valor que o grid ESTAVA exibindo (COALESCE pos1/pos2)',
'        v_sub_txt    VARCHAR2(10);   -- valor que voltou do grid',
'        v_editou_mao BOOLEAN;',
'    BEGIN',
'        -- reproduz a MESMA logica COALESCE(pos1, pos2) da query da regiao,',
'        -- pra comparar contra o que o usuario viu na tela',
'        SELECT MAX(CASE WHEN posicao = 1 THEN vira_dia END),',
'               TO_CHAR(COALESCE(',
'                   MAX(CASE WHEN posicao = 1 THEN vira_dia END),',
'                   MAX(CASE WHEN posicao = 2 THEN vira_dia END)',
'               ), ''DD/MM/RRRR'')',
'        INTO   v_vira_pos1, v_old_txt',
'        FROM   pe_tratamento_batimentos',
'        WHERE  cod_empresa = v_emp',
'        AND    matricula   = v_mat',
'        AND    NVL(vira_dia, data_ponto) = v_data;',
'',
'        v_sub_txt := TRIM(:VIRA_DIA);',
'',
'        -- houve edicao manual se o valor que voltou difere do que estava exibido',
'        v_editou_mao := NVL(v_sub_txt, ''#'') <> NVL(v_old_txt, ''#'');',
'',
'        IF v_editou_mao THEN',
'            ------------------------------------------------------------- MANUAL',
'            IF v_sub_txt IS NULL THEN',
'                v_vira_dia := NULL;                       -- usuario APAGOU',
'            ELSE',
'                BEGIN',
'                    v_vira_dia := TO_DATE(v_sub_txt, ''DD/MM/RRRR'');  -- usuario DIGITOU',
'                EXCEPTION',
'                    WHEN OTHERS THEN',
'                        RAISE_APPLICATION_ERROR(-20010,',
'                            ''Vira Dia invalido: "'' || v_sub_txt ||',
'                            ''". Use o formato DD/MM/AAAA.'');',
'                END;',
'            END IF;',
'        ELSE',
'            --------------------------------------------------------- AUTOMATICO',
'            IF TRIM(:HORA_1) IS NOT NULL AND TRIM(:HORA_2) IS NOT NULL THEN',
'                IF TO_DATE(:HORA_2, ''HH24:MI'') > TO_DATE(:HORA_1, ''HH24:MI'') THEN',
'                    v_vira_dia := NULL;',
'                ELSE',
'                    v_vira_dia := v_data;',
'                END IF;',
'            ELSIF TRIM(:HORA_1) IS NOT NULL AND TRIM(:HORA_2) IS NULL THEN',
'                v_vira_dia := v_vira_pos1;                 -- mantem o que ja tinha',
'            ELSE',
'                v_vira_dia := NULL;',
'            END IF;',
'        END IF;',
'    END;',
'',
'    /*--------------------------------------------------------------------------',
'     * Dia FISICO da posicao 2:',
'     *   - com virada -> vira_dia + 1  (as duas datas nunca ficam iguais)',
'     *   - sem virada -> o proprio dia da jornada',
'     *------------------------------------------------------------------------*/',
'    v_dt_pos2 := CASE WHEN v_vira_dia IS NOT NULL THEN v_vira_dia + 1 ELSE v_data END;',
'',
'    /*==========================================================================',
unistr('     * BLOCO 5 - JUSTIFICATIVA E VIRA_DIA (somente posi\00E7\00E3o 1)'),
'     *==========================================================================*/',
'  -- Justificativa continua apenas na posicao 1',
'    UPDATE pe_tratamento_batimentos',
'    SET    cod_justificativa = :JUSTIFICATIVA,',
'           usuario           = :P230_USUARIO,',
'           dt_atualizacao    = SYSDATE',
'    WHERE  cod_empresa = v_emp',
'    AND    matricula   = v_mat',
'    AND    NVL(vira_dia, data_ponto) = v_data',
'    AND    posicao     = 1;',
'',
'    /*==========================================================================',
unistr('     * BLOCO 6 - HORAS POR POSI\00C7\00C3O (1 a 10)'),
'     * Regra ao limpar (bind NULL):',
'     *   - Se hora_batida_abono existe no banco: limpa hora_batida_abono',
unistr('     *   - Se hora_batida_abono \00E9 NULL no banco:  limpa hora_batida'),
'     * Regra ao digitar (bind com valor):',
'     *   - Grava em hora_batida_abono normalmente',
unistr('     *   - Se n\00E3o existe a posi\00E7\00E3o: faz INSERT'),
'     *==========================================================================*/',
'',
unistr('    -- Posi\00E7\00E3o 1'),
'    v_hora := CASE WHEN TRIM(:HORA_1) IS NULL THEN NULL',
'                   ELSE TO_DATE(TO_CHAR(v_data,''DD/MM/RRRR'')||'' ''||:HORA_1,''DD/MM/RRRR HH24:MI'') END;',
'',
'    IF v_hora IS NULL THEN',
'        UPDATE pe_tratamento_batimentos',
'        SET    hora_batida_abono = CASE WHEN hora_batida_abono IS NOT NULL THEN NULL ELSE hora_batida_abono END,',
'               hora_batida       = CASE WHEN hora_batida_abono IS NOT NULL THEN hora_batida ELSE NULL END,',
'               usuario           = :P230_USUARIO,',
'               dt_atualizacao    = SYSDATE',
'        WHERE  cod_empresa = v_emp AND matricula = v_mat AND NVL(vira_dia, data_ponto) = v_data AND posicao = 1;',
'    ELSE',
'        UPDATE pe_tratamento_batimentos',
'        SET    hora_batida_abono = v_hora,',
'               usuario           = :P230_USUARIO,',
'               dt_atualizacao    = SYSDATE',
'        WHERE  cod_empresa = v_emp AND matricula = v_mat AND NVL(vira_dia, data_ponto) = v_data AND posicao = 1;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            LOCK TABLE pe_tratamento_batimentos IN EXCLUSIVE MODE;',
'            SELECT NVL(MAX(cod_trat_bat), 0) + 1 INTO v_next_id FROM pe_tratamento_batimentos;',
'            INSERT INTO pe_tratamento_batimentos',
'                (cod_trat_bat, cod_empresa, matricula, data_ponto, posicao, hora_batida_abono,',
'                 cod_justificativa, plantao, vira_dia, usuario, dt_atualizacao,',
'                 foi_tratado, data_processamento, cod_importacao, origem)',
'            VALUES',
'                (v_next_id, v_emp, v_mat, v_data, 1, v_hora,',
'                 :JUSTIFICATIVA, :PLANTAO, NULL, :P230_USUARIO, SYSDATE,',
'                 0, SYSDATE, 0, ''M'');   -- ALTERADO: posicao 1 nunca recebe vira_dia',
'        END IF;',
'    END IF;',
'',
unistr('    -- Posi\00E7\00E3o 2 (a unica que pode mudar de dia)'),
'    v_hora := CASE WHEN TRIM(:HORA_2) IS NULL THEN NULL',
'                   ELSE TO_DATE(TO_CHAR(v_dt_pos2,''DD/MM/RRRR'')||'' ''||:HORA_2,''DD/MM/RRRR HH24:MI'') END;',
'',
'    IF v_hora IS NULL THEN',
'        UPDATE pe_tratamento_batimentos',
'        SET    hora_batida_abono = CASE WHEN hora_batida_abono IS NOT NULL THEN NULL ELSE hora_batida_abono END,',
'               hora_batida       = CASE WHEN hora_batida_abono IS NOT NULL THEN hora_batida ELSE NULL END,',
'               usuario           = :P230_USUARIO,',
'               dt_atualizacao    = SYSDATE',
'        WHERE  cod_empresa = v_emp AND matricula = v_mat AND NVL(vira_dia, data_ponto) = v_data AND posicao = 2;',
'    ELSE',
'        UPDATE pe_tratamento_batimentos',
'        SET    hora_batida_abono = v_hora,',
'               usuario           = :P230_USUARIO,',
'               dt_atualizacao    = SYSDATE',
'        WHERE  cod_empresa = v_emp AND matricula = v_mat AND NVL(vira_dia, data_ponto) = v_data AND posicao = 2;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
