'    ',
'    ',
'    /*==========================================================================',
'     * BLOCO 6.1 - VIRA_DIA somente na POSICAO 2',
'     * A posicao 1 (entrada) nunca recebe vira_dia. Somente a posicao 2 (saida)',
'     * marca que a jornada cruzou a meia-noite.',
'     * Roda DEPOIS do BLOCO 6 para pegar tambem posicoes recem-inseridas.',
'     *==========================================================================*/',
'    -- limpa o vira_dia de todas as posicoes que NAO sejam a 2',
'    -- (tambem corrige residuo antigo que estiver na posicao 1)',
'    UPDATE pe_tratamento_batimentos',
'    SET    vira_dia       = NULL,',
'           usuario        = :P230_USUARIO,',
'           dt_atualizacao = SYSDATE',
'    WHERE  cod_empresa = v_emp',
'    AND    matricula   = v_mat',
'    AND    NVL(vira_dia, data_ponto) = v_data',
'    AND    posicao    <> 2',
'    AND    vira_dia IS NOT NULL;',
'',
'    -- posiciona a saida: grava o vira_dia e o dia fisico na posicao 2',
'    UPDATE pe_tratamento_batimentos',
'    SET    data_ponto     = v_dt_pos2,',
'           vira_dia       = v_vira_dia,',
'           usuario        = :P230_USUARIO,',
'           dt_atualizacao = SYSDATE',
'    WHERE  cod_empresa = v_emp',
'    AND    matricula   = v_mat',
'    AND    NVL(vira_dia, data_ponto) = v_data',
'    AND    posicao     = 2;',
'',
'    /*==========================================================================',
'     * BLOCO 7 - LOG DE AUDITORIA',
'     * Compara snapshot OLD com estado atual NEW',
unistr('     * Detecta mudan\00E7a em hora_batida_abono OU hora_batida (ambos monitorados)'),
'     *==========================================================================*/',
'    FOR r IN (',
'        SELECT posicao, hora_batida_abono, hora_batida, vira_dia,',
'               plantao, cod_justificativa, usuario, dt_atualizacao',
'        FROM   pe_tratamento_batimentos',
'        WHERE  cod_empresa = v_emp',
'        AND    matricula   = v_mat',
'        AND    NVL(vira_dia, data_ponto) = v_data',
'        ORDER BY posicao',
'    ) LOOP',
'        DECLARE',
'            v_old_rec t_snapshot;',
'            v_mudou   BOOLEAN := FALSE;',
'        BEGIN',
'            v_old_rec := NULL;',
'',
'            FOR i IN 1..v_old.COUNT LOOP',
'                IF v_old(i).posicao = r.posicao THEN',
'                    v_old_rec := v_old(i);',
'                    EXIT;',
'                END IF;',
'            END LOOP;',
'',
'            IF NVL(TO_CHAR(v_old_rec.hora_batida_abono,''HH24:MI''), ''#'')',
'                != NVL(TO_CHAR(r.hora_batida_abono,''HH24:MI''), ''#'')',
'            OR NVL(TO_CHAR(v_old_rec.hora_batida,''HH24:MI''), ''#'')',
'                != NVL(TO_CHAR(r.hora_batida,''HH24:MI''), ''#'')',
'            OR NVL(TO_CHAR(v_old_rec.vira_dia,''DD/MM/RRRR''), ''#'')',
'                != NVL(TO_CHAR(r.vira_dia,''DD/MM/RRRR''), ''#'')',
'            OR NVL(v_old_rec.plantao, ''#'')',
'                != NVL(r.plantao, ''#'')',
'            OR NVL(TO_CHAR(v_old_rec.cod_justificativa), ''#'')',
'                != NVL(TO_CHAR(r.cod_justificativa), ''#'')',
'            THEN',
'                v_mudou := TRUE;',
'            END IF;',
'',
'            IF v_old_rec.posicao IS NULL AND r.hora_batida_abono IS NOT NULL THEN',
'                v_mudou := TRUE;',
'            END IF;',
'',
'            IF v_mudou THEN',
'                v_houve_alteracao := TRUE;',
'',
'                INSERT INTO log_pe_tratamento_batimentos (',
'                    log_data, log_usuario,',
'                    cod_empresa, matricula, data_ponto, posicao,',
'                    hora_batida_abono_old, vira_dia_old, plantao_old, cod_justificativa_old,',
'                    usuario_old, dt_atualizacao_old,',
'                    hora_batida_abono_new, vira_dia_new, plantao_new, cod_justificativa_new',
'                ) VALUES (',
'                    SYSDATE, :P230_USUARIO,',
'                    v_emp, v_mat, v_data, r.posicao,',
'                    v_old_rec.hora_batida_abono, v_old_rec.vira_dia,',
'                    v_old_rec.plantao, v_old_rec.cod_justificativa,',
'                    v_old_rec.usuario, v_old_rec.dt_atualizacao,',
'                    r.hora_batida_abono, r.vira_dia,',
'                    r.plantao, r.cod_justificativa',
'                );',
'            END IF;',
'        END;',
'    END LOOP;',
'',
'    /*==========================================================================',
unistr('     * BLOCO 8 - REAPURA\00C7\00C3O DE PONTO'),
'     *==========================================================================*/',
'    COMMIT; -- Garante dados gravados antes do refresh do IG',
'',
'    IF v_houve_alteracao THEN',
'        DECLARE',
'            p_erro VARCHAR2(4000);',
'        BEGIN',
'            PKG_APURACAO_PONTO.APURA(',
'                P_EMPRESA        => v_emp,',
'                p_filial_ini     => v_filial,',
'                p_filial_fin     => v_filial,',
'                p_ccusto_ini     => 0,',
'                p_ccusto_fin     => 9999999999,',
'                p_local_ini      => NULL,',
'                p_local_fin      => NULL,',
'                p_grupo_ini      => NULL,',
'                p_grupo_fin      => NULL,',
'                p_matricula_ini  => v_mat,',
'                p_matricula_fin  => v_mat,',
'                P_DATA_INI       => v_data,',
'                p_data_fin       => v_data,',
'                P_id_apuracao    => NULL,',
'                p_erro           => p_erro,',
'                P_USUARIO        => :P230_USUARIO,',
'                P_DT_ATUALIZACAO => SYSDATE,',
'                p_manter_hist    => ''S'',',
'                P_COD_REQ        => NULL,',
'                P_APURA          => NULL',
'            );',
'',
'            IF p_erro IS NOT NULL THEN',
unistr('                RAISE_APPLICATION_ERROR(-20001, ''Erro na reapura\00E7\00E3o: '' || p_erro);'),
'            END IF;',
'        END;',
'    END IF;',
'',
'    /*==========================================================================',
'     * BLOCO 9 - MENSAGEM DE SUCESSO',
'     *==========================================================================*/',
'    IF v_houve_alteracao THEN',
