,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_data  DATE;',
'    v_ini   DATE := TO_DATE(:P232_DT_INI, ''DD/MM/RRRR'');',
'    v_fim   DATE := TO_DATE(:P232_DT_FIM, ''DD/MM/RRRR'');',
'BEGIN',
'    -- data informada precisa ser valida',
'    BEGIN',
'        v_data := TO_DATE(:P232_DATA, ''DD/MM/RRRR'');',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            RETURN ''Data invalida. Use o formato DD/MM/AAAA.'';',
'    END;',
'',
'    -- precisa estar dentro do periodo pesquisado na tela',
'    IF v_ini IS NOT NULL AND v_fim IS NOT NULL',
'       AND v_data NOT BETWEEN v_ini AND v_fim THEN',
'        RETURN ''A data '' || TO_CHAR(v_data, ''DD/MM/RRRR'')',
'               || '' esta fora do periodo pesquisado (''',
'               || TO_CHAR(v_ini, ''DD/MM/RRRR'') || '' a ''',
'               || TO_CHAR(v_fim, ''DD/MM/RRRR'')',
'               || ''). Ajuste o filtro na tela ou informe uma data dentro do periodo.'';',
'    END IF;',
'',
'    RETURN NULL;',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_api.id(21918647867284675732)
,p_associated_item=>wwv_flow_api.id(21918648026868675733)
