'}, 500);'))
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(21918647600393675729)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Processamento'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*==============================================================================',
' * PROCESSO da MODAL 232 - "Incluir Marcacao"',
' * Ponto de execucao: After Submit / Processing',
' * Quando: botao Confirmar (request = ''CRIAR'')',
' *',
' * Objetivo: criar o "esqueleto" de um dia novo na pe_tratamento_batimentos.',
' *   O usuario informa EMPRESA, MATRICULA e DATA. O dia aparece no grid da',
' *   pagina 230 e o restante (horas) e preenchido por la, reaproveitando o',
' *   processo ja existente.',
' *',
' * Itens da pagina 232:',
' *   P232_EMPRESA    - empresa',
' *   P232_MATRICULA  - matricula',
' *   P232_DATA       - data da jornada (dia a ser criado)',
' *============================================================================*/',
'DECLARE',
'    v_emp     NUMBER := :P232_EMPRESA;',
'    v_mat     NUMBER := :P232_MATRICULA;',
'    v_data    DATE   := TO_DATE(:P232_DATA, ''DD/MM/RRRR'');',
'    v_next_id NUMBER;',
'    v_existe  NUMBER;',
'BEGIN',
'',
'    /*--------------------------------------------------------------------------',
'     * 1) VALIDACAO: a data (JORNADA) ja existe para essa matricula?',
'     *    Considera NVL(vira_dia, data_ponto) = dia da jornada, para nao recusar',
'     *    um dia que so tem batida de virada de outra jornada.',
'     *------------------------------------------------------------------------*/',
'    SELECT COUNT(*)',
'    INTO   v_existe',
'    FROM   pe_tratamento_batimentos',
'    WHERE  cod_empresa = v_emp',
'    AND    matricula   = v_mat',
'    AND    NVL(vira_dia, data_ponto) = v_data;',
'',
'    IF v_existe > 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001,',
'            ''Ja existe marcacao para a matricula '' || v_mat ||',
'            '' na data '' || TO_CHAR(v_data, ''DD/MM/RRRR'') ||',
'            ''. Utilize o grid para editar.'');',
'    END IF;',
'',
'    /*--------------------------------------------------------------------------',
'     * 2) VALIDACAO: matricula existe e trabalha na empresa informada?',
'     *------------------------------------------------------------------------*/',
'    SELECT COUNT(*)',
'    INTO   v_existe',
'    FROM   informacoes_funcionais',
'    WHERE  cod_empresa = v_emp',
'    AND    matricula   = v_mat;',
'',
'    IF v_existe = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20002,',
'            ''Matricula '' || v_mat || '' nao encontrada na empresa '' || v_emp || ''.'');',
'    END IF;',
'',
'    /*--------------------------------------------------------------------------',
'     * 3) INSERT do dia (esqueleto) - posicao 1, sem hora',
'     *    Campos cravados conforme modelo (aba Plan1 do xls):',
'     *      foi_tratado=1, foi_apurado=0, origem=''M'', cod_importacao=0,',
'     *      posicao=1, hora vazia. Marca de auditoria: comentarios.',
'     *------------------------------------------------------------------------*/',
'    LOCK TABLE pe_tratamento_batimentos IN EXCLUSIVE MODE;',
'    SELECT NVL(MAX(cod_trat_bat), 0) + 1 INTO v_next_id FROM pe_tratamento_batimentos;',
'',
'    INSERT INTO pe_tratamento_batimentos',
'        (cod_trat_bat, cod_empresa, matricula, data_ponto, posicao,',
'         hora_batida, hora_batida_abono, vira_dia, plantao,',
'         foi_tratado, foi_apurado, data_processamento,',
'         cod_importacao, origem, comentarios,',
'         usuario, dt_atualizacao)',
'    VALUES',
'        (v_next_id, v_emp, v_mat, v_data, 1,',
'         NULL, NULL, NULL, ''N'',',
'         1, 0, SYSDATE,',
'         0, ''M'', ''INSERIDO MANUALMENTE'',',
'         :APP_USER, SYSDATE);',
