'      :P714_NUM_DIAS_JUST := vDias;',
'    END IF;',
'    --',
'    vDataF := TO_DATE(:P714_DATA) + (vDias - 1);',
'    --',
'    IF :P714_DT_FIM_VAL_JUST IS NULL OR :P714_DT_FIM_VAL_JUST <> vDataF THEN',
