'        ',
'        ',
'    }else{',
'            if ($x(''P714_ITEM_VALIDACAO'').value.length == 0){',
'            $x(''P714_OK'').value = ''S'';',
'            }',
'    }',
'    ',
'    if ($x(''P714_ITEM_VALIDACAO'').value == ''P714_CREATE''){',
'            $x(''P714_OK'').value = ''S'';',
'        $x(''P714_ITEM_VALIDACAO'').value = '''';',
'    }',
'',
'}'))
);
