,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    cursor c_req is',
'        SELECT *',
'          FROM pe_req_tratamento_batimentos',
'         WHERE cod_req = :P714_COD_REQ;',
