,p_process_name=>'Define Painel'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
' cursor c_gestor is',
' select distinct ''S'' existe',
'   from apex_programas_acesso',
'  where usuario = :p_usuario',
'    and substr(app_id,1,1) = 1 -- Gestor',
'    and app_page_number <> 1',
'    and acesso = ''S'';',
' ',
' v_gestor c_gestor%rowtype;',
' ',
' cursor c_oper is',
' select distinct ''S'' existe',
'   from apex_programas_acesso',
'  where usuario = :p_usuario',
'    and substr(app_id,1,1) = 2 -- Operador',
'    and app_page_number <> 1',
'    and acesso = ''S'';',
'    ',
' v_oper c_oper%rowtype;',
' ',
'begin',
'',
'open c_gestor;',
'fetch c_gestor into v_gestor;',
'close c_gestor;',
'',
'open c_oper;',
'fetch c_oper into v_oper;',
'close c_oper;',
'',
'if v_gestor.existe = ''S'' and v_oper.existe = ''S'' then',
'--faz pergunta',
'null;',
'elsif v_gestor.existe = ''S'' and nvl(v_oper.existe,''N'') = ''N'' then',
':p_painel := ''PG'';',
'elsif nvl(v_gestor.existe,''N'') = ''N'' and v_oper.existe = ''S'' then',
':p_painel := ''PO'';',
'end if;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
